INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87865, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "空", "is_correct": true, "explanation": "正确。满与空相对，一个指装得很多，一个指里面没有东西。"}, {"text": "亮", "is_correct": false, "explanation": "亮与暗相对，与满没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快与慢相对，与满没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻与重相对，与满没有反义关系。"}], "correct_answer": "空", "explanations": {"空": "正确。满与空相对，一个指装得很多，一个指里面没有东西。", "亮": "亮与暗相对，与满没有反义关系。", "快": "快与慢相对，与满没有反义关系。", "轻": "轻与重相对，与满没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
