INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87865, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "满是一个东西里面装得很多，不能再放了。", "primary_collocate": null, "pronunciation": "mǎn", "ipa": "man˨˩˦", "syllable_count": 1, "sentences": [{"text": "杯子里的水太满了，别再倒了。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书包很满，放不下了。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电梯很满，我们等下一趟吧。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里的菜盛得太满了。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的箱子很满，拉链都拉不上。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车场很满，我们只能停在路边。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把水倒得太满，小心洒出来。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里东西太满，找不到牛奶。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的背包还没满，还能再放一本书。", "target_word": "满", "complexity_tier": "T3", "furigana": "wǒ de bēibāo hái méi mǎn, hái néng zài fàng yì běn shū.", "sentence_source": "generated"}, {"text": "这个杯子还没满，再加一点茶吧。", "target_word": "满", "complexity_tier": "T3", "furigana": "zhè ge bēizi hái méi mǎn, zài jiā yì diǎn chá ba.", "sentence_source": "generated"}], "morphological_forms": [{"form": "满了", "label": "体标"}, {"form": "滿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "满：容器里装得很多，已经放不下了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471a2867-8aea-41f5-bcb0-874b318de0af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87865, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "满", "is_correct": true, "explanation": "正确。满（mǎn）指装得很多，已经放不下。"}, {"text": "慢", "is_correct": false, "explanation": "声调不同：mǎn（第三声）与 màn（第四声）不同。慢指速度不快，意思不同。"}, {"text": "瞒", "is_correct": false, "explanation": "声调不同：mǎn（第三声）与 mán（第二声）不同。瞒指隐瞒。"}, {"text": "蟒", "is_correct": false, "explanation": "韵母不同：-ǎn 与 -ǎng（n 与 ng）不同。蟒指蟒蛇。"}], "explanations": {"满": "正确。满（mǎn）指装得很多，已经放不下。", "慢": "声调不同：mǎn（第三声）与 màn（第四声）不同。慢指速度不快，意思不同。", "瞒": "声调不同：mǎn（第三声）与 mán（第二声）不同。瞒指隐瞒。", "蟒": "韵母不同：-ǎn 与 -ǎng（n 与 ng）不同。蟒指蟒蛇。"}, "sentence_index": null, "correct_answer": "满"}, "level_3": {"options": [{"text": "满", "is_correct": true, "explanation": "正确。满指装得很多，与「水太……了，别再倒了」的意思相符。"}, {"text": "空", "is_correct": false, "explanation": "语义：空指里面没有东西，与「水太……了，别再倒了」中装得太多的意思相反。"}, {"text": "深", "is_correct": false, "explanation": "语义：深说的是深度，不说装得多少。「水太深了，别再倒了」说不通。"}, {"text": "少", "is_correct": false, "explanation": "语义：少表示水不多，那就应该再倒，与「别再倒了」矛盾。"}], "explanations": {"满": "正确。满指装得很多，与「水太……了，别再倒了」的意思相符。", "空": "语义：空指里面没有东西，与「水太……了，别再倒了」中装得太多的意思相反。", "深": "语义：深说的是深度，不说装得多少。「水太深了，别再倒了」说不通。", "少": "语义：少表示水不多，那就应该再倒，与「别再倒了」矛盾。"}, "sentence_index": 0, "correct_answer": "满"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的箱子现在很满，还可以放很多东西。", "explanation": "这里应该用〈空〉。满表示已经装得很多、放不下；还可以放很多东西要说「空」。"}, {"text": "我对这个结果很满，不想再改了。", "explanation": "这里应该用〈满意〉。满表示装得很多、放不下，不能单独表示心里满足；对结果感到满意要说「满意」。"}, {"text": "我今天中午吃得很满，已经吃不下了。", "explanation": "这里应该用〈饱〉。满用于容器装得很多；人吃饱要说「饱」，不说「吃得很满」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "满", "is_correct": true, "explanation": "正确。满指装得很多，与「小心洒出来」的担心相符。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：轻说的是分量，不说水倒得多少。「倒得太轻」说不通。"}, {"text": "浅", "is_correct": false, "explanation": "语义：浅说的是深度，不说装得多少。「倒得太浅」与「小心洒出来」的担心不合。"}, {"text": "干", "is_correct": false, "explanation": "语义：干指没有水分，与「小心洒出来」的意思相反。"}], "explanations": {"满": "正确。满指装得很多，与「小心洒出来」的担心相符。", "轻": "搭配：轻说的是分量，不说水倒得多少。「倒得太轻」说不通。", "浅": "语义：浅说的是深度，不说装得多少。「倒得太浅」与「小心洒出来」的担心不合。", "干": "语义：干指没有水分，与「小心洒出来」的意思相反。"}, "sentence_index": 6, "correct_answer": "满"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔钱很满，足够用一年了。", "explanation": "这里应该用〈宽裕〉。满用于容器或场所装得很多；手头有钱要说「宽裕」，不说「钱很满」。"}, {"text": "我的愿望已经很满了，不用再努力了。", "explanation": "这里应该用〈满足〉。满表示装得很多、放不下；心愿得到实现要说「满足」，不说「愿望很满」。"}, {"text": "这个抽屉很满，还能放很多东西。", "explanation": "这里应该用〈空〉。满表示装得很多、放不下；还能放很多东西要说「空」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把箱子装了满。", "corrected_sentence": "我把箱子装满了。", "error_description": "「满」作结果补语要紧跟动词，说「装满」。说「装了满」语序不对，应说「装满了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把饭盒装满满的。", "corrected_sentence": "他把饭盒装得满满的。", "error_description": "「满满的」作状态补语前要用「得」连接。说「装得满满的」才对，说「装满满的」少了「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
