INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87866, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "充满；达到容量的极限。", "primary_collocate": null, "pronunciation": "mǎn", "ipa": "man˨˩˦", "syllable_count": 1, "sentences": [{"text": "池子里的水满了，快关水龙头。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的信箱满了，收不到新邮件。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机内存满了，不能再拍照了。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班已经满了，不能再报名了。", "target_word": "满", "complexity_tier": "T3", "furigana": "zhè ge bān yǐjīng mǎn le, bù néng zài bàomíng le.", "sentence_source": "generated"}, {"text": "这个硬盘的空间满了，删一些文件吧。", "target_word": "满", "complexity_tier": "T3", "furigana": "zhè ge yìngpán de kōngjiān mǎn le, shān yì xiē wénjiàn ba.", "sentence_source": "generated"}, {"text": "这个房间的书架已经满了，放不下新书。", "target_word": "满", "complexity_tier": "T3", "furigana": "zhè ge fángjiān de shūjià yǐjīng mǎn le, fàng bu xià xīn shū.", "sentence_source": "generated"}, {"text": "这个文件柜已经满了，得整理一下。", "target_word": "满", "complexity_tier": "T3", "furigana": "zhè ge wénjiàn guì yǐjīng mǎn le, děi zhěnglǐ yíxià.", "sentence_source": "generated"}, {"text": "杯子一满，水就流出来了。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影票卖完了，座位都满了。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的日程已经满了，下周没有时间。", "target_word": "满", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "满了", "label": "体标"}, {"form": "滿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "满：达到容量、数量或期限的极限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471a2867-8aea-41f5-bcb0-874b318de0af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87866, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "满", "is_correct": true, "explanation": "正确。满（mǎn）作动词，指充满、达到容量的极限。"}, {"text": "慢", "is_correct": false, "explanation": "声调不同：mǎn（第三声）与 màn（第四声）不同。慢指速度不快，意思不同。"}, {"text": "瞒", "is_correct": false, "explanation": "声调不同：mǎn（第三声）与 mán（第二声）不同。瞒指隐瞒。"}, {"text": "蟒", "is_correct": false, "explanation": "韵母不同：-ǎn 与 -ǎng（n 与 ng）不同。蟒指蟒蛇。"}], "explanations": {"满": "正确。满（mǎn）作动词，指充满、达到容量的极限。", "慢": "声调不同：mǎn（第三声）与 màn（第四声）不同。慢指速度不快，意思不同。", "瞒": "声调不同：mǎn（第三声）与 mán（第二声）不同。瞒指隐瞒。", "蟒": "韵母不同：-ǎn 与 -ǎng（n 与 ng）不同。蟒指蟒蛇。"}, "sentence_index": null, "correct_answer": "满"}, "level_3": {"options": [{"text": "满", "is_correct": true, "explanation": "正确。满指水达到池子的容量极限，与「快关水龙头」的原因相符。"}, {"text": "空", "is_correct": false, "explanation": "语义：空表示水没有了，与「快关水龙头」的原因矛盾。"}, {"text": "干", "is_correct": false, "explanation": "搭配：干多指水分蒸发殆尽，不用来说池子里的水达到容量极限。"}, {"text": "少", "is_correct": false, "explanation": "语义：少表示水不多，与「快关水龙头」的原因矛盾。"}], "explanations": {"满": "正确。满指水达到池子的容量极限，与「快关水龙头」的原因相符。", "空": "语义：空表示水没有了，与「快关水龙头」的原因矛盾。", "干": "搭配：干多指水分蒸发殆尽，不用来说池子里的水达到容量极限。", "少": "语义：少表示水不多，与「快关水龙头」的原因矛盾。"}, "sentence_index": 0, "correct_answer": "满"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班只有三个学生，已经满了。", "explanation": "这里应该用〈没满〉。满表示名额已达上限；只有三个学生说明名额还很多，要说「没满」。"}, {"text": "这个班还在满，欢迎大家报名。", "explanation": "这里应该用〈招〉。满表示名额已经达到上限；还在招人要说「招」，不说「还在满」。"}, {"text": "这个班已经满了，还能再报名。", "explanation": "这里应该用〈没满〉。满表示名额已到上限；还能再报名说明名额还有空位，要说「没满」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "满", "is_correct": true, "explanation": "正确。满表示已经装满，与「得整理一下」的情况相符。"}, {"text": "亮", "is_correct": false, "explanation": "语义：亮指发光或明亮，不用来形容文件柜的状态，「文件柜已经亮了，得整理一下」说不通。"}, {"text": "缩", "is_correct": false, "explanation": "语义：缩指变小，与「文件柜」装得太多的情况相反。"}, {"text": "高", "is_correct": false, "explanation": "语义：高说的是高度，文件柜「已经高了」与「得整理一下」的情况不合。"}], "explanations": {"满": "正确。满表示已经装满，与「得整理一下」的情况相符。", "亮": "语义：亮指发光或明亮，不用来形容文件柜的状态，「文件柜已经亮了，得整理一下」说不通。", "缩": "语义：缩指变小，与「文件柜」装得太多的情况相反。", "高": "语义：高说的是高度，文件柜「已经高了」与「得整理一下」的情况不合。"}, "sentence_index": 6, "correct_answer": "满"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下周我很满，没有事情做。", "explanation": "这里应该用〈闲〉。满表示事情排得很多、没有空位；没有事情做要说「闲」。"}, {"text": "我的日程已经满了，还能再加一个会议。", "explanation": "这里应该用〈没满〉。满表示事情排满、没有空位；还能再加会议，日程要说「没满」，不能说「已经满了」。"}, {"text": "我的日程已经满了，我每天都很闲。", "explanation": "这里应该用〈没满〉。满表示事情排得很多、没有空位；和「每天都很闲」搭配时，日程要说「没满」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个班没还满，还能报名。", "corrected_sentence": "这个班还没满，还能报名。", "error_description": "「还没满」中「还」要放在「没」前面。说「没还满」语序不对，应说「还没满」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个文件柜满放不下文件了。", "corrected_sentence": "这个文件柜满得放不下文件了。", "error_description": "「满得……」表示结果，中间要用「得」连接。少了「得」，「满放不下」就不成句，应说「满得放不下」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
