INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "先对问题进行剖析，再加以处理。", "primary_collocate": null, "pronunciation": "fēn xī chǔ lǐ", "ipa": "fən˥ ɕi˥ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "老师教我们怎么分析处理问题。", "target_word": "分析处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到麻烦，先分析处理，再做决定。", "target_word": "分析处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请专家来分析处理这些数据。", "target_word": "分析处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很复杂，要慢慢分析处理。", "target_word": "分析处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会分析处理工作中的问题。", "target_word": "分析处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生先检查，再分析处理病人的情况。", "target_word": "分析处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李分析处理了客人的意见。", "target_word": "分析处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据太多，我们要把它们分析处理一下。", "target_word": "分析处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求大家认真分析处理每个投诉。", "target_word": "分析处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分析处理问题很冷静。", "target_word": "分析处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分析处理了", "label": "体标"}, {"form": "分析处理过", "label": "体标"}], "register": "书面", "sense_fingerprint": "先剖析问题再处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167a7954-97b5-4a26-941f-142692a13d69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分析处理", "is_correct": true, "explanation": "正确。分析处理指先剖析问题再加以处理，与“怎么……问题”搭配。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”指搬动实物，不能用于“问题”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热做饭，与“问题”不相容。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”多接具体物体，不说“擦问题”。"}], "explanations": {"分析处理": "正确。分析处理指先剖析问题再加以处理，与“怎么……问题”搭配。", "搬运": "语义：“搬运”指搬动实物，不能用于“问题”。", "煮": "语义：“煮”指加热做饭，与“问题”不相容。", "擦": "搭配：“擦”多接具体物体，不说“擦问题”。"}, "sentence_index": 0, "correct_answer": "分析处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天分析处理了一杯牛奶。", "explanation": "这里应该用〈喝〉。分析处理用于问题、情况、数据等，不能用于饮料。"}, {"text": "老师分析处理了那只小猫。", "explanation": "这里应该用〈照顾〉。分析处理的对象是问题或情况，不能指动物。"}, {"text": "妈妈分析处理了新买的桌子。", "explanation": "这里应该用〈擦〉。分析处理只能用于问题、情况，不能用于家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分析处理", "is_correct": true, "explanation": "正确。分析处理可以带“意见”作宾语，指对意见进行剖析并处理。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能接“意见”。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”多接果实、花等具体物，不接“意见”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，与“意见”不相合。"}], "explanations": {"分析处理": "正确。分析处理可以带“意见”作宾语，指对意见进行剖析并处理。", "吃": "语义：“吃”指进食，不能接“意见”。", "摘": "搭配：“摘”多接果实、花等具体物，不接“意见”。", "洗": "语义：“洗”指清洁，与“意见”不相合。"}, "sentence_index": 6, "correct_answer": "分析处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她分析处理了一双鞋子。", "explanation": "这里应该用〈洗〉。分析处理的对象是问题或数据，不能用于鞋子。"}, {"text": "我每天分析处理花园里的花。", "explanation": "这里应该用〈浇〉。分析处理不能用于植物，花要用浇水等动作照料。"}, {"text": "我分析处理了一碗饭。", "explanation": "这里应该用〈吃〉。分析处理用于问题、情况，饭要用吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师很分析处理这些数据。", "corrected_sentence": "工程师认真分析处理这些数据。", "error_description": "错误形式：很分析处理；正确形式：认真分析处理。“很”是程度副词，不能直接修饰动词，应改用“认真”等表示动作方式的副词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友分析处理的很仔细。", "corrected_sentence": "朋友分析处理得很仔细。", "error_description": "错误形式：分析处理的很仔细；正确形式：分析处理得很仔细。“得”连接动词与后面的补语，“的”用于定语，不能用于此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷淡", "is_correct": true, "explanation": "冷淡：待人不热心、不亲切，与“热情”相对，是这个义项的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：形容清晰明白，与“热情”没有反义关系。"}, {"text": "平凡", "is_correct": false, "explanation": "平凡：形容普通、不出众，与“热情”没有反义关系。"}, {"text": "辛苦", "is_correct": false, "explanation": "辛苦：形容劳累、费力，与“热情”没有反义关系。"}], "correct_answer": "冷淡", "explanations": {"冷淡": "冷淡：待人不热心、不亲切，与“热情”相对，是这个义项的反义词。", "清楚": "清楚：形容清晰明白，与“热情”没有反义关系。", "平凡": "平凡：形容普通、不出众，与“热情”没有反义关系。", "辛苦": "辛苦：形容劳累、费力，与“热情”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷淡", "is_correct": true, "explanation": "冷淡：待人不热心、不亲切，与“热情”相对，是这个义项的反义词。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐：形容排列有序、不乱，与“热情”没有反义关系。"}, {"text": "狡猾", "is_correct": false, "explanation": "狡猾：形容人心眼多、不老实，与“热情”不是反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线充足或眼睛有神，与“热情”没有反义关系。"}], "correct_answer": "冷淡", "explanations": {"冷淡": "冷淡：待人不热心、不亲切，与“热情”相对，是这个义项的反义词。", "整齐": "整齐：形容排列有序、不乱，与“热情”没有反义关系。", "狡猾": "狡猾：形容人心眼多、不老实，与“热情”不是反义关系。", "明亮": "明亮：形容光线充足或眼睛有神，与“热情”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "热情是对别人很好，让人觉得暖和。", "primary_collocate": null, "pronunciation": "rè qíng", "ipa": "ʐɤ˥˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他热情的话让我心里暖暖的。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老奶奶很热情，给我们倒了热茶。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一家人都很热情，我一点也不紧张。", "target_word": "热情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她热情地抱了抱我，我觉得很温暖。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在陌生的城市，大家都很热情，我很感动。", "target_word": "热情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居热情地请我们吃饭。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话很热情，像朋友一样。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天里，他热情的问候让人觉得暖和。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "店员热情地给我们介绍了菜。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友很热情，把最好的房间给了我。", "target_word": "热情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "热情地", "label": "副词形式"}, {"form": "熱情", "label": "繁体"}], "register": "中性", "sense_fingerprint": "热情·对人很好、让人感到温暖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e807c9-c27f-4438-82f2-649eff8684c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热情", "is_correct": true, "explanation": "正确。“热情的话”指对人亲切、让人感到温暖的话。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：冰冷的话不会让人心里暖，与“心里暖暖的”矛盾。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语义：粗鲁的话让人不舒服，与“心里暖暖的”不合。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型，不能修饰“话”。"}], "explanations": {"热情": "正确。“热情的话”指对人亲切、让人感到温暖的话。", "冰冷": "语义：冰冷的话不会让人心里暖，与“心里暖暖的”矛盾。", "粗鲁": "语义：粗鲁的话让人不舒服，与“心里暖暖的”不合。", "高大": "搭配：“高大”形容体型，不能修饰“话”。"}, "sentence_index": 0, "correct_answer": "热情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里生着火，很热情，我脱掉了外套。", "explanation": "这里应该用〈暖和〉。形容温度要说“暖和”，“热情”只形容人待人的态度。"}, {"text": "这条街晚上很热情，大家都来散步。", "explanation": "这里应该用〈热闹〉。形容街道人多、有生气要说“热闹”，“热情”不能形容街道。"}, {"text": "她的眼眶里涌出了热情，我也哭了。", "explanation": "这里应该用〈热泪〉。眼眶里流出的泪水要说“热泪”，“热情”不能指泪水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热情", "is_correct": true, "explanation": "正确。“她说话很热情，像朋友一样”说明她说话亲切。"}, {"text": "生硬", "is_correct": false, "explanation": "语义：生硬的说话方式与“像朋友一样”不协调。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容身体，不能用来形容说话的态度。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：呆板和“像朋友一样”矛盾，说话不亲切。"}], "explanations": {"热情": "正确。“她说话很热情，像朋友一样”说明她说话亲切。", "生硬": "语义：生硬的说话方式与“像朋友一样”不协调。", "瘦弱": "体貌：“瘦弱”形容身体，不能用来形容说话的态度。", "呆板": "语义：呆板和“像朋友一样”矛盾，说话不亲切。"}, "sentence_index": 6, "correct_answer": "热情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场争论很热情，双方都不肯让步。", "explanation": "这里应该用〈激烈〉。争论的紧张程度要说“激烈”，“热情”只形容人的态度。"}, {"text": "天气很热情，我们都想去游泳。", "explanation": "这里应该用〈炎热〉。形容天气的热要说“炎热”，“热情”不能形容天气。"}, {"text": "他热情地咳嗽了几声，大家都很担心。", "explanation": "这里应该用〈剧烈〉。咳嗽的程度要说“剧烈”，“热情”不能形容身体的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位大叔热情的给我们指了路。", "corrected_sentence": "这位大叔热情地给我们指了路。", "error_description": "结构助词错误：“热情”修饰动词“指”时要用“地”，应说“热情地给我们指路”，不说“热情的给我们指路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家民宿的主人很特别热情，还帮我们搬行李。", "corrected_sentence": "这家民宿的主人特别热情，还帮我们搬行李。", "error_description": "程度副词重复错误：“特别”本身已表示程度，前面不能再加“很”；应说“特别热情”，不说“很特别热情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
