INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87871, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "concrete", "definition": "分米是量长度的一个单位，一米的十分之一。", "primary_collocate": null, "pronunciation": "fēn mǐ", "ipa": "fən˥ mi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这张桌子宽六分米，也就是六十厘米。", "target_word": "分米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一米等于十分米。", "target_word": "分米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小鱼只有三分米长。", "target_word": "分米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书包高四分米，放得下这本书。", "target_word": "分米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们量一量，这本书有几分米长。", "target_word": "分米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的画长五分米，宽三分米。", "target_word": "分米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树苗长高了两分米。", "target_word": "分米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布长八分米，做不了大衣服。", "target_word": "分米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子长两分米，宽一分米。", "target_word": "分米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一分米是十厘米，一米是十分米。", "target_word": "分米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方分米", "label": "复合"}, {"form": "立方分米", "label": "复合"}], "register": "中性", "sense_fingerprint": "长度单位，十分之一米", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167a7954-97b5-4a26-941f-142692a13d69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87871, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分米", "is_correct": true, "explanation": "正确答案。分米是长度单位，一米的十分之一。"}, {"text": "分泌", "is_correct": false, "explanation": "mì（第四声）与 mǐ（第三声）声调不同，意思是分泌，指液体从体内排出。"}, {"text": "分子", "is_correct": false, "explanation": "zǐ（第三声）与 mǐ（第三声）声调相同，仅声母 z 与 m 不同，意思是分子（物质的微粒）。"}, {"text": "分秒", "is_correct": false, "explanation": "miǎo 与 mǐ 声母、声调相同，韵母不同（iao 与 i），意思是很短的时间。"}], "explanations": {"分米": "正确答案。分米是长度单位，一米的十分之一。", "分泌": "mì（第四声）与 mǐ（第三声）声调不同，意思是分泌，指液体从体内排出。", "分子": "zǐ（第三声）与 mǐ（第三声）声调相同，仅声母 z 与 m 不同，意思是分子（物质的微粒）。", "分秒": "miǎo 与 mǐ 声母、声调相同，韵母不同（iao 与 i），意思是很短的时间。"}, "sentence_index": null, "correct_answer": "分米"}, "level_3": {"options": [{"text": "分米", "is_correct": true, "explanation": "正确。分米是长度单位，一米的十分之一，与“六十厘米”的换算相符。"}, {"text": "厘米", "is_correct": false, "explanation": "语义：“宽六厘米，也就是六十厘米”自相矛盾，六厘米与六十厘米不是同一长度。"}, {"text": "米", "is_correct": false, "explanation": "语义：“宽六米”等于六百厘米，与“也就是六十厘米”矛盾。"}, {"text": "公里", "is_correct": false, "explanation": "搭配：桌子的宽度不用公里计量，“宽六公里”不符合常识。"}], "explanations": {"分米": "正确。分米是长度单位，一米的十分之一，与“六十厘米”的换算相符。", "厘米": "语义：“宽六厘米，也就是六十厘米”自相矛盾，六厘米与六十厘米不是同一长度。", "米": "语义：“宽六米”等于六百厘米，与“也就是六十厘米”矛盾。", "公里": "搭配：桌子的宽度不用公里计量，“宽六公里”不符合常识。"}, "sentence_index": 0, "correct_answer": "分米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喝了一分米的牛奶。", "explanation": "这里应该用〈升〉或〈杯〉。分米只用于量长度，牛奶是液体，要按容量计量。"}, {"text": "这袋大米重五分米。", "explanation": "这里应该用〈公斤〉。分米只量长度，重量要用公斤、斤等单位。"}, {"text": "我学了三分米的中文。", "explanation": "这里应该用〈个月〉。分米是长度单位，表示学习的时长要用个月、年等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分米", "is_correct": true, "explanation": "正确。分米是长度单位，小树苗长高两分米即二十厘米，符合常识。"}, {"text": "斤", "is_correct": false, "explanation": "语义：“斤”是重量单位，小树苗长高说的是长度，两者不相符。"}, {"text": "吨", "is_correct": false, "explanation": "语义：“吨”是重量单位，“长高了两吨”与长度变化无关。"}, {"text": "毫升", "is_correct": false, "explanation": "搭配：“长高”计量的是长度，“毫升”是容量单位，不能用来计量身高的增长。"}], "explanations": {"分米": "正确。分米是长度单位，小树苗长高两分米即二十厘米，符合常识。", "斤": "语义：“斤”是重量单位，小树苗长高说的是长度，两者不相符。", "吨": "语义：“吨”是重量单位，“长高了两吨”与长度变化无关。", "毫升": "搭配：“长高”计量的是长度，“毫升”是容量单位，不能用来计量身高的增长。"}, "sentence_index": 6, "correct_answer": "分米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班里来了五分米的同学。", "explanation": "这里应该用〈名〉。分米只量长度，人数要用名、个等量词。"}, {"text": "这件衣服花了八分米的钱。", "explanation": "这里应该用〈元〉。分米不能用来计算钱数，钱要用元、块等单位。"}, {"text": "今天的气温是七分米。", "explanation": "这里应该用〈度〉。分米只量长度，温度要用摄氏度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张木板长八分米，宽三个分米。", "corrected_sentence": "这张木板长八分米，宽三分米。", "error_description": "错误形式：三个分米；正确形式：三分米。分米是量词，数词后直接接分米，不能再加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地毯长六分米，宽第四分米。", "corrected_sentence": "这块地毯长六分米，宽四分米。", "error_description": "错误形式：第四分米；正确形式：四分米。“第”只用于序数，量词前的数词不能加“第”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
