INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87873, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "编是把很多细条一根一根绕在一起，做成一样东西。", "primary_collocate": null, "pronunciation": "biān", "ipa": "pjɛn˥", "syllable_count": 1, "sentences": [{"text": "奶奶会编篮子。", "target_word": "编", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她正在编辫子。", "target_word": "编", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给女儿编了两条辫子。", "target_word": "编", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用草编了一顶帽子。", "target_word": "编", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个竹篮是爷爷编的。", "target_word": "编", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小女孩坐在树下编花环。", "target_word": "编", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人用竹子编成了一个小篮子。", "target_word": "编", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我学会了编中国结。", "target_word": "编", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把红线编成一条手链。", "target_word": "编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人都会用竹子编东西。", "target_word": "编", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "编了", "label": "体标"}, {"form": "编着", "label": "体标"}, {"form": "编过", "label": "体标"}, {"form": "编织", "label": "复合"}, {"form": "編", "label": "繁体"}], "register": "中性", "sense_fingerprint": "编·把细条绕在一起做成东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e807c9-c27f-4438-82f2-649eff8684c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "编", "is_correct": true, "explanation": "正确答案。编（biān，第一声）指把细条一根一根绕在一起做成东西。"}, {"text": "变", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是改变。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。"}, {"text": "偏", "is_correct": false, "explanation": "piān 与 biān 声母不同（p 与 b），意思是偏斜、偏向。"}, {"text": "篇", "is_correct": false, "explanation": "piān 与 biān 声母不同（p 与 b），意思是文章、篇章。"}, {"text": "辩", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是辩论。"}], "explanations": {"编": "正确答案。编（biān，第一声）指把细条一根一根绕在一起做成东西。", "变": "biàn（第四声）与 biān（第一声）声调不同，意思是改变。", "扁": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。", "偏": "piān 与 biān 声母不同（p 与 b），意思是偏斜、偏向。", "篇": "piān 与 biān 声母不同（p 与 b），意思是文章、篇章。", "辩": "biàn（第四声）与 biān（第一声）声调不同，意思是辩论。"}, "sentence_index": null, "correct_answer": "编"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：吃是把食物放进嘴里，篮子不能吃。"}, {"text": "编", "is_correct": true, "explanation": "编：把细条交叉编成篮子，与“篮子”搭配，句意通顺。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的宾语是歌曲，不说唱篮子。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿的宾语是衣服、鞋袜，不说穿篮子。"}], "explanations": {"吃": "语义：吃是把食物放进嘴里，篮子不能吃。", "编": "编：把细条交叉编成篮子，与“篮子”搭配，句意通顺。", "唱": "搭配：唱的宾语是歌曲，不说唱篮子。", "穿": "搭配：穿的宾语是衣服、鞋袜，不说穿篮子。"}, "sentence_index": 0, "correct_answer": "编"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给孩子编了一件棉衣。", "explanation": "这里应该用〈缝〉。棉衣是用布料裁剪后缝制的，不是编织而成；编是用毛线或细条交叉织成，多用于毛衣、篮子等，不说编棉衣。"}, {"text": "工人用石头编了一道墙。", "explanation": "这里应该用〈垒〉。垒是把石块或砖一层层堆起来砌墙；编是把细条交叉成器物，不用于用石头砌墙。"}, {"text": "妈妈一早编了一锅粥。", "explanation": "这里应该用〈熬〉。熬是用文火久煮，指做粥汤；编是把细条交叉成器物，不用于做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87873, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "便", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是方便。"}, {"text": "编", "is_correct": true, "explanation": "正确答案。编（biān，第一声）指把细条一根一根绕在一起做成东西。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。"}, {"text": "贬", "is_correct": false, "explanation": "biǎn（第三声）与 biān（第一声）声调不同，意思是降低、贬低。"}, {"text": "遍", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是次数、整个过程。"}], "explanations": {"便": "biàn（第四声）与 biān（第一声）声调不同，意思是方便。", "编": "正确答案。编（biān，第一声）指把细条一根一根绕在一起做成东西。", "扁": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。", "贬": "biǎn（第三声）与 biān（第一声）声调不同，意思是降低、贬低。", "遍": "biàn（第四声）与 biān（第一声）声调不同，意思是次数、整个过程。"}, "sentence_index": null, "correct_answer": "编"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "语义：写是用笔记录文字，竹子不能写成篮子。"}, {"text": "烤", "is_correct": false, "explanation": "语义：烤是用火加热食物，竹子不能烤成篮子。"}, {"text": "编", "is_correct": true, "explanation": "编成：把竹子编织成篮子，与“竹子”“篮子”搭配，句意通顺。"}, {"text": "吹", "is_correct": false, "explanation": "语义：吹是用气流推动，竹子不能吹成篮子。"}], "explanations": {"写": "语义：写是用笔记录文字，竹子不能写成篮子。", "烤": "语义：烤是用火加热食物，竹子不能烤成篮子。", "编": "编成：把竹子编织成篮子，与“竹子”“篮子”搭配，句意通顺。", "吹": "语义：吹是用气流推动，竹子不能吹成篮子。"}, "sentence_index": 6, "correct_answer": "编"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂里用机器编布。", "explanation": "应该用〈织〉。织是用纱线交叉成布，可用机器完成；编是把细条交叉成器物，不说编布。"}, {"text": "她在手绢上编了一朵花。", "explanation": "应该用〈绣〉。绣是用彩线在布上做出花纹；编是把细条交叉成器物，不用于在布上做花。"}, {"text": "他用木头编了一只小鸟。", "explanation": "应该用〈雕〉。雕是用刀在木头上刻出形状；编是把细条交叉成器物，不用于木头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他编了完一顶草帽。", "corrected_sentence": "他编完了一顶草帽。", "error_description": "错误：“编了完”。结果补语“完”应紧跟动词，“了”放在补语之后，正确为“编完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把竹条编。", "corrected_sentence": "她把竹条编成了一个筐。", "error_description": "错误：“把”字句中，“编”后缺少结果补语或“了”，句子不完整。正确应为“编成了一个筐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
