INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按一定次序整理材料、编写成书，或创作故事、歌曲、舞蹈等。", "primary_collocate": null, "pronunciation": "biān", "ipa": "pjɛn˥", "syllable_count": 1, "sentences": [{"text": "他在给孩子编故事。", "target_word": "编", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师编了一本新课本。", "target_word": "编", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌是他自己编的。", "target_word": "编", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她正在编一个很长的故事。", "target_word": "编", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷把家里的老照片编成了一本相册。", "target_word": "编", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们编了一个新舞蹈，准备下周表演。", "target_word": "编", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把学生的作文编成了一本书。", "target_word": "编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈自己编了一首摇篮曲。", "target_word": "编", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本词典是他花了五年时间编的。", "target_word": "编", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧文章重新编了一遍。", "target_word": "编", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编了", "label": "体标"}, {"form": "编着", "label": "体标"}, {"form": "编过", "label": "体标"}, {"form": "编织", "label": "复合"}, {"form": "編", "label": "繁体"}], "register": "中性", "sense_fingerprint": "编·整理材料编写成书，或创作故事、歌曲、舞蹈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e807c9-c27f-4438-82f2-649eff8684c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87874, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扁", "is_correct": false, "explanation": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。"}, {"text": "编", "is_correct": true, "explanation": "正确答案。编（biān，第一声）指编织，也指整理、创作。"}, {"text": "辩", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是辩论。"}, {"text": "变", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是改变。"}, {"text": "偏", "is_correct": false, "explanation": "piān 与 biān 声母不同（p 与 b），意思是偏斜、偏向。"}], "explanations": {"扁": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。", "编": "正确答案。编（biān，第一声）指编织，也指整理、创作。", "辩": "biàn（第四声）与 biān（第一声）声调不同，意思是辩论。", "变": "biàn（第四声）与 biān（第一声）声调不同，意思是改变。", "偏": "piān 与 biān 声母不同（p 与 b），意思是偏斜、偏向。"}, "sentence_index": null, "correct_answer": "编"}, "level_3": {"options": [{"text": "穿", "is_correct": false, "explanation": "搭配：穿的宾语是衣服、鞋袜，不说穿故事。"}, {"text": "编", "is_correct": true, "explanation": "编：创作或编写故事，与“故事”搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是把食物放进嘴里，故事不能吃。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝是把液体咽下，故事不能喝。"}], "explanations": {"穿": "搭配：穿的宾语是衣服、鞋袜，不说穿故事。", "编": "编：创作或编写故事，与“故事”搭配，句意通顺。", "吃": "语义：吃是把食物放进嘴里，故事不能吃。", "喝": "语义：喝是把液体咽下，故事不能喝。"}, "sentence_index": 0, "correct_answer": "编"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一笔一笔编了一幅画。", "explanation": "这里应该用〈画〉。画是用笔在纸上描绘；编是整理、创作文字或舞蹈、音乐，不用于用笔作画。"}, {"text": "工人在院子里编了一间小屋。", "explanation": "这里应该用〈盖〉。盖是用砖瓦、木料建造房屋；编是整理、创作或把细条交叉成器物，不用于建房。"}, {"text": "妈妈编了一锅面条。", "explanation": "这里应该用〈煮〉。煮是用水加热做饭；编是整理、创作或把细条交叉成器物，不用于煮食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87874, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "天", "is_correct": false, "explanation": "tiān（第一声）与 biān（第一声）声母不同（t 与 b），意思是天空。"}, {"text": "遍", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是次数、整个过程。"}, {"text": "编", "is_correct": true, "explanation": "正确答案。编（biān，第一声）指编织，也指整理、创作。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。"}, {"text": "便", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是方便。"}], "explanations": {"天": "tiān（第一声）与 biān（第一声）声母不同（t 与 b），意思是天空。", "遍": "biàn（第四声）与 biān（第一声）声调不同，意思是次数、整个过程。", "编": "正确答案。编（biān，第一声）指编织，也指整理、创作。", "扁": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。", "便": "biàn（第四声）与 biān（第一声）声调不同，意思是方便。"}, "sentence_index": null, "correct_answer": "编"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：唱的宾语是歌曲，不说唱作文。"}, {"text": "烤", "is_correct": false, "explanation": "语义：烤是用火加热食物，作文不能烤成书。"}, {"text": "编", "is_correct": true, "explanation": "编成：把作文整理、编排成书，与“作文”“书”搭配，句意通顺。"}, {"text": "吹", "is_correct": false, "explanation": "语义：吹是用气流推动，作文不能吹成书。"}], "explanations": {"唱": "搭配：唱的宾语是歌曲，不说唱作文。", "烤": "语义：烤是用火加热食物，作文不能烤成书。", "编": "编成：把作文整理、编排成书，与“作文”“书”搭配，句意通顺。", "吹": "语义：吹是用气流推动，作文不能吹成书。"}, "sentence_index": 6, "correct_answer": "编"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位建筑师编了一座新大楼。", "explanation": "应该用〈设计〉。设计用于建筑、产品；编用于编织或编写，不说编大楼。"}, {"text": "这台机器每天编布五百米。", "explanation": "应该用〈织〉。织是用纱线交叉成布，常用机器完成；编是把细条交叉成器物，不说编布。"}, {"text": "她在枕巾上编了一朵牡丹。", "explanation": "应该用〈绣〉。绣是用彩线在布上做出花纹；编是把细条交叉成器物，不用于在布上做花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师已经编了完那本教材。", "corrected_sentence": "老师已经编完了那本教材。", "error_description": "错误：“编了完”。结果补语“完”应紧跟动词，“了”放在补语之后，正确为“编完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把这份资料编。", "corrected_sentence": "她把这份资料编好了。", "error_description": "错误：“把”字句中，“编”后缺少结果补语或“了”，句子不完整。正确应为“编好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
