INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87875, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "猴子是一种小动物。它爱爬树,爱吃香蕉。", "primary_collocate": null, "pronunciation": "hóu zi", "ipa": "xoʊ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "猴子爱爬树,也爱吃香蕉。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里有一只小猴子。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猴子坐在树上吃香蕉。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猴子看见我,马上跑开了。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给猴子一个苹果,它很高兴。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子的手和脚都很灵活。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带我去看猴子。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树上有一群猴子在玩儿。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子跳得很高,一下就上树了。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猴子把香蕉皮扔在地上。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "群", "label": "量词"}], "register": "中性", "sense_fingerprint": "爱爬树、爱吃香蕉的小动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ca57c2-ac8c-47f7-b168-f786db53d8e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鱼", "is_correct": false, "explanation": "语义：鱼生活在水里，不会爬树，也不吃香蕉。"}, {"text": "猴子", "is_correct": true, "explanation": "正确：猴子爱爬树，也爱吃香蕉，只有猴子符合句中的两个特点。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“爬树”和“吃香蕉”的主语必须是动物，汽车不能爬树，也不能吃东西。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，没有生命，不会爬树，也不会吃香蕉。"}], "explanations": {"鱼": "语义：鱼生活在水里，不会爬树，也不吃香蕉。", "猴子": "正确：猴子爱爬树，也爱吃香蕉，只有猴子符合句中的两个特点。", "汽车": "搭配：“爬树”和“吃香蕉”的主语必须是动物，汽车不能爬树，也不能吃东西。", "桌子": "语义：桌子是家具，没有生命，不会爬树，也不会吃香蕉。"}, "sentence_index": 0, "correct_answer": "猴子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猴子是最聪明的类人猿之一。", "explanation": "这里应该用〈猩猩〉。猴子不属于类人猿，类人猿指猩猩、黑猩猩等，猴子是另一类动物。"}, {"text": "我在动物园看到了一颗猴子。", "explanation": "这里应该用〈只〉。“颗”用于圆形或粒状的小东西，猴子是动物，量词用“只”。"}, {"text": "森林里有一棵猴子在树上跳。", "explanation": "这里应该用〈只〉。“棵”用于树木和植物，猴子是动物，量词应用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，不是可以“去看”的对象。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：牛奶是饮品，应说“喝”，不能说“看”。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是液体燃料，一般不作为参观或观看的对象。"}, {"text": "猴子", "is_correct": true, "explanation": "正确：“去看”后面接的是动物园里可以观看的动物，猴子符合句意。"}], "explanations": {"空气": "语义：空气看不见摸不着，不是可以“去看”的对象。", "牛奶": "搭配：牛奶是饮品，应说“喝”，不能说“看”。", "汽油": "语义：汽油是液体燃料，一般不作为参观或观看的对象。", "猴子": "正确：“去看”后面接的是动物园里可以观看的动物，猴子符合句意。"}, "sentence_index": 6, "correct_answer": "猴子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在市场上买了一本猴子。", "explanation": "这里应该用〈只〉。“本”用于书籍、本子，不用于动物，猴子的量词是“只”。"}, {"text": "动物园里新来了一部猴子。", "explanation": "这里应该用〈只〉。“部”用于电影、机器、车辆等，猴子的量词是“只”。"}, {"text": "树林里有一块猴子在跳。", "explanation": "这里应该用〈只〉。“块”用于块状的东西，猴子是活的动物，不能用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹很喜欢那颗小猴子。", "corrected_sentence": "妹妹很喜欢那只小猴子。", "error_description": "量词错误：猴子是动物，应说“那只小猴子”，不能用“颗”（“颗”用于圆形或粒状的小东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "树上有一个猴子在玩。", "corrected_sentence": "树上有一只猴子在玩。", "error_description": "量词错误：猴子是动物，量词应用“只”，应说“一只猴子”，不能说“一个猴子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
