INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "灵长目动物,身体灵活,善于攀爬,多生活在树林里。", "primary_collocate": null, "pronunciation": "hóu zi", "ipa": "xoʊ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "猴子身体灵活,善于爬树。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子多生活在大树林里。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的猴子主要吃水果和树叶。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只猴子在树枝上跳来跳去。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子是一种很聪明的动物。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种猴子的尾巴特别长。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子用手抓住树枝往上爬。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在山里研究猴子。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子一般成群生活在一起。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片树林里有很多猴子。", "target_word": "猴子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "群", "label": "量词"}], "register": "中性", "sense_fingerprint": "灵长目、善攀爬、生活在树林的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ca57c2-ac8c-47f7-b168-f786db53d8e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乌龟", "is_correct": false, "explanation": "语义：乌龟行动缓慢，不会爬树，也谈不上“身体灵活”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能“身体灵活”，也不能“爬树”。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“善于”多用于人或动物的能力，电视不能“善于爬树”。"}, {"text": "猴子", "is_correct": true, "explanation": "正确：猴子身体灵活，善于爬树，这是它的典型特点。"}], "explanations": {"乌龟": "语义：乌龟行动缓慢，不会爬树，也谈不上“身体灵活”。", "石头": "语义：石头没有生命，不能“身体灵活”，也不能“爬树”。", "电视": "搭配：“善于”多用于人或动物的能力，电视不能“善于爬树”。", "猴子": "正确：猴子身体灵活，善于爬树，这是它的典型特点。"}, "sentence_index": 0, "correct_answer": "猴子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猴子属于类人猿，和大猩猩是同一类。", "explanation": "这里应该用〈猩猩〉。猴子不属于类人猿，猩猩和大猩猩才是类人猿。"}, {"text": "森林里有一座猴子在树上跳。", "explanation": "这里应该用〈只〉。“座”用于山、桥、楼房等大型固定的东西，猴子是动物，量词用“只”。"}, {"text": "我在树林里看到一张猴子。", "explanation": "这里应该用〈只〉。“张”用于纸、桌子等扁平的东西，猴子不能用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鸟", "is_correct": false, "explanation": "语义：鸟靠爪子和翅膀活动，不会用手抓树枝往上爬。"}, {"text": "蛇", "is_correct": false, "explanation": "体貌：蛇没有手，不能“用手抓住树枝”。"}, {"text": "章鱼", "is_correct": false, "explanation": "语义：章鱼生活在海里，不会爬到树上去。"}, {"text": "猴子", "is_correct": true, "explanation": "正确：猴子用手抓住树枝往上爬，符合句中的动作。"}], "explanations": {"鸟": "语义：鸟靠爪子和翅膀活动，不会用手抓树枝往上爬。", "蛇": "体貌：蛇没有手，不能“用手抓住树枝”。", "章鱼": "语义：章鱼生活在海里，不会爬到树上去。", "猴子": "正确：猴子用手抓住树枝往上爬，符合句中的动作。"}, "sentence_index": 6, "correct_answer": "猴子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在山里看到一块猴子。", "explanation": "这里应该用〈只〉。“块”用于块状的东西，猴子是活的动物，不能用“块”。"}, {"text": "这片树林里有很多部猴子。", "explanation": "这里应该用〈只〉。“部”用于书、电影、车辆等，不能用于猴子。"}, {"text": "一本猴子在树上玩儿。", "explanation": "这里应该用〈只〉。“本”用于书籍、本子，猴子不能用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园里来了一张小猴子。", "corrected_sentence": "公园里来了一只小猴子。", "error_description": "量词错误：猴子是动物，应说“一只小猴子”，不能用“张”（“张”用于扁平的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家在山里看到了一条猴子。", "corrected_sentence": "科学家在山里看到了一只猴子。", "error_description": "量词错误：猴子的量词是“只”，应说“一只猴子”，不能用“条”（“条”用于蛇、鱼等细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
