INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机构或企业的最高领导和管理部门所在地。", "primary_collocate": null, "pronunciation": "zǒng bù", "ipa": "tsʊŋ˨˩˦ pu˥˩", "syllable_count": 2, "sentences": [{"text": "公司的总部在北京。", "target_word": "总部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家银行的总部在上海。", "target_word": "总部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "总部的领导明天会来我们这里。", "target_word": "总部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司的总部设在一座很高的楼里。", "target_word": "总部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在总部工作了五年。", "target_word": "总部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总部决定把新产品卖到国外。", "target_word": "总部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司有很多分公司，总部在深圳。", "target_word": "总部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总部给各个分公司发了一封信。", "target_word": "总部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想去美国总部学习管理。", "target_word": "总部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "联合国的总部在纽约。", "target_word": "总部", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "总部大楼", "label": "复合词"}], "register": "中性", "sense_fingerprint": "总部：机构或企业最高领导和管理部门所在地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '986f312e-72c3-468e-8424-eadc7ad44fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总部", "is_correct": true, "explanation": "正确：“总部”指机构最高管理部门所在地，“公司的总部在北京”读起来通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是能位于某个地点的事物，“公司的颜色在北京”读起来不通。"}, {"text": "校区", "is_correct": false, "explanation": "搭配：“校区”是学校的说法，公司不说“公司的校区”。"}, {"text": "府邸", "is_correct": false, "explanation": "语域：“府邸”是旧时官宦或富户的住宅，书面色彩很浓，不用于公司机构。"}], "explanations": {"总部": "正确：“总部”指机构最高管理部门所在地，“公司的总部在北京”读起来通顺。", "颜色": "语义：“颜色”不是能位于某个地点的事物，“公司的颜色在北京”读起来不通。", "校区": "搭配：“校区”是学校的说法，公司不说“公司的校区”。", "府邸": "语域：“府邸”是旧时官宦或富户的住宅，书面色彩很浓，不用于公司机构。"}, "sentence_index": 0, "correct_answer": "总部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个集团在深圳设了一只总部。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对器官中的一个，不能用来计量机构。"}, {"text": "那家连锁超市新建了一条总部。", "explanation": "这里应该用〈个〉。“条”用于细长的物品，不用于机构；总部用“个”计量。"}, {"text": "这家电视台有一把总部。", "explanation": "这里应该用〈个〉。“把”多用于带柄的器具或椅子，不能用来修饰机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总部", "is_correct": true, "explanation": "正确：“总部”与“分公司”相对，“总部在深圳”表示总部的位置，句意通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是存在的时间长度，不能位于地点，“年龄在深圳”读起来不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的体形特征，不能用来说机构的位置。"}, {"text": "班级", "is_correct": false, "explanation": "搭配：“班级”是学校的组织，与“公司”的分支机构不搭配。"}], "explanations": {"总部": "正确：“总部”与“分公司”相对，“总部在深圳”表示总部的位置，句意通顺。", "年龄": "语义：“年龄”是存在的时间长度，不能位于地点，“年龄在深圳”读起来不通。", "身高": "体貌：“身高”指人的体形特征，不能用来说机构的位置。", "班级": "搭配：“班级”是学校的组织，与“公司”的分支机构不搭配。"}, "sentence_index": 6, "correct_answer": "总部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂在城外设了一个总部，每天生产一千个零件。", "explanation": "这里应该用〈车间〉。总部是管理机构所在地，不负责具体生产；生产零件的场所要叫车间。"}, {"text": "这家餐厅在城里开了三个总部，每天都有人来吃饭。", "explanation": "这里应该用〈分店〉。总部是管理机构所在地，不直接接待食客；接待食客的门店要叫分店。"}, {"text": "这家书店的总部每天在门口卖书，方便附近的居民。", "explanation": "这里应该用〈门店〉。总部是管理机构所在地，不直接卖货；卖书的场所要叫门店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的那只总部设在杭州。", "corrected_sentence": "这家公司的那个总部设在杭州。", "error_description": "错在量词。“总部”是机构，量词应用“个”；“只”不能用来计量机构，应说“那个总部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家跨国公司的总部们位于伦敦。", "corrected_sentence": "这家跨国公司的总部位于伦敦。", "error_description": "错在“总部”后面加了“们”。“们”只用于指人的复数，机构不能加“们”，应说“总部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
