INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87879, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城是很多人住在一起的大地方，里面有很多房子。", "primary_collocate": null, "pronunciation": "chéng", "ipa": "ʈʂʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这座城很大，里面住着很多人。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家在城里，我家在乡下。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天早上，我坐车进城上班。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里的房子又高又新，路上有很多车。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城外有山有水，空气比城里好。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城有一千多年的历史了。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们开车去城里买东西。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城不大，只有一条主要的路。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，城里的灯都亮了，真漂亮。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人离开家乡，去城里找工作。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座城", "label": "量词"}, {"form": "城市", "label": "复合"}, {"form": "城墙", "label": "复合"}], "register": "中性", "sense_fingerprint": "城：很多人住在一起、有很多房子的大地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70440bbe-270b-40e4-ad01-5390c3128607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87879, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "城", "is_correct": true, "explanation": "城（chéng）：人口多、房屋多的大地方，是正确答案。"}, {"text": "常", "is_correct": false, "explanation": "cháng 与 chéng 韵母不同（ang/eng），意思是“常常”。"}, {"text": "陈", "is_correct": false, "explanation": "chén 与 chéng 韵尾不同（n/ng），意思是“陈旧”。"}, {"text": "虫", "is_correct": false, "explanation": "chóng 与 chéng 韵母不同（o/e），意思是“虫子”。"}, {"text": "撑", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，意思是“撑开”。"}, {"text": "秤", "is_correct": false, "explanation": "chèng（第四声）与 chéng 声调不同，意思是“秤”。"}], "explanations": {"城": "城（chéng）：人口多、房屋多的大地方，是正确答案。", "常": "cháng 与 chéng 韵母不同（ang/eng），意思是“常常”。", "陈": "chén 与 chéng 韵尾不同（n/ng），意思是“陈旧”。", "虫": "chóng 与 chéng 韵母不同（o/e），意思是“虫子”。", "撑": "chēng（第一声）与 chéng（第二声）声调不同，意思是“撑开”。", "秤": "chèng（第四声）与 chéng 声调不同，意思是“秤”。"}, "sentence_index": null, "correct_answer": "城"}, "level_3": {"options": [{"text": "城", "is_correct": true, "explanation": "“城”是人口众多的大地方，与“里面住着很多人”相符。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“座”不能用来计量“书”，书里也不住人。"}, {"text": "树", "is_correct": false, "explanation": "语义：树里不能住很多人，“里面住着很多人”与“树”不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，里面不能住人。"}], "explanations": {"城": "“城”是人口众多的大地方，与“里面住着很多人”相符。", "书": "搭配：“座”不能用来计量“书”，书里也不住人。", "树": "语义：树里不能住很多人，“里面住着很多人”与“树”不符。", "桌子": "语义：桌子是家具，里面不能住人。"}, "sentence_index": 0, "correct_answer": "城"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城里住着几十户人家，大家都认识。", "explanation": "这里应该用〈村〉。几十户人家、大家都认识的聚居地要用“村”，城指人口众多的大地方。"}, {"text": "城上挂着一幅画，画上是一片大海。", "explanation": "这里应该用〈墙〉。城是很多人住的大地方，挂画的墙面要用“墙”。"}, {"text": "我家的城只有十平方米，很暖和。", "explanation": "这里应该用〈小屋〉。城指大的城市，十平方米的住处要用“小屋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87879, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "城", "is_correct": true, "explanation": "城（chéng）：人口多、房屋多的大地方，是正确答案。"}, {"text": "尘", "is_correct": false, "explanation": "chén 与 chéng 韵尾不同（n/ng），意思是“灰尘”。"}, {"text": "长", "is_correct": false, "explanation": "cháng 与 chéng 韵母不同（ang/eng），意思是“长短的长”。"}, {"text": "绳", "is_correct": false, "explanation": "shéng 与 chéng 声母不同（sh/ch），意思是“绳子”。"}, {"text": "称", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，意思是“称呼”。"}, {"text": "晨", "is_correct": false, "explanation": "chén 与 chéng 韵尾不同（n/ng），意思是“清晨”。"}], "explanations": {"城": "城（chéng）：人口多、房屋多的大地方，是正确答案。", "尘": "chén 与 chéng 韵尾不同（n/ng），意思是“灰尘”。", "长": "cháng 与 chéng 韵母不同（ang/eng），意思是“长短的长”。", "绳": "shéng 与 chéng 声母不同（sh/ch），意思是“绳子”。", "称": "chēng（第一声）与 chéng（第二声）声调不同，意思是“称呼”。", "晨": "chén 与 chéng 韵尾不同（n/ng），意思是“清晨”。"}, "sentence_index": null, "correct_answer": "城"}, "level_3": {"options": [{"text": "城", "is_correct": true, "explanation": "“城里”指城市，与“周末开车去……里买东西”相符。"}, {"text": "海", "is_correct": false, "explanation": "语义：“海”是大片水域，不能开车去海里买东西。"}, {"text": "碗", "is_correct": false, "explanation": "语义：“碗”是餐具，人不能进去买东西。"}, {"text": "田", "is_correct": false, "explanation": "搭配：田里一般没有店铺，不说“去田里买东西”。"}], "explanations": {"城": "“城里”指城市，与“周末开车去……里买东西”相符。", "海": "语义：“海”是大片水域，不能开车去海里买东西。", "碗": "语义：“碗”是餐具，人不能进去买东西。", "田": "搭配：田里一般没有店铺，不说“去田里买东西”。"}, "sentence_index": 6, "correct_answer": "城"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "城的菜都是自己种的，很新鲜。", "explanation": "这里应该用〈农村〉。城指城市，自己种菜的地方要用“农村”。"}, {"text": "我把城放进书包里，带去学校。", "explanation": "这里应该用〈本子〉。城是很多人住的大地方，不能放进书包里。"}, {"text": "城在河里开得很快，一会儿就到对岸了。", "explanation": "这里应该用〈船〉。城是很多人住的大地方，不能在河里开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条城的夜市很热闹，人们都去逛。", "corrected_sentence": "这座城的夜市很热闹，人们都去逛。", "error_description": "错误在量词：“城”应使用量词“座”，不能用“条”（条多用于河流、道路、鱼等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每个月都城进看病。", "corrected_sentence": "他每个月都进城看病。", "error_description": "错误在语序：“进城”是动词加宾语的结构，应说“进城”，不能颠倒成“城进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
