INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市；围绕市区的高大围墙，也指城市。", "primary_collocate": null, "pronunciation": "chéng", "ipa": "ʈʂʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "古代的城有高高的墙，敌人进不去。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵守在城上，看着远处的路。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，士兵在城上点火报信。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，人们不能出城。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人把城围住了，里面的人没有吃的。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城外有一条河，城里有很多商店。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天进城买了一些东西。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从乡下来到城里工作。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城很大，走一圈要三个小时。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们站在城上，可以看到下面的河。", "target_word": "城", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座城", "label": "量词"}, {"form": "城墙", "label": "复合"}, {"form": "城市", "label": "复合"}], "register": "中性", "sense_fingerprint": "城：围绕市区的高大围墙，也指城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70440bbe-270b-40e4-ad01-5390c3128607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87880, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "城", "is_correct": true, "explanation": "城（chéng）：城市，或围绕市区的高墙，是正确答案。"}, {"text": "称", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，意思是“称呼”。"}, {"text": "常", "is_correct": false, "explanation": "cháng 与 chéng 韵母不同（ang/eng），意思是“常常”。"}, {"text": "陈", "is_correct": false, "explanation": "chén 与 chéng 韵尾不同（n/ng），意思是“陈旧”。"}, {"text": "绳", "is_correct": false, "explanation": "shéng 与 chéng 声母不同（sh/ch），意思是“绳子”。"}, {"text": "秤", "is_correct": false, "explanation": "chèng（第四声）与 chéng 声调不同，意思是“秤”。"}], "explanations": {"城": "城（chéng）：城市，或围绕市区的高墙，是正确答案。", "称": "chēng（第一声）与 chéng（第二声）声调不同，意思是“称呼”。", "常": "cháng 与 chéng 韵母不同（ang/eng），意思是“常常”。", "陈": "chén 与 chéng 韵尾不同（n/ng），意思是“陈旧”。", "绳": "shéng 与 chéng 声母不同（sh/ch），意思是“绳子”。", "秤": "chèng（第四声）与 chéng 声调不同，意思是“秤”。"}, "sentence_index": null, "correct_answer": "城"}, "level_3": {"options": [{"text": "城", "is_correct": true, "explanation": "“城”是高墙环绕的城池，与“古代的……有高高的墙，敌人进不去”相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”是人，不是防御的建筑，不能说“古代的学生有高高的墙”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”没有墙，不能说“古代的书有高高的墙”。"}, {"text": "河", "is_correct": false, "explanation": "语义：河流不是城池，不会有“高高的墙”把敌人挡在外面。"}], "explanations": {"城": "“城”是高墙环绕的城池，与“古代的……有高高的墙，敌人进不去”相符。", "学生": "语义：“学生”是人，不是防御的建筑，不能说“古代的学生有高高的墙”。", "书": "搭配：“书”没有墙，不能说“古代的书有高高的墙”。", "河": "语义：河流不是城池，不会有“高高的墙”把敌人挡在外面。"}, "sentence_index": 0, "correct_answer": "城"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城把我家的院子围起来了。", "explanation": "这里应该用〈墙〉。城指城市或环绕市区的城墙，不指院子的墙。"}, {"text": "我家的城很小，只有两间屋子。", "explanation": "这里应该用〈房子〉。城指城市或城墙，不指一家人住的房子。"}, {"text": "妈妈用城给我做了一碗面条。", "explanation": "这里应该用〈锅〉。城指城市或城墙，不是做饭的用具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87880, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "城", "is_correct": true, "explanation": "城（chéng）：城市，或围绕市区的高墙，是正确答案。"}, {"text": "尘", "is_correct": false, "explanation": "chén 与 chéng 韵尾不同（n/ng），意思是“尘土”。"}, {"text": "长", "is_correct": false, "explanation": "cháng 与 chéng 韵母不同（ang/eng），意思是“长短的长”。"}, {"text": "虫", "is_correct": false, "explanation": "chóng 与 chéng 韵母不同（o/e），意思是“虫子”。"}, {"text": "撑", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，意思是“撑”。"}, {"text": "晨", "is_correct": false, "explanation": "chén 与 chéng 韵尾不同（n/ng），意思是“清晨”。"}], "explanations": {"城": "城（chéng）：城市，或围绕市区的高墙，是正确答案。", "尘": "chén 与 chéng 韵尾不同（n/ng），意思是“尘土”。", "长": "cháng 与 chéng 韵母不同（ang/eng），意思是“长短的长”。", "虫": "chóng 与 chéng 韵母不同（o/e），意思是“虫子”。", "撑": "chēng（第一声）与 chéng（第二声）声调不同，意思是“撑”。", "晨": "chén 与 chéng 韵尾不同（n/ng），意思是“清晨”。"}, "sentence_index": null, "correct_answer": "城"}, "level_3": {"options": [{"text": "城", "is_correct": true, "explanation": "“城”指城市，与“我昨天进……买了一些东西”相符。"}, {"text": "海", "is_correct": false, "explanation": "语义：“海”是大片水域，不能“进海”去买东西。"}, {"text": "碗", "is_correct": false, "explanation": "语义：“碗”是餐具，人不能进去买东西。"}, {"text": "田", "is_correct": false, "explanation": "搭配：田里一般没有店铺，不说“进田买东西”。"}], "explanations": {"城": "“城”指城市，与“我昨天进……买了一些东西”相符。", "海": "语义：“海”是大片水域，不能“进海”去买东西。", "碗": "语义：“碗”是餐具，人不能进去买东西。", "田": "搭配：田里一般没有店铺，不说“进田买东西”。"}, "sentence_index": 6, "correct_answer": "城"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城种满了麦子，今年丰收了。", "explanation": "这里应该用〈田〉。城指城市或城墙，种庄稼要用“田”。"}, {"text": "这座城很小，只能装一支笔。", "explanation": "这里应该用〈盒子〉。城指大的城市，不是能装东西的容器。"}, {"text": "这座城很大，可以载五十个人。", "explanation": "这里应该用〈船〉。城指城市或城墙，不能用来载人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条城很古老，城墙上长满了草。", "corrected_sentence": "这座城很古老，城墙上长满了草。", "error_description": "错误在量词：“城”应使用量词“座”，不能用“条”（条多用于河流、道路、鱼等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐周末城进看朋友。", "corrected_sentence": "姐姐周末进城看朋友。", "error_description": "错误在语序：“进城”是动词加宾语的结构，应说“进城”，不能颠倒成“城进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
