INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87881, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "职务是一个人在单位里要做的事和他的名称。", "primary_collocate": null, "pronunciation": "zhí wù", "ipa": "ʈʂʅ˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "他在公司的职务是经理。", "target_word": "职务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你现在担任什么职务？", "target_word": "职务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的职务是办公室主任。", "target_word": "职务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的职务比我高。", "target_word": "职务", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请在表格里写上你的姓名和职务。", "target_word": "职务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师同时兼任两个职务。", "target_word": "职务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他退休前的职务是校长。", "target_word": "职务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的同事是什么职务？", "target_word": "职务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他因为生病，辞去了职务。", "target_word": "职务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理这个职务很重要，责任也大。", "target_word": "职务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "職務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人在单位里的职位名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14cca9b8-8933-4231-8bfa-84367bc59d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87881, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "职务", "is_correct": true, "explanation": "正确。职务：一个人在单位里要做的事和他的名称。"}, {"text": "迟误", "is_correct": false, "explanation": "chí（第二声）与 zhí（第二声）声母不同，意思是耽误。"}, {"text": "食物", "is_correct": false, "explanation": "shí（第二声）与 zhí（第二声）声母不同，意思是可以吃的东西。"}, {"text": "织物", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是纺织品。"}], "explanations": {"职务": "正确。职务：一个人在单位里要做的事和他的名称。", "迟误": "chí（第二声）与 zhí（第二声）声母不同，意思是耽误。", "食物": "shí（第二声）与 zhí（第二声）声母不同，意思是可以吃的东西。", "织物": "zhī（第一声）与 zhí（第二声）声调不同，意思是纺织品。"}, "sentence_index": null, "correct_answer": "职务"}, "level_3": {"options": [{"text": "职务", "is_correct": true, "explanation": "正确。“职务”指在公司担任的职位，与“是经理”相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是钱，不是职位，“工资是经理”句意不通。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：“办公室”是地点，不是职位名称，不能说“办公室是经理”。"}, {"text": "任务", "is_correct": false, "explanation": "搭配：“任务”指要完成的工作，不能说“任务是经理”。"}], "explanations": {"职务": "正确。“职务”指在公司担任的职位，与“是经理”相符。", "工资": "语义：“工资”是钱，不是职位，“工资是经理”句意不通。", "办公室": "语义：“办公室”是地点，不是职位名称，不能说“办公室是经理”。", "任务": "搭配：“任务”指要完成的工作，不能说“任务是经理”。"}, "sentence_index": 0, "correct_answer": "职务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的职务是学生。", "explanation": "这里应该用〈身份〉。职务指在单位里担任的职位，学生不是单位里的职务。"}, {"text": "他的职务是男。", "explanation": "这里应该用〈性别〉。职务指在单位里担任的职位或要做的工作，不能表示一个人的性别。"}, {"text": "他的职务是北京人。", "explanation": "这里应该用〈籍贯〉。职务指在单位里担任的职位，不能表示籍贯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87881, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "职务", "is_correct": true, "explanation": "正确。职务：一个人在单位里要做的事和他的名称。"}, {"text": "实物", "is_correct": false, "explanation": "shí（第二声）与 zhí（第二声）声母不同，意思是实际的物品。"}, {"text": "时务", "is_correct": false, "explanation": "shí（第二声）与 zhí（第二声）只差声母（sh/zh），意思是当前的要务。"}, {"text": "织物", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）只差声调，意思是纺织品。"}], "explanations": {"职务": "正确。职务：一个人在单位里要做的事和他的名称。", "实物": "shí（第二声）与 zhí（第二声）声母不同，意思是实际的物品。", "时务": "shí（第二声）与 zhí（第二声）只差声母（sh/zh），意思是当前的要务。", "织物": "zhī（第一声）与 zhí（第二声）只差声调，意思是纺织品。"}, "sentence_index": null, "correct_answer": "职务"}, "level_3": {"options": [{"text": "职务", "is_correct": true, "explanation": "正确。“职务”指担任的职位，与“退休前的……是校长”相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，不是职位，“年龄是校长”句意不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指个性，不是工作岗位，不能说“性格是校长”。"}, {"text": "宿舍", "is_correct": false, "explanation": "搭配：“宿舍”是住的地方，不能作职位名称，不能说“宿舍是校长”。"}], "explanations": {"职务": "正确。“职务”指担任的职位，与“退休前的……是校长”相符。", "年龄": "语义：“年龄”指岁数，不是职位，“年龄是校长”句意不通。", "性格": "语义：“性格”指个性，不是工作岗位，不能说“性格是校长”。", "宿舍": "搭配：“宿舍”是住的地方，不能作职位名称，不能说“宿舍是校长”。"}, "sentence_index": 6, "correct_answer": "职务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的职务是硕士。", "explanation": "这里应该用〈学历〉。职务指工作中的职位，硕士是学历。"}, {"text": "他的职务是三十岁。", "explanation": "这里应该用〈年龄〉。职务是岗位，不能用来表示岁数。"}, {"text": "他的职务是一米八。", "explanation": "这里应该用〈身高〉。职务是岗位，不能用来表示身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
