INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他担任一本职务。", "corrected_sentence": "他担任一个职务。", "error_description": "量词错误：“职务”的量词应为“个”，“本”只用于书籍等。应说“担任一个职务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
