INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87883, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "大为是很多、很大的意思。", "primary_collocate": null, "pronunciation": "dà wéi", "ipa": "ta˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这次比赛的结果令人大为意外。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家以后，他的生活大为方便。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听完介绍，客人对这家店的印象大为改观。", "target_word": "大为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个消息让他大为震惊。", "target_word": "大为", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气转暖后，来公园的人数大为增加。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板看到报告，大为生气。", "target_word": "大为", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听到坏消息，大家大为失望。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了新电脑，他的打字速度大为加快。", "target_word": "大为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看到魔术，大为惊奇。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过一年锻炼，他的身体状况大为改善。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "表示数量多、幅度大或程度深，常修饰表示情绪或变化的词语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08fec9-be23-4df3-b23e-efdc278f5158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings 