INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大为", "is_correct": true, "explanation": "正确：“大为”表示幅度很大，修饰“意外”，与原句一致。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”修饰人的具体行动，不能修饰“意外”这类心理状态。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示长期如此，与“这次比赛的结果”这一次性事件矛盾。"}, {"text": "处处", "is_correct": false, "explanation": "搭配：“处处”指各个地方，不能修饰“令人意外”这种心理反应。"}], "explanations": {"大为": "正确：“大为”表示幅度很大，修饰“意外”，与原句一致。", "亲自": "搭配：“亲自”修饰人的具体行动，不能修饰“意外”这类心理状态。", "从不": "语义：“从不”表示长期如此，与“这次比赛的结果”这一次性事件矛盾。", "处处": "搭配：“处处”指各个地方，不能修饰“令人意外”这种心理反应。"}, "sentence_index": 0, "correct_answer": "大为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服大为放在箱子里。", "explanation": "这里应该用〈随便〉。“大为”表示程度很深，不能修饰“放在箱子里”这样的一般动作。"}, {"text": "他大为走了。", "explanation": "这里应该用〈已经〉。“大为”表示程度很深，不能修饰“走了”这样的动作完成。"}, {"text": "这本书大为出版了三次。", "explanation": "这里应该用〈先后〉。“大为”表示程度很深，不能用来说明次数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大为", "is_correct": true, "explanation": "正确：“大为”表示程度很深，修饰“失望”，与原句一致。"}, {"text": "大力", "is_correct": false, "explanation": "搭配：“大力”修饰具体的行动，不能修饰“失望”这类心理状态。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”表示长期如此，与“听到坏消息”这一具体事件矛盾。"}, {"text": "竭力", "is_correct": false, "explanation": "搭配：“竭力”表示尽力去做某事，不能修饰“失望”这种情绪。"}], "explanations": {"大为": "正确：“大为”表示程度很深，修饰“失望”，与原句一致。", "大力": "搭配：“大力”修饰具体的行动，不能修饰“失望”这类心理状态。", "一向": "语义：“一向”表示长期如此，与“听到坏消息”这一具体事件矛盾。", "竭力": "搭配：“竭力”表示尽力去做某事，不能修饰“失望”这种情绪。"}, "sentence_index": 6, "correct_answer": "大为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司大为聘请了一名员工。", "explanation": "这里应该用〈只〉。“大为”表示程度很深，不能修饰“聘请一名员工”这样数量很少的事。"}, {"text": "他的身体大为强壮了一点。", "explanation": "这里应该用〈稍微〉。“大为”表示幅度很大，与“一点”表示的轻微程度相矛盾。"}, {"text": "他大为睡着了。", "explanation": "这里应该用〈很快〉。“大为”表示程度很深，不能修饰“睡着”这样的状态变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年，来这里旅游的人很大为增加。", "corrected_sentence": "这几年，来这里旅游的人大为增加。", "error_description": "“大为”前面不能再加“很”，两者都表示程度：应说“大为增加”，不说“很大为增加”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动，报名的人数大为的增加。", "corrected_sentence": "这次活动，报名的人数大为增加。", "error_description": "“大为”是副词，不能用“的”连接动词“增加”：应说“大为增加”，不说“大为的增加”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
