INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87885, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "琴是用手弹或拉，就能发出好听声音的东西。", "primary_collocate": null, "pronunciation": "qín", "ipa": "tɕʰin˧˥", "syllable_count": 1, "sentences": [{"text": "她用手弹琴，声音很好听。", "target_word": "琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有人在拉琴。", "target_word": "琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把琴放在桌子上。", "target_word": "琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "琴放在窗边，阳光照着它。", "target_word": "琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一把便宜的琴。", "target_word": "琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这把琴拉起来很好听。", "target_word": "琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "女儿喜欢听妈妈弹琴。", "target_word": "琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的琴坏了，声音不好听。", "target_word": "琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们围着老人听他拉琴。", "target_word": "琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上她一个人在家弹琴。", "target_word": "琴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "张", "label": "量词"}], "register": "中性", "sense_fingerprint": "用手弹或拉发出悦耳声音的乐器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e864c1b8-57ca-4d3b-9755-214d3c6e6153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "琴", "is_correct": true, "explanation": "正确：琴 qín，弦乐器。"}, {"text": "亲", "is_correct": false, "explanation": "亲 qīn（第一声）与 qín（第二声）声调不同，意思是亲人。"}, {"text": "寝", "is_correct": false, "explanation": "寝 qǐn（第三声）与 qín（第二声）声调不同，意思是睡觉、寝室。"}, {"text": "情", "is_correct": false, "explanation": "情 qíng 与 qín 韵母不同（-ng 与 -n），意思是感情。"}, {"text": "沁", "is_correct": false, "explanation": "沁 qìn（第四声）与 qín（第二声）声调不同，意思是渗入。"}], "explanations": {"琴": "正确：琴 qín，弦乐器。", "亲": "亲 qīn（第一声）与 qín（第二声）声调不同，意思是亲人。", "寝": "寝 qǐn（第三声）与 qín（第二声）声调不同，意思是睡觉、寝室。", "情": "情 qíng 与 qín 韵母不同（-ng 与 -n），意思是感情。", "沁": "沁 qìn（第四声）与 qín（第二声）声调不同，意思是渗入。"}, "sentence_index": null, "correct_answer": "琴"}, "level_3": {"options": [{"text": "琴", "is_correct": true, "explanation": "正确：“用手弹琴”是动宾搭配，“琴”是乐器，“声音很好听”也符合。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“弹”后面接乐器，不接“歌”，“用手弹歌”不通。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能用手弹，“用手弹”的对象只能是乐器。"}, {"text": "纸", "is_correct": false, "explanation": "配价：“弹”的宾语须是乐器，“纸”不能作它的宾语。"}], "explanations": {"琴": "正确：“用手弹琴”是动宾搭配，“琴”是乐器，“声音很好听”也符合。", "歌": "搭配：“弹”后面接乐器，不接“歌”，“用手弹歌”不通。", "水": "语义：水不能用手弹，“用手弹”的对象只能是乐器。", "纸": "配价：“弹”的宾语须是乐器，“纸”不能作它的宾语。"}, "sentence_index": 0, "correct_answer": "琴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家有一块琴，很旧。", "explanation": "这里应该用〈把〉。量词“块”用于片状的东西，琴不能用“块”。"}, {"text": "我想买一幅琴。", "explanation": "这里应该用〈把〉。量词“幅”用于画，琴不能用“幅”。"}, {"text": "她有一根琴，拉得很好。", "explanation": "这里应该用〈把〉。量词“根”用于细长条状的东西，琴不能用“根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87885, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "琴", "is_correct": true, "explanation": "正确：琴 qín，弦乐器。"}, {"text": "侵", "is_correct": false, "explanation": "侵 qīn（第一声）与 qín（第二声）声调不同，意思是侵犯。"}, {"text": "晴", "is_correct": false, "explanation": "晴 qíng 与 qín 韵母不同（-ng 与 -n），意思是晴朗。"}, {"text": "前", "is_correct": false, "explanation": "前 qián 与 qín 韵母不同（qián 多一个 a），意思是前面。"}], "explanations": {"琴": "正确：琴 qín，弦乐器。", "侵": "侵 qīn（第一声）与 qín（第二声）声调不同，意思是侵犯。", "晴": "晴 qíng 与 qín 韵母不同（-ng 与 -n），意思是晴朗。", "前": "前 qián 与 qín 韵母不同（qián 多一个 a），意思是前面。"}, "sentence_index": null, "correct_answer": "琴"}, "level_3": {"options": [{"text": "琴", "is_correct": true, "explanation": "正确：“听妈妈弹琴”指弹奏乐器，与“女儿喜欢听”的语境一致。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“弹”的宾语是乐器，“饭”不能被“弹”，“弹饭”不成词。"}, {"text": "门", "is_correct": false, "explanation": "语义：门不是乐器，弹门发不出可以“听”的音乐。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能弹，“听妈妈弹书”不合常理。"}], "explanations": {"琴": "正确：“听妈妈弹琴”指弹奏乐器，与“女儿喜欢听”的语境一致。", "饭": "搭配：“弹”的宾语是乐器，“饭”不能被“弹”，“弹饭”不成词。", "门": "语义：门不是乐器，弹门发不出可以“听”的音乐。", "书": "语义：书不能弹，“听妈妈弹书”不合常理。"}, "sentence_index": 6, "correct_answer": "琴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚上她一个人在家踢琴。", "explanation": "这里应该用〈弹〉。琴靠手弹或拉发声，不能用“踢”。"}, {"text": "晚上她一个人在家撕琴。", "explanation": "这里应该用〈弹〉。琴靠手弹或拉发声，不能用“撕”。"}, {"text": "晚上她一个人在家摇琴。", "explanation": "这里应该用〈弹〉。琴靠手弹或拉发声，不能用“摇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶留给我一根琴。", "corrected_sentence": "奶奶留给我一把琴。", "error_description": "量词错误：“琴”应搭配量词“把”，“根”用于细长条状的东西，说“一根琴”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天买了一根琴。", "corrected_sentence": "妈妈昨天买了一把琴。", "error_description": "量词错误：“琴”应搭配量词“把”，“根”用于细长条状的东西，说“一根琴”不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
