INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "弦乐器或某些乐器的统称，如钢琴、古琴、小提琴。", "primary_collocate": null, "pronunciation": "qín", "ipa": "tɕʰin˧˥", "syllable_count": 1, "sentences": [{"text": "她会弹琴，也会拉琴。", "target_word": "琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家有一把很旧的琴。", "target_word": "琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明每天晚上都要练琴。", "target_word": "琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从五岁开始学琴。", "target_word": "琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸给我买了一把新琴。", "target_word": "琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那把琴是爷爷留下来的。", "target_word": "琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把琴的声音很好听。", "target_word": "琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不在家，在朋友家弹琴。", "target_word": "琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想学哪一种琴？", "target_word": "琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，学琴要有耐心。", "target_word": "琴", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "张", "label": "量词"}], "register": "中性", "sense_fingerprint": "弦乐器或乐器的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e864c1b8-57ca-4d3b-9755-214d3c6e6153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
