eration_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87886, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "琴", "is_correct": true, "explanation": "正确：琴 qín，弦乐器。"}, {"text": "侵", "is_correct": false, "explanation": "侵 qīn（第一声）与 qín（第二声）声调不同，意思是侵犯。"}, {"text": "晴", "is_correct": false, "explanation": "晴 qíng 与 qín 韵母不同（-ng 与 -n），意思是晴朗。"}, {"text": "前", "is_correct": false, "explanation": "前 qián 与 qín 韵母不同（qián 多一个 a），意思是前面。"}], "explanations": {"琴": "正确：琴 qín，弦乐器。", "侵": "侵 qīn（第一声）与 qín（第二声）声调不同，意思是侵犯。", "晴": "晴 qíng 与 qín 韵母不同（-ng 与 -n），意思是晴朗。", "前": "前 qián 与 qín 韵母不同（qián 多一个 a），意思是前面。"}, "sentence_index": null, "correct_answer": "琴"}, "level_3": {"options": [{"text": "琴", "is_correct": true, "explanation": "正确：“这把琴”指乐器，“声音很好听”符合乐器的特点。"}, {"text": "伞", "is_correct": false, "explanation": "语义：伞不发出悦耳的声音，不能说“伞的声音很好听”。"}, {"text": "尺", "is_correct": false, "explanation": "语义：尺子没有可供欣赏的声音，与“声音很好听”不合。"}, {"text": "饼", "is_correct": false, "explanation": "语义：饼没有可供欣赏的声音，“这把饼的声音很好听”不通。"}], "explanations": {"琴": "正确：“这把琴”指乐器，“声音很好听”符合乐器的特点。", "伞": "语义：伞不发出悦耳的声音，不能说“伞的声音很好听”。", "尺": "语义：尺子没有可供欣赏的声音，与“声音很好听”不合。", "饼": "语义：饼没有可供欣赏的声音，“这把饼的声音很好听”不通。"}, "sentence_index": 6, "correct_answer": "琴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上都在家踢琴。", "explanation": "动宾搭配错误：琴要用手“弹”或“拉”，不能“踢”。"}, {"text": "这把琴很好吃。", "explanation": "语义错误：琴是乐器，不能吃，不能说“好吃”。"}, {"text": "我在琴上喝了一杯水。", "explanation": "语义错误：琴是用来演奏的乐器，不是喝水的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈送给我一头旧琴。", "corrected_sentence": "妈妈送给我一把旧琴。", "error_description": "量词错误：“琴”应搭配量词“把”，“头”用于牲畜，说“一头琴”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他琴把放进箱子里了。", "corrected_sentence": "他把琴放进箱子里了。", "error_description": "语序错误：“把”要放在被处理的对象“琴”之前，应说“把琴放进”，不能说“琴把放进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
