INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87889, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "百分点是用来比两个百分数差多少的。", "primary_collocate": null, "pronunciation": "bǎi fēn diǎn", "ipa": "pai˨˩ fən˥ tjɛn˨˩", "syllable_count": 3, "sentences": [{"text": "今年的比例比去年高三个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "男生和女生差两个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的数字下降了五个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次民调的支持率比上个月高了三个百分点。", "target_word": "百分点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市的比例只差一个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年的通货膨胀率比去年高了一个百分点。", "target_word": "百分点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的比例比去年低两个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试的通过率比上次多了六个百分点。", "target_word": "百分点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个数字差几个百分点？", "target_word": "百分点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个百分数只差零点五个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "比较两个百分数差距的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e864c1b8-57ca-4d3b-9755-214d3c6e6153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87889, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "百分点", "is_correct": true, "explanation": "正确：“高三个百分点”是两个百分数之差，与“比例比去年高”一致。"}, {"text": "公斤", "is_correct": false, "explanation": "语义：比例的差距不用重量单位衡量，“高三个公斤”不通。"}, {"text": "元", "is_correct": false, "explanation": "语义：比例不以货币计量，“高三个元”没有意义。"}, {"text": "米", "is_correct": false, "explanation": "搭配：“高三米”可以说，但比例不用长度单位，“高三个米”也不自然。"}], "explanations": {"百分点": "正确：“高三个百分点”是两个百分数之差，与“比例比去年高”一致。", "公斤": "语义：比例的差距不用重量单位衡量，“高三个公斤”不通。", "元": "语义：比例不以货币计量，“高三个元”没有意义。", "米": "搭配：“高三米”可以说，但比例不用长度单位，“高三个米”也不自然。"}, "sentence_index": 0, "correct_answer": "百分点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天走了三个百分点的路。", "explanation": "用法错误：百分点只表示百分数之差，不能用来计量路程。"}, {"text": "收入比去年多了一个百分点。", "explanation": "用法错误：收入本身不是百分数，百分点不能直接计量收入的变化，应说“多了百分之一”。"}, {"text": "这个城市的平均温度比去年高了三个百分点。", "explanation": "这里应该用〈三度〉。百分点只用于百分数之差，温度的变化要用度数表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "百分点", "is_correct": true, "explanation": "正确：“低两个百分点”表示两个百分数之差，与“比例比去年低”一致。"}, {"text": "斤", "is_correct": false, "explanation": "语义：斤是重量单位，比例的差距不能用重量衡量。"}, {"text": "度", "is_correct": false, "explanation": "语义：度是温度或角度单位，“比例低两度”没有意义。"}, {"text": "次", "is_correct": false, "explanation": "搭配：“次”计数动作或次数，“比例低两次”不通。"}], "explanations": {"百分点": "正确：“低两个百分点”表示两个百分数之差，与“比例比去年低”一致。", "斤": "语义：斤是重量单位，比例的差距不能用重量衡量。", "度": "语义：度是温度或角度单位，“比例低两度”没有意义。", "次": "搭配：“次”计数动作或次数，“比例低两次”不通。"}, "sentence_index": 6, "correct_answer": "百分点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次民调的支持率是三个百分点。", "explanation": "用法错误：百分点表示两个百分数之差，不能单独说某个比例是几个百分点，应说“支持率是百分之三”。"}, {"text": "这个学校有十个百分点的学生。", "explanation": "用法错误：百分点只用于比较百分数的差距，不能用来计数学生。"}, {"text": "他的身高比上个月高了十个百分点。", "explanation": "用法错误：身高是长度，应说“高了十厘米”，百分点不能用来计量身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的失业率比去年低了零点四百分点。", "corrected_sentence": "今年的失业率比去年低了零点四个百分点。", "error_description": "量词错误：“百分点”前的数量词要带量词“个”，应说“零点四个百分点”，不说“零点四百分点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的失业率比去年高了两个百分数。", "corrected_sentence": "今年的失业率比去年高了两个百分点。", "error_description": "用词错误：两个百分数之间的差距要用“百分点”，不说“两个百分数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
