INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87890, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "表示两个百分数之差的单位，一个百分点即百分之一。", "primary_collocate": null, "pronunciation": "bǎi fēn diǎn", "ipa": "pai˨˩ fən˥ tjɛn˨˩", "syllable_count": 3, "sentences": [{"text": "一个百分点就是百分之一。", "target_word": "百分点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "利率提高了半个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济增长率上升了两个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失业率下降了零点三个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行把利率降低了一个百分点。", "target_word": "百分点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从百分之十到百分之十二，是两个百分点。", "target_word": "百分点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的人口增长率比去年高一个百分点。", "target_word": "百分点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个百分点的差别不算大。", "target_word": "百分点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试合格率提高了八个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报告说，物价只涨了一个百分点。", "target_word": "百分点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "表示百分数之差的单位，一个等于百分之一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e864c1b8-57ca-4d3b-9755-214d3c6e6153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "百分点", "is_correct": true, "explanation": "正确：“一个百分点就是百分之一”，“百分点”指百分之一的差。"}, {"text": "度", "is_correct": false, "explanation": "语义：度是温度或角度单位，与“百分之一”的比例无关。"}, {"text": "倍", "is_correct": false, "explanation": "搭配：“一倍”指增长一倍，不能与“就是百分之一”构成等式，“一个倍”也不是常用说法。"}, {"text": "步", "is_correct": false, "explanation": "搭配：“步”指距离或动作，不能与“就是百分之一”构成等式。"}], "explanations": {"百分点": "正确：“一个百分点就是百分之一”，“百分点”指百分之一的差。", "度": "语义：度是温度或角度单位，与“百分之一”的比例无关。", "倍": "搭配：“一倍”指增长一倍，不能与“就是百分之一”构成等式，“一个倍”也不是常用说法。", "步": "搭配：“步”指距离或动作，不能与“就是百分之一”构成等式。"}, "sentence_index": 0, "correct_answer": "百分点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书有两个百分点那么厚。", "explanation": "用法错误：百分点只表示百分数之差，不能用来描述厚度。"}, {"text": "销量比去年翻了一个百分点。", "explanation": "这里应该用〈一倍〉。百分点只用于百分数之差，销量的增长要用倍数表示。"}, {"text": "他的身高比去年高了两个百分点。", "explanation": "这里应该用〈两厘米〉。百分点只用于百分数之差，身高要用长度单位表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "百分点", "is_correct": true, "explanation": "正确：“比去年高一个百分点”表示增长率之差，与句意一致。"}, {"text": "斤", "is_correct": false, "explanation": "语义：斤是重量单位，人口增长率不能用重量衡量。"}, {"text": "次", "is_correct": false, "explanation": "搭配：“次”计数动作或次数，“增长率比去年高一次”不通。"}, {"text": "公里", "is_correct": false, "explanation": "语义：公里是长度单位，与人口增长率无关。"}], "explanations": {"百分点": "正确：“比去年高一个百分点”表示增长率之差，与句意一致。", "斤": "语义：斤是重量单位，人口增长率不能用重量衡量。", "次": "搭配：“次”计数动作或次数，“增长率比去年高一次”不通。", "公里": "语义：公里是长度单位，与人口增长率无关。"}, "sentence_index": 6, "correct_answer": "百分点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一个百分点的水果。", "explanation": "用法错误：百分点只用于比较百分数之差，不能用来计量水果。"}, {"text": "这个班有一个百分点的同学迟到了。", "explanation": "用法错误：百分点不能用来计数人，应直接说“一个同学”。"}, {"text": "他一口气喝了一个百分点的水。", "explanation": "用法错误：百分点不是体积或重量单位，不能用来计量水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的通货膨胀率下降了零点五百分点。", "corrected_sentence": "今年的通货膨胀率下降了零点五个百分点。", "error_description": "量词错误：“百分点”前要用量词“个”，应说“零点五个百分点”，不说“零点五百分点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的人口增长率比去年高了一个百分数。", "corrected_sentence": "今年的人口增长率比去年高了一个百分点。", "error_description": "用词错误：两个百分数之差要用“百分点”，不说“一个百分数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
