INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "持有公司股份的人或单位。", "primary_collocate": null, "pronunciation": "gǔ dōng", "ipa": "ku²¹⁴ tʊŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "这家银行持有公司的大量股份，是股东。", "target_word": "股东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要把一部分钱分给股东。", "target_word": "股东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位股东手里有公司百分之十的股份。", "target_word": "股东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司欢迎新股东加入。", "target_word": "股东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股东要看公司去年的账。", "target_word": "股东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的股东是个人，有的是公司。", "target_word": "股东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的股东来自三个国家。", "target_word": "股东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他卖掉了股份，不再是股东了。", "target_word": "股东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的股东换了，经理也换了。", "target_word": "股东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位股东对这个计划有不同意见。", "target_word": "股东", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名股东", "label": "量词"}, {"form": "小股东", "label": "复合"}], "register": "中性", "sense_fingerprint": "持有公司股份的个人或单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43e9cbc-284b-4337-94c6-a22041e14477') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客户", "is_correct": false, "explanation": "语义：“客户”是购买服务的人，与持有股份的身份不符。"}, {"text": "股东", "is_correct": true, "explanation": "正确。持有公司大量股份的单位就是股东，这里指银行是股东。"}, {"text": "股份", "is_correct": false, "explanation": "搭配：“是”后接身份，不能说“是股份”，股份是份额。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校与持有股份无关，句中“是”后要的是持股的身份。"}], "explanations": {"客户": "语义：“客户”是购买服务的人，与持有股份的身份不符。", "股东": "正确。持有公司大量股份的单位就是股东，这里指银行是股东。", "股份": "搭配：“是”后接身份，不能说“是股份”，股份是份额。", "学校": "语义：学校与持有股份无关，句中“是”后要的是持股的身份。"}, "sentence_index": 0, "correct_answer": "股东"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司欢迎新股东来店里买东西。", "explanation": "这里应该用〈顾客〉。来店里买东西的是顾客，股东是持有公司股份的人或单位。"}, {"text": "公司招聘了一批新股东。", "explanation": "这里应该用〈员工〉。招聘的是员工，股东是出资持股的人，不能招聘。"}, {"text": "公司发行了新股东，欢迎大家购买。", "explanation": "这里应该用〈股票〉。发行和购买的是股票，股东是持有股份的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是公司的一部分，不能“来自三个国家”。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“来自”后接的是人或单位，不能说“方向来自三个国家”。"}, {"text": "股东", "is_correct": true, "explanation": "正确。“股东”是持有公司股份的人或单位，可以来自不同国家。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是活动，不会“来自三个国家”，与“公司的”搭配不通。"}], "explanations": {"天气": "语义：天气不是公司的一部分，不能“来自三个国家”。", "方向": "搭配：“来自”后接的是人或单位，不能说“方向来自三个国家”。", "股东": "正确。“股东”是持有公司股份的人或单位，可以来自不同国家。", "考试": "语义：考试是活动，不会“来自三个国家”，与“公司的”搭配不通。"}, "sentence_index": 6, "correct_answer": "股东"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几位股东看起来很好吃。", "explanation": "股东是人或单位，不能用“好吃”来形容，与词义相悖。"}, {"text": "我们把几位股东拿去喂狗了。", "explanation": "股东是人或单位，不能拿去喂狗，“喂”的对象应是食物。"}, {"text": "这几位股东是一本书。", "explanation": "股东指持有股份的人或单位，不能是书，二者不属于同一类事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几位新股东们已经同意了这个计划。", "corrected_sentence": "几位新股东已经同意了这个计划。", "error_description": "错误：“几位”后面不能再加“们”。正确：“几位新股东”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家饭店有五股东。", "corrected_sentence": "那家饭店有五个股东。", "error_description": "错误：数词和名词之间缺少量词。正确：“有五个股东”，“个”可用于一般的人或单位。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
