INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87895, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87895, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "秋天是夏天以后的那一季。天气变凉，树叶会变黄。", "primary_collocate": null, "pronunciation": "qiū tiān", "ipa": "tɕʰi̯oʊ˥ tʰi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "秋天来了，天气变凉了，我穿上了外套。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，公园里的树叶都黄了。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到秋天，树叶就慢慢变黄。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天过去以后，冬天就要来了。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太热，我更喜欢凉快的秋天。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的风吹着树叶，叶子一片一片落下来。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年秋天，我们去公园看黄叶。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天天气很好，不冷也不热。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶黄了，妈妈说秋天要多穿一件衣服。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢秋天，因为树叶黄得很漂亮。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "季节：夏天之后，天气变凉、树叶变黄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秋天", "is_correct": true, "explanation": "正确：“秋天”是季节，“来了”引出天气变凉、穿外套的情况。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天炎热，与“天气变凉了，我穿上了外套”矛盾。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“书包”不是季节，不能用“来了”引出天气变化。"}, {"text": "端午节", "is_correct": false, "explanation": "语义：端午节在夏天，不会带来天气变凉。"}], "explanations": {"秋天": "正确：“秋天”是季节，“来了”引出天气变凉、穿外套的情况。", "夏天": "语义：夏天炎热，与“天气变凉了，我穿上了外套”矛盾。", "书包": "搭配：“书包”不是季节，不能用“来了”引出天气变化。", "端午节": "语义：端午节在夏天，不会带来天气变凉。"}, "sentence_index": 0, "correct_answer": "秋天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这学期是秋天学期。", "explanation": "这里应该用〈秋季〉。“秋季学期”是固定说法，“秋天”指季节本身，不作学期名。"}, {"text": "农民们忙着秋天，粮仓都满了。", "explanation": "这里应该用〈秋收〉。“秋天”是季节，不能作“忙”的对象，表示收获的活动要用“秋收”。"}, {"text": "周末我们去秋天了。", "explanation": "这里应该用〈秋游〉。“秋天”是季节，不能当作去的地方或活动，秋季郊游要说秋游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秋天", "is_correct": true, "explanation": "正确：“秋天”是季节，与“树叶黄了”的去年经历相符。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天的树叶多是绿的，与“看黄叶”矛盾。"}, {"text": "深夜", "is_correct": false, "explanation": "搭配：“深夜”光线暗，与“去公园看黄叶”不搭。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”不是时间，不能与“去年”搭配。"}], "explanations": {"秋天": "正确：“秋天”是季节，与“树叶黄了”的去年经历相符。", "春天": "语义：春天的树叶多是绿的，与“看黄叶”矛盾。", "深夜": "搭配：“深夜”光线暗，与“去公园看黄叶”不搭。", "雨伞": "语义：“雨伞”不是时间，不能与“去年”搭配。"}, "sentence_index": 6, "correct_answer": "秋天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的秋天今年五岁了。", "explanation": "这里应该用〈孩子〉。“秋天”是季节，不能指人，说人的年龄要用孩子。"}, {"text": "我们班今天去参加秋天。", "explanation": "这里应该用〈秋游〉。“秋天”是季节，不能作“参加”的对象，参加的活动要说秋游。"}, {"text": "一阵秋天吹了过来。", "explanation": "这里应该用〈秋风〉。“秋天”指季节，不能指一阵风，吹来的风要说秋风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只秋天，我第一次去了香山。", "corrected_sentence": "这个秋天，我第一次去了香山。", "error_description": "错误：“这只秋天”；正确：“这个秋天”。“秋天”作时间名词，量词用“个”，不用“只”（“只”多用于动物或成对物件中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每秋天我们都去公园看黄叶。", "corrected_sentence": "每个秋天我们都去公园看黄叶。", "error_description": "错误：“每秋天”，漏了量词；正确：“每个秋天”。“每”后接时间词时要带量词“个”或“年”，如“每个秋天”“每年秋天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
