INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "四季中的第三季，天气由热转凉，庄稼成熟。", "primary_collocate": null, "pronunciation": "qiū tiān", "ipa": "tɕʰi̯oʊ˥ tʰi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "秋天到了，农民们忙着收玉米。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天是庄稼成熟的季节。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田里的稻子到了秋天就黄了。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，爷爷把一车苹果运到城里卖。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天种的玉米，秋天就能收了。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年庄稼长得好，到了秋天一定能多收粮。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民说，秋天是一年里最忙的时候。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的田里到处都是黄色的稻子。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到秋天，果园里的梨和苹果都熟了。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家秋天收了很多粮食。", "target_word": "秋天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "四季第三季：庄稼成熟、农民收获的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秋天", "is_correct": true, "explanation": "正确：“秋天”是玉米收获的季节，与“忙着收玉米”相符。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：冬天不是玉米收获的季节，与“忙着收玉米”矛盾。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是播种的季节，与“收玉米”不符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”不是时间，不能用“到了”引出收玉米的季节。"}], "explanations": {"秋天": "正确：“秋天”是玉米收获的季节，与“忙着收玉米”相符。", "冬天": "语义：冬天不是玉米收获的季节，与“忙着收玉米”矛盾。", "春天": "语义：春天是播种的季节，与“收玉米”不符。", "书包": "语义：“书包”不是时间，不能用“到了”引出收玉米的季节。"}, "sentence_index": 0, "correct_answer": "秋天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民们忙着秋天，粮仓都满了。", "explanation": "这里应该用〈秋收〉。“秋天”是季节，不能作“忙”的对象，表示收获的活动要用“秋收”。"}, {"text": "这些秋天很好吃，我们都爱吃。", "explanation": "这里应该用〈玉米〉。“秋天”是季节，不能当作吃的东西，要说玉米。"}, {"text": "农民们正在种秋天。", "explanation": "这里应该用〈小麦〉。“秋天”是时间，不能作“种”的对象，种的应是庄稼，如小麦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秋天", "is_correct": true, "explanation": "正确：“秋天”是农民最忙的季节，与“一年里最忙的时候”相符。"}, {"text": "寒假", "is_correct": false, "explanation": "语义：寒假是学生的假期，不是农民一年里最忙的时候。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不能是农忙的时候，与句意矛盾。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“上午”是一天里的时段，与“一年里”搭配不当。"}], "explanations": {"秋天": "正确：“秋天”是农民最忙的季节，与“一年里最忙的时候”相符。", "寒假": "语义：寒假是学生的假期，不是农民一年里最忙的时候。", "月亮": "语义：“月亮”不能是农忙的时候，与句意矛盾。", "上午": "搭配：“上午”是一天里的时段，与“一年里”搭配不当。"}, "sentence_index": 6, "correct_answer": "秋天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们家的秋天很多，吃不完。", "explanation": "这里应该用〈收成〉。“秋天”指季节，不能指收成的多少，要说收成。"}, {"text": "他们家把秋天收进仓库里了。", "explanation": "这里应该用〈粮食〉。“秋天”是季节，不能被收进仓库，收进仓库的应是粮食。"}, {"text": "他们家的秋天一袋一袋地装好了。", "explanation": "这里应该用〈稻谷〉。“秋天”是季节，不能被装袋，装袋的应是稻谷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只秋天，农民们在地里收玉米。", "corrected_sentence": "这个秋天，农民们在地里收玉米。", "error_description": "错误：“这只秋天”；正确：“这个秋天”。“秋天”作时间词，量词用“个”，不用“只”（“只”多用于动物或成对物件中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每秋天，农民们都在田里忙着收粮食。", "corrected_sentence": "每个秋天，农民们都在田里忙着收粮食。", "error_description": "错误：“每秋天”，漏了量词；正确：“每个秋天”。“每”后接时间词时要带量词“个”或“年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
