INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87899, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "业务是一个人每天要做的工作。", "primary_collocate": null, "pronunciation": "yè wù", "ipa": "jɛ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "他每天的业务是接电话和回邮件。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同事还不熟悉业务，我来教他。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的业务不多，下午就能做完。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月业务太多，他天天加班。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王的业务是管仓库。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把业务做得又快又好。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先把今天的业务写在本子上。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "业务不忙的时候，我们一起喝茶。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李刚来，业务还不太熟。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了部门，业务也不一样了。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项业务", "label": "量词"}, {"form": "業務", "label": "繁体"}, {"form": "业务员", "label": "复合"}, {"form": "业务范围", "label": "复合"}], "register": "通用", "sense_fingerprint": "业务：个人每天负责去做的具体工作内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70440bbe-270b-40e4-ad01-5390c3128607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87899, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "业务", "is_correct": true, "explanation": "正确：业务，指个人每天要做的工作。"}, {"text": "业余", "is_correct": false, "explanation": "第二个音节 yú（第二声）与 wù（第四声）不同，意思是业余。"}, {"text": "夜路", "is_correct": false, "explanation": "第二个音节 lù（第四声）与 wù 只差声母，意思是夜里走的路。"}, {"text": "夜幕", "is_correct": false, "explanation": "第二个音节 mù（第四声）与 wù 声母不同，意思是笼罩夜空的样子。"}, {"text": "夜露", "is_correct": false, "explanation": "第二个音节 lù（第四声）与 wù 只差声母，意思是夜间的露水。"}], "explanations": {"业务": "正确：业务，指个人每天要做的工作。", "业余": "第二个音节 yú（第二声）与 wù（第四声）不同，意思是业余。", "夜路": "第二个音节 lù（第四声）与 wù 只差声母，意思是夜里走的路。", "夜幕": "第二个音节 mù（第四声）与 wù 声母不同，意思是笼罩夜空的样子。", "夜露": "第二个音节 lù（第四声）与 wù 只差声母，意思是夜间的露水。"}, "sentence_index": null, "correct_answer": "业务"}, "level_3": {"options": [{"text": "业务", "is_correct": true, "explanation": "正确：业务，指每天要做的工作，与“接电话和回邮件”相符。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：饮食指吃喝，与接电话、回邮件无关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人活了多少年，不能是“接电话和回邮件”。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”通常说“发、领、涨”，不说“工资是做某件事”。"}], "explanations": {"业务": "正确：业务，指每天要做的工作，与“接电话和回邮件”相符。", "饮食": "语义：饮食指吃喝，与接电话、回邮件无关。", "年龄": "语义：年龄指人活了多少年，不能是“接电话和回邮件”。", "工资": "搭配：“工资”通常说“发、领、涨”，不说“工资是做某件事”。"}, "sentence_index": 0, "correct_answer": "业务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这个月接了一只业务。", "explanation": "这里应该用〈项〉。业务作量词用“项”，“只”多用于动物或单个物件，不用来数业务。"}, {"text": "他的业务是医生。", "explanation": "这里应该用〈职业〉。问人的身份用“职业”；业务指每天要做的工作内容，不能说“业务是医生”。"}, {"text": "他每个月的业务很高。", "explanation": "这里应该用〈工作量〉。“业务”指要做的工作，不指收入或价格，所以不能直接用“高”来形容；说工作多少要用“工作量大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87899, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "业务", "is_correct": true, "explanation": "正确：业务，指个人每天要做的工作。"}, {"text": "异物", "is_correct": false, "explanation": "第一个音节 yì（第四声）与 yè 只差韵母，意思是不该出现的外来物。"}, {"text": "野物", "is_correct": false, "explanation": "第一个音节 yě（第三声）与 yè（第四声）只差声调，意思是野生的动物。"}, {"text": "衣物", "is_correct": false, "explanation": "第一个音节 yī（第一声）与 yè（第四声）只差声调，意思是衣服等物品。"}, {"text": "遗物", "is_correct": false, "explanation": "第一个音节 yí（第二声）与 yè 声调和韵母都不同，意思是死者留下的物品。"}], "explanations": {"业务": "正确：业务，指个人每天要做的工作。", "异物": "第一个音节 yì（第四声）与 yè 只差韵母，意思是不该出现的外来物。", "野物": "第一个音节 yě（第三声）与 yè（第四声）只差声调，意思是野生的动物。", "衣物": "第一个音节 yī（第一声）与 yè（第四声）只差声调，意思是衣服等物品。", "遗物": "第一个音节 yí（第二声）与 yè 声调和韵母都不同，意思是死者留下的物品。"}, "sentence_index": null, "correct_answer": "业务"}, "level_3": {"options": [{"text": "业务", "is_correct": true, "explanation": "正确：业务，指今天要处理的工作事务，可以记在本子上。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开门用的工具，不是可以写在本子上的内容。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是出门带的箱包，写在本子上没有意义。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是挡雨的东西，不能写在本子上。"}], "explanations": {"业务": "正确：业务，指今天要处理的工作事务，可以记在本子上。", "钥匙": "语义：钥匙是开门用的工具，不是可以写在本子上的内容。", "行李": "语义：行李是出门带的箱包，写在本子上没有意义。", "雨伞": "语义：雨伞是挡雨的东西，不能写在本子上。"}, "sentence_index": 6, "correct_answer": "业务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院开了一杯业务。", "explanation": "这里应该用〈项〉。“杯”用于盛装的饮料，业务要用“项”来数。"}, {"text": "医院有五十名业务。", "explanation": "这里应该用〈员工〉。“名”可以数人，但业务指事务，不能用来数人。"}, {"text": "他每天最喜欢的业务是喝茶。", "explanation": "这里应该用〈爱好〉。“业务”指个人每天要做的工作，不指闲暇时喜欢做的事，喝茶属于爱好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天有几只业务要处理。", "corrected_sentence": "我今天有几项业务要处理。", "error_description": "“业务”的量词应用“项”，不用“只”。“只”多用于动物或单个物件，应改为“几项业务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天有三本业务要处理。", "corrected_sentence": "他今天有三项业务要处理。", "error_description": "“业务”的量词应用“项”，不用“本”。“本”用于书、本子，应改为“三项业务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
