INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87901, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "称作是给一个东西起名字，大家都这样叫。", "primary_collocate": null, "pronunciation": "chēng zuò", "ipa": "tʂʰɤŋ˥ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "人们把这种红色的水果称作苹果。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把我家的小狗称作“大白”。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们那儿的人把这种车称作“小三轮”。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把雪人称作“小白”。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，过年时吃的饺子，有人称作“元宝”。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把学习好的同学称作“小博士”。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新买的自行车称作“飞飞”。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把我的小猫称作“小懒虫”，因为它爱睡觉。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们把教室称作“第二个家”。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都把他称作“活地图”，因为他什么路都知道。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "称作了", "label": "体标"}, {"form": "称作过", "label": "体标"}], "register": "中性", "sense_fingerprint": "给人或东西起名字、起外号，大家都这样叫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '572e04e2-6b86-4c93-ad0e-9ef951c337f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87901, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称作", "is_correct": true, "explanation": "正确：“把……称作……”表示给这种水果起名字，称它为苹果。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”需要一个接受的人，苹果不能作为接受者。"}, {"text": "切成", "is_correct": false, "explanation": "搭配：“切成”后接的是块、片等形状，不能接一种水果的名字。"}, {"text": "卖给", "is_correct": false, "explanation": "配价：“卖给”需要买的人，苹果不能作为买主。"}], "explanations": {"称作": "正确：“把……称作……”表示给这种水果起名字，称它为苹果。", "送给": "配价：“送给”需要一个接受的人，苹果不能作为接受者。", "切成": "搭配：“切成”后接的是块、片等形状，不能接一种水果的名字。", "卖给": "配价：“卖给”需要买的人，苹果不能作为买主。"}, "sentence_index": 0, "correct_answer": "称作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把这次失败称作很宝贵。", "explanation": "这里应该用〈认为〉。称作用于给人或事物起名字，后面接名词，不能直接接“很宝贵”这样的形容词；说这次失败很宝贵，要用认为。"}, {"text": "他把这场比赛称作很精彩。", "explanation": "这里应该用〈觉得〉。称作后面接的是名称，不能直接接形容词；说比赛很精彩，要用觉得。"}, {"text": "老板把这袋苹果称作两斤。", "explanation": "这里应该用〈称〉。称作表示起名字，用秤量重量要说称，称作两斤说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称作", "is_correct": true, "explanation": "正确：这里要给自行车起名字，叫它“飞飞”，用“称作”。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是物体表面，不能用来给东西起名字。"}, {"text": "骑", "is_correct": false, "explanation": "语义：“骑”表示乘坐，不表示给车起名字，与句意不符。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”表示修理，不表示起名字，与句意不符。"}], "explanations": {"称作": "正确：这里要给自行车起名字，叫它“飞飞”，用“称作”。", "擦": "搭配：“擦”的对象是物体表面，不能用来给东西起名字。", "骑": "语义：“骑”表示乘坐，不表示给车起名字，与句意不符。", "修": "语义：“修”表示修理，不表示起名字，与句意不符。"}, "sentence_index": 6, "correct_answer": "称作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们都把他称作很好。", "explanation": "这里应该用〈觉得〉。称作要给人或事物起名字，不能直接接形容词；说他很好，要用觉得。"}, {"text": "他把这件衣服称作很便宜。", "explanation": "这里应该用〈说〉。称作后面接名称，不能接形容词；要表达衣服便宜，应说“他说这件衣服很便宜”。"}, {"text": "他把这块肉称作三斤。", "explanation": "这里应该用〈称〉。称作表示起名字，用秤量重量要说称，称作三斤说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人们把这种黄色的瓜称作在南瓜。", "corrected_sentence": "人们把这种黄色的瓜称作南瓜。", "error_description": "错误：“称作”后面直接接所称的名称，中间不能插入“在”。应说“人们把这种黄色的瓜称作南瓜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把那只灰色的猫称作在“小灰”。", "corrected_sentence": "我们把那只灰色的猫称作“小灰”。", "error_description": "错误：“称作”后面直接接所称的名称，中间不能插入“在”。应说：我们把那只灰色的猫称作“小灰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
