INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87902, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叫做；称为。", "primary_collocate": null, "pronunciation": "chēng zuò", "ipa": "tʂʰɤŋ˥ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "我们把水变成气的过程称作蒸发。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们把一年中最冷的那段时间称作“寒冬”。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把这种病称作感冒。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人把一年的开始称作“春节”。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绕着太阳转的八个大星球称作行星。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们公司，经理的助手称作“秘书”。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山以后到第二天早上，这段时间称作夜晚。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们把用来写毛笔字的黑色液体称作墨汁。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，没有水的大片土地称作沙漠。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在法律上，十八岁以下的人称作未成年人。", "target_word": "称作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "称作了", "label": "体标"}, {"form": "称作过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用名称来说明某类事物或现象，相当于叫做、称为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '572e04e2-6b86-4c93-ad0e-9ef951c337f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称作", "is_correct": true, "explanation": "正确：这里用来给“水变成气的过程”下定义，说它叫“蒸发”，用“称作”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体或饮品，不能喝一个过程。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”需要接受的人，过程不能作为接受者。"}, {"text": "打破", "is_correct": false, "explanation": "语义：“打破”表示破坏，与句中给过程下定义的意思不符。"}], "explanations": {"称作": "正确：这里用来给“水变成气的过程”下定义，说它叫“蒸发”，用“称作”。", "喝": "搭配：“喝”的对象是液体或饮品，不能喝一个过程。", "送给": "配价：“送给”需要接受的人，过程不能作为接受者。", "打破": "语义：“打破”表示破坏，与句中给过程下定义的意思不符。"}, "sentence_index": 0, "correct_answer": "称作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这件事称作很简单。", "explanation": "这里应该用〈说〉。称作用于给事物起名字或归类，后面接名称，不接形容词；要表达事情简单，应说“他说这件事很简单”。"}, {"text": "妈妈把这块布称作两米。", "explanation": "这里应该用〈量〉。量布的长度要说量，称作表示起名字，不能用来表示长度。"}, {"text": "我们把这个问题称作很难。", "explanation": "这里应该用〈认为〉。称作后面接名称或类别，不接形容词；说这个问题很难，要用认为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称作", "is_correct": true, "explanation": "正确：这里用来给一段时间下定义，说它叫“夜晚”，用“称作”。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的对象是食物，不能吃掉一段时间。"}, {"text": "摘下", "is_correct": false, "explanation": "搭配：“摘下”的对象是具体的东西，不能摘下一段时间。"}, {"text": "关上", "is_correct": false, "explanation": "语义：“关上”表示关闭门窗之类，与给时间下定义的意思不符。"}], "explanations": {"称作": "正确：这里用来给一段时间下定义，说它叫“夜晚”，用“称作”。", "吃掉": "搭配：“吃掉”的对象是食物，不能吃掉一段时间。", "摘下": "搭配：“摘下”的对象是具体的东西，不能摘下一段时间。", "关上": "语义：“关上”表示关闭门窗之类，与给时间下定义的意思不符。"}, "sentence_index": 6, "correct_answer": "称作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶把我称作很乖。", "explanation": "这里应该用〈夸〉。称作用于起名字或归类，不接形容词；夸一个人乖，要用夸。"}, {"text": "他把这袋米称作十斤。", "explanation": "这里应该用〈称〉。称作表示起名字，用秤量重量要说称，称作十斤说不通。"}, {"text": "我们把这件事称作很大。", "explanation": "这里应该用〈觉得〉。称作后面接名称，不能直接接形容词；说这件事很大，要用觉得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人们把这种无色的气体称作在氧气。", "corrected_sentence": "人们把这种无色的气体称作氧气。", "error_description": "错误：“称作”后面直接接所称的名称，中间不能插入“在”。应说“人们把这种无色的气体称作氧气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人们把这种能发光的小虫称作在萤火虫。", "corrected_sentence": "人们把这种能发光的小虫称作萤火虫。", "error_description": "错误：“称作”后面直接接所称的名称，中间不能插入“在”。应说“人们把这种能发光的小虫称作萤火虫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
