INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87903, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87903, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "袭击是突然跑去打别人，别人没有想到。", "primary_collocate": null, "pronunciation": "xí jī", "ipa": "ɕi˧˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "昨天晚上有人袭击了我的朋友。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大狗突然袭击了那个小孩。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几个人躲在墙后袭击路过的学生。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公园里袭击过老人。", "target_word": "袭击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂袭击了树下休息的人们。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏人跑过来袭击他，他没有看见。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察抓到了袭击老人的小偷。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人知道是谁在夜里袭击了那个司机。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只鸟突然飞下来袭击我的头。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们商量好了，明天去袭击对方。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "袭击了", "label": "体标"}, {"form": "袭击过", "label": "体标"}, {"form": "袭击者", "label": "复合"}], "register": "书面", "sense_fingerprint": "突然冲过去打人，对方事先毫无准备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe9756ff-4b06-4a9a-9345-22a235fc21d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87903, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能是“我的朋友”。"}, {"text": "袭击", "is_correct": true, "explanation": "袭击：突然攻击，与“昨天晚上”的语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的宾语应是歌曲，不能说唱“朋友”。"}, {"text": "供养", "is_correct": false, "explanation": "语义：“供养”指长期提供生活所需，与“昨天晚上”这样的短时间不合。"}], "explanations": {"吃": "配价：“吃”的宾语应是食物，不能是“我的朋友”。", "袭击": "袭击：突然攻击，与“昨天晚上”的语境相合。", "唱": "配价：“唱”的宾语应是歌曲，不能说唱“朋友”。", "供养": "语义：“供养”指长期提供生活所需，与“昨天晚上”这样的短时间不合。"}, "sentence_index": 0, "correct_answer": "袭击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在医院袭击生病的爷爷，还给他喂饭。", "explanation": "这里应该用〈照顾〉。袭击是突然施加暴力，与每天喂饭的照料之意矛盾；照料病人要用照顾。"}, {"text": "老师袭击了迟到的学生，委婉地提醒他以后要守时。", "explanation": "这里应该用〈批评〉。袭击是突然施加暴力，与“委婉提醒”的态度矛盾；指出学生的错误要用批评。"}, {"text": "我去车站袭击了远方的朋友，还帮他提了行李。", "explanation": "这里应该用〈接〉。袭击是攻击，与帮他提行李的迎接之意矛盾；到车站迎接远方的朋友要用接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接待", "is_correct": false, "explanation": "语义：“接待”是以礼相待，与“抓到”“小偷”的语境不合。"}, {"text": "袭击", "is_correct": true, "explanation": "袭击：突然攻击，与“抓到”的对象“小偷”的行为相合。"}, {"text": "款待", "is_correct": false, "explanation": "语域：“款待”是郑重的待客用语，与警察抓捕小偷的语境不合。"}, {"text": "慰问", "is_correct": false, "explanation": "语域：“慰问”是书面的问候用语，与“抓到小偷”的语境不合。"}], "explanations": {"接待": "语义：“接待”是以礼相待，与“抓到”“小偷”的语境不合。", "袭击": "袭击：突然攻击，与“抓到”的对象“小偷”的行为相合。", "款待": "语域：“款待”是郑重的待客用语，与警察抓捕小偷的语境不合。", "慰问": "语域：“慰问”是书面的问候用语，与“抓到小偷”的语境不合。"}, "sentence_index": 6, "correct_answer": "袭击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们去医院袭击受伤的同事，还带去了水果和鲜花。", "explanation": "这里应该用〈慰问〉。袭击是突然攻击，与带去水果和鲜花的关怀之意矛盾；去医院看望受伤的同事要用慰问。"}, {"text": "他在街上袭击了多年不见的老朋友，还问他最近过得好不好。", "explanation": "这里应该用〈问候〉。袭击是突然攻击，与问候对方近况的温和之意矛盾；久别重逢时的寒暄要用问候。"}, {"text": "他袭击奶奶去公园散步，一路上小心地扶着她。", "explanation": "这里应该用〈陪〉。袭击是突然攻击，与一路小心扶着她的陪伴之意矛盾；陪奶奶散步要用陪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨晚有人很袭击了那个老人。", "corrected_sentence": "昨晚有人突然袭击了那个老人。", "error_description": "“很”不能修饰动词“袭击”，应改为表示袭击方式的“突然”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有人在路上袭击了过一个孩子。", "corrected_sentence": "有人在路上袭击过一个孩子。", "error_description": "“袭击”后面不能同时带“了”和“过”，表示曾经发生过只用“袭击过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
