INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87904, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出其不意地攻击。", "primary_collocate": null, "pronunciation": "xí jī", "ipa": "ɕi˧˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "小偷夜里袭击了一个路人。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人半夜突然袭击了我们的营地。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一只狼袭击了山下的羊群。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在路上袭击过一辆运钱的车。", "target_word": "袭击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑夜里，有人袭击了那个警察。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军队准备在天亮前袭击对方。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老虎突然从树后袭击小鹿。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那些坏人想袭击银行的保安。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没想到有人会在门口袭击他。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小队悄悄走近，想袭击守门的人。", "target_word": "袭击", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "袭击了", "label": "体标"}, {"form": "袭击过", "label": "体标"}, {"form": "袭击者", "label": "复合"}], "register": "书面", "sense_fingerprint": "趁对方没有防备，突然发动攻击", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe9756ff-4b06-4a9a-9345-22a235fc21d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偷", "is_correct": false, "explanation": "配价：“偷”的宾语应是财物，不能直接是“一个路人”。"}, {"text": "袭击", "is_correct": true, "explanation": "袭击：突然发动攻击，与“小偷夜里”的语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是演唱，与“小偷夜里”的作案情境不合，且“唱”的宾语不能是路人。"}, {"text": "拜访", "is_correct": false, "explanation": "语域：“拜访”是礼貌的登门看望，与深夜作案的小偷不合。"}], "explanations": {"偷": "配价：“偷”的宾语应是财物，不能直接是“一个路人”。", "袭击": "袭击：突然发动攻击，与“小偷夜里”的语境相合。", "唱": "语义：“唱”是演唱，与“小偷夜里”的作案情境不合，且“唱”的宾语不能是路人。", "拜访": "语域：“拜访”是礼貌的登门看望，与深夜作案的小偷不合。"}, "sentence_index": 0, "correct_answer": "袭击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在辩论中袭击了对方的观点。", "explanation": "这里应该用〈攻击〉。袭击指突然发动武力冲击，辩论中驳斥观点要用攻击。"}, {"text": "他去医院袭击生病的朋友，还给他带了水果。", "explanation": "这里应该用〈探望〉。袭击是突然施加暴力，与后面“带了水果”的看望之意矛盾；看望病人要用探望。"}, {"text": "我们在会议上袭击了那个方案。", "explanation": "这里应该用〈反对〉。袭击是出其不意的武力行为，对方案表示不同意要用反对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "款待", "is_correct": false, "explanation": "语域：“款待”是郑重的待客用语，与老虎埋伏、突然扑出的情境不合。"}, {"text": "袭击", "is_correct": true, "explanation": "袭击：突然攻击，与“突然从树后”的埋伏情境相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护卫，老虎是捕食者，与句中的动作正好相反。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”是欢迎，与“突然从树后”的出其不意不合。"}], "explanations": {"款待": "语域：“款待”是郑重的待客用语，与老虎埋伏、突然扑出的情境不合。", "袭击": "袭击：突然攻击，与“突然从树后”的埋伏情境相合。", "保护": "语义：“保护”是护卫，老虎是捕食者，与句中的动作正好相反。", "迎接": "语义：“迎接”是欢迎，与“突然从树后”的出其不意不合。"}, "sentence_index": 6, "correct_answer": "袭击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大使馆在门口袭击了来访的客人，还为他们安排了住处。", "explanation": "这里应该用〈接待〉。袭击是突然施加暴力，与为客人安排住处的迎接之意矛盾；迎接来访客人要用接待。"}, {"text": "消防员袭击了被困的居民，把他们一个个救了出来。", "explanation": "这里应该用〈救助〉。袭击是攻击伤害，与“救了出来”的营救之意矛盾；救助被困的人要用救助。"}, {"text": "他轻轻袭击了熟睡的妈妈。", "explanation": "这里应该用〈叫醒〉。袭击是突然攻击，与轻轻唤醒的动作完全相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "敌人昨晚很袭击了我们的哨所。", "corrected_sentence": "敌人昨晚突然袭击了我们的哨所。", "error_description": "“很”是程度副词，不能修饰动词“袭击”。这里应改为表示方式的“突然”，即“突然袭击”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那伙人昨天夜里袭击了过一位老人。", "corrected_sentence": "那伙人昨天夜里袭击过一位老人。", "error_description": "“了”和“过”不能同时用在“袭击”后面，表示曾经发生的经历只用“袭击过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
