INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87905, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "武器是打仗时用来保护自己或打别人的东西。", "primary_collocate": null, "pronunciation": "wǔ qì", "ipa": "u˨˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "士兵手里拿着武器。", "target_word": "武器", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "打仗的时候，每个人都需要武器。", "target_word": "武器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们没有武器，只好跑回家。", "target_word": "武器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战士用武器保护自己的国家。", "target_word": "武器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家买了很多新武器。", "target_word": "武器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察发现他身上带着武器。", "target_word": "武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的人用石头做武器。", "target_word": "武器", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "敌人的武器比我们的好。", "target_word": "武器", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "士兵把武器放在桌子上，开始吃饭。", "target_word": "武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，他们交出了所有武器。", "target_word": "武器", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件武器", "label": "量词"}, {"form": "一种武器", "label": "量词"}, {"form": "核武器", "label": "复合词"}, {"form": "武器库", "label": "复合词"}], "register": "中性", "sense_fingerprint": "打仗时士兵用来保护自己、攻击别人的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae51d7e-db40-49f3-b67b-d653c6a88f9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "武器", "is_correct": true, "explanation": "本词：指打仗时用来攻击或防卫的东西。"}, {"text": "雾气", "is_correct": false, "explanation": "wù（第四声）与 wǔ（第三声）声调不同，意思是雾气，不是武器。"}, {"text": "舞技", "is_correct": false, "explanation": "qì 与 jì 声母不同（q / j），意思是舞蹈的技艺。"}, {"text": "武技", "is_correct": false, "explanation": "qì 与 jì 声母不同（q / j），意思是武术技艺。"}], "explanations": {"武器": "本词：指打仗时用来攻击或防卫的东西。", "雾气": "wù（第四声）与 wǔ（第三声）声调不同，意思是雾气，不是武器。", "舞技": "qì 与 jì 声母不同（q / j），意思是舞蹈的技艺。", "武技": "qì 与 jì 声母不同（q / j），意思是武术技艺。"}, "sentence_index": null, "correct_answer": "武器"}, "level_3": {"options": [{"text": "武器", "is_correct": true, "explanation": "正确：武器是士兵手里拿着的器械，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子体积太大，不能用手拿着。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「拿着」不搭配天气，天气不能握在手里。"}, {"text": "大海", "is_correct": false, "explanation": "配价：「拿着」要求可握持的具体物件，大海不能被拿着。"}], "explanations": {"武器": "正确：武器是士兵手里拿着的器械，符合句意。", "房子": "语义：房子体积太大，不能用手拿着。", "天气": "搭配：「拿着」不搭配天气，天气不能握在手里。", "大海": "配价：「拿着」要求可握持的具体物件，大海不能被拿着。"}, "sentence_index": 0, "correct_answer": "武器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸用这件武器修好了自行车。", "explanation": "这里应该用〈工具〉。修理自行车用的是工具，武器是用于攻击或防卫的器械。"}, {"text": "他用这件武器吃了一顿饭。", "explanation": "这里应该用〈餐具〉。吃饭用的是餐具，武器不能用来吃饭。"}, {"text": "他用这件武器写作业。", "explanation": "这里应该用〈文具〉。写作业用的是文具，武器不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87905, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "武器", "is_correct": true, "explanation": "本词：指打仗时用来攻击或防卫的东西。"}, {"text": "武戏", "is_correct": false, "explanation": "qì 与 xì 声母不同（q / x），意思是武打戏。"}, {"text": "误期", "is_correct": false, "explanation": "wǔ 与 wù、qì 与 qī 声调不同，意思是耽误期限。"}, {"text": "雨期", "is_correct": false, "explanation": "wǔ 与 yǔ 声母不同（w / y），意思是雨季。"}], "explanations": {"武器": "本词：指打仗时用来攻击或防卫的东西。", "武戏": "qì 与 xì 声母不同（q / x），意思是武打戏。", "误期": "wǔ 与 wù、qì 与 qī 声调不同，意思是耽误期限。", "雨期": "wǔ 与 yǔ 声母不同（w / y），意思是雨季。"}, "sentence_index": null, "correct_answer": "武器"}, "level_3": {"options": [{"text": "武器", "is_correct": true, "explanation": "正确：古代的人用石头做的是武器，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：古代没有手机，不能用石头做手机。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：「做」不搭配名字，应说「取名字」。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，不能用石头做成。"}], "explanations": {"武器": "正确：古代的人用石头做的是武器，符合句意。", "手机": "语义：古代没有手机，不能用石头做手机。", "名字": "搭配：「做」不搭配名字，应说「取名字」。", "空气": "语义：空气看不见摸不着，不能用石头做成。"}, "sentence_index": 6, "correct_answer": "武器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都要喝武器。", "explanation": "这里应该用〈饮料〉。喝的是饮料，武器不能用来喝。"}, {"text": "老师正在批改这件武器。", "explanation": "这里应该用〈试卷〉。批改的是试卷，武器不能批改。"}, {"text": "这个孩子经常用武器画画。", "explanation": "这里应该用〈画笔〉。画画用的是画笔，武器不能用来画画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
