INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "武器", "is_correct": true, "explanation": "本词：指用于攻击或防卫的器械。"}, {"text": "雾气", "is_correct": false, "explanation": "wù（第四声）与 wǔ（第三声）声调不同，意思是雾气，不是武器。"}, {"text": "舞技", "is_correct": false, "explanation": "qì 与 jì 声母不同（q / j），意思是舞蹈的技艺。"}, {"text": "武技", "is_correct": false, "explanation": "qì 与 jì 声母不同（q / j），意思是武术技艺。"}], "explanations": {"武器": "本词：指用于攻击或防卫的器械。", "雾气": "wù（第四声）与 wǔ（第三声）声调不同，意思是雾气，不是武器。", "舞技": "qì 与 jì 声母不同（q / j），意思是舞蹈的技艺。", "武技": "qì 与 jì 声母不同（q / j），意思是武术技艺。"}, "sentence_index": null, "correct_answer": "武器"}, "level_3": {"options": [{"text": "武器", "is_correct": true, "explanation": "正确：枪、炮和刀都属于用于攻击或防卫的器械，符合句意。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：枪、炮和刀不是乐器。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：枪、炮和刀不能喝，不是饮料。"}, {"text": "水果", "is_correct": false, "explanation": "配价：「是」后的类属名词要与主语同类，水果与枪、炮、刀不属于同类。"}], "explanations": {"武器": "正确：枪、炮和刀都属于用于攻击或防卫的器械，符合句意。", "乐器": "语义：枪、炮和刀不是乐器。", "饮料": "语义：枪、炮和刀不能喝，不是饮料。", "水果": "配价：「是」后的类属名词要与主语同类，水果与枪、炮、刀不属于同类。"}, "sentence_index": 0, "correct_answer": "武器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们用这件武器搭积木。", "explanation": "这里应该用〈玩具〉。搭积木用的是玩具，武器是用于攻击或防卫的器械。"}, {"text": "他用这件武器弹了一首曲子。", "explanation": "这里应该用〈乐器〉。弹曲子用的是乐器，武器不能用来演奏。"}, {"text": "妈妈用这件武器炒了一盘菜。", "explanation": "这里应该用〈厨具〉。炒菜用的是厨具，武器不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCL