INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87907, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "算出是动脑筋算一算，得到一个答案。", "primary_collocate": null, "pronunciation": "suàn chū", "ipa": "swan˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "爸爸算出了我们一家的开支。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们动脑筋算出了正确的数字。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在心里算出了大概的价钱。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈算出买这些菜要多少钱。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了一会儿，就算出了结果。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先算出总数，再除以五。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们算出了从北京到上海要几个小时。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她认真地算出了每天的花费。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔账他花了一小时才算出来。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们算出了谁的苹果最多。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "算出了", "label": "体标（了）"}, {"form": "算出来", "label": "趋向补语形式"}], "register": "中性", "sense_fingerprint": "动脑筋算一算得到答案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d2912c-6f4e-4394-8528-f3a78e8b990c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = 