INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87909, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "首是用来数歌和诗的量词，“一首”就是一支歌或一首诗。", "primary_collocate": null, "pronunciation": "shǒu", "ipa": "ʂoʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我会唱一首中文歌。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们读一首诗。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写了一首短诗。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌很好听。", "target_word": "首", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你再给我们唱一首吧。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给妈妈弹了一首钢琴曲。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首诗是李白写的。", "target_word": "首", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我最喜欢这首歌。", "target_word": "首", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他念了两首古诗。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在学一首新歌。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数歌和诗的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14cca9b8-8933-4231-8bfa-84367bc59d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87909, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "首", "is_correct": true, "explanation": "正确。首（shǒu，第三声）是量词，用于诗和歌曲。"}, {"text": "收", "is_correct": false, "explanation": "收（shōu，第一声）与首（shǒu，第三声）声调不同，意思是收取、收拾，不是量词。"}, {"text": "寿", "is_correct": false, "explanation": "寿（shòu，第四声）与首（shǒu，第三声）声调不同，意思是寿命。"}, {"text": "受", "is_correct": false, "explanation": "受（shòu，第四声）与首（shǒu，第三声）声调不同，意思是接受、遭受。"}, {"text": "瘦", "is_correct": false, "explanation": "瘦（shòu，第四声）与首（shǒu，第三声）声调不同，意思是身体少肉。"}], "explanations": {"首": "正确。首（shǒu，第三声）是量词，用于诗和歌曲。", "收": "收（shōu，第一声）与首（shǒu，第三声）声调不同，意思是收取、收拾，不是量词。", "寿": "寿（shòu，第四声）与首（shǒu，第三声）声调不同，意思是寿命。", "受": "受（shòu，第四声）与首（shǒu，第三声）声调不同，意思是接受、遭受。", "瘦": "瘦（shòu，第四声）与首（shǒu，第三声）声调不同，意思是身体少肉。"}, "sentence_index": null, "correct_answer": "首"}, "level_3": {"options": [{"text": "首", "is_correct": true, "explanation": "正确。“首”是量词，用于诗和歌，“一首中文歌”搭配自然。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能用来数“歌”。"}, {"text": "篇", "is_correct": false, "explanation": "语义：“篇”指文章、小说等文字作品，歌曲不属于这类。"}, {"text": "座", "is_correct": false, "explanation": "体貌：“座”用于山、桥等大型固定的东西，歌曲不是这种事物。"}], "explanations": {"首": "正确。“首”是量词，用于诗和歌，“一首中文歌”搭配自然。", "本": "搭配：“本”用于书册，不能用来数“歌”。", "篇": "语义：“篇”指文章、小说等文字作品，歌曲不属于这类。", "座": "体貌：“座”用于山、桥等大型固定的东西，歌曲不是这种事物。"}, "sentence_index": 0, "correct_answer": "首"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写了一首文章。", "explanation": "这里应该用〈篇〉。首用于诗词、歌曲，文章要用“篇”。"}, {"text": "我昨天看了一首电影。", "explanation": "这里应该用〈部〉。首用于诗词、歌曲，电影要用“部”。"}, {"text": "我买了一首书。", "explanation": "这里应该用〈本〉。首只用于诗词、歌曲，书要用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87909, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "首", "is_correct": true, "explanation": "正确。首（shǒu，第三声）是量词，用于诗和歌曲。"}, {"text": "售", "is_correct": false, "explanation": "售（shòu，第四声）与首（shǒu，第三声）声调不同，意思是卖出。"}, {"text": "兽", "is_correct": false, "explanation": "兽（shòu，第四声）与首（shǒu，第三声）声调不同，意思是野兽。"}, {"text": "授", "is_correct": false, "explanation": "授（shòu，第四声）与首（shǒu，第三声）声调不同，意思是传授、授予。"}], "explanations": {"首": "正确。首（shǒu，第三声）是量词，用于诗和歌曲。", "售": "售（shòu，第四声）与首（shǒu，第三声）声调不同，意思是卖出。", "兽": "兽（shòu，第四声）与首（shǒu，第三声）声调不同，意思是野兽。", "授": "授（shòu，第四声）与首（shǒu，第三声）声调不同，意思是传授、授予。"}, "sentence_index": null, "correct_answer": "首"}, "level_3": {"options": [{"text": "首", "is_correct": true, "explanation": "正确。“首”用于诗，“这首诗”指李白所写的那一首。"}, {"text": "棵", "is_correct": false, "explanation": "语义：“棵”用于植物，诗不是植物。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车，不能用来数“诗”。"}, {"text": "扇", "is_correct": false, "explanation": "体貌：“扇”指门窗之类的平面物件，诗不具这种形态。"}], "explanations": {"首": "正确。“首”用于诗，“这首诗”指李白所写的那一首。", "棵": "语义：“棵”用于植物，诗不是植物。", "辆": "搭配：“辆”用于车，不能用来数“诗”。", "扇": "体貌：“扇”指门窗之类的平面物件，诗不具这种形态。"}, "sentence_index": 6, "correct_answer": "首"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首画很漂亮。", "explanation": "这里应该用〈幅〉。首用于诗词、歌曲，画要用“幅”。"}, {"text": "我洗了两首照片。", "explanation": "这里应该用〈张〉。首用于诗词、歌曲，照片要用“张”。"}, {"text": "我吃了一首面包。", "explanation": "这里应该用〈块〉。首只用于诗词、歌曲，面包要用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈教我唱了一首的童谣。", "corrected_sentence": "妈妈教我唱了一首童谣。", "error_description": "“一首”后不能直接加“的”。应说“妈妈教我唱了一首童谣”，去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都听一个首英文歌。", "corrected_sentence": "他每天都听一首英文歌。", "error_description": "量词重复：“英文歌”前只能用量词“首”，不能再加“个”。应说“他每天都听一首英文歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
