INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87910, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于诗词、歌曲等。", "primary_collocate": null, "pronunciation": "shǒu", "ipa": "ʂoʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他每天听三首歌。", "target_word": "首", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位诗人写过很多首诗。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首词写的是秋天。", "target_word": "首", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想给你唱一首生日歌。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为爱人写了一首诗。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐会上有五首歌，我都喜欢。", "target_word": "首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子很慢，让人想睡觉。", "target_word": "首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用吉他弹了一首老歌。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课本里有一首关于春天的诗。", "target_word": "首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会背几首唐诗？", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用于诗词、歌曲等的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14cca9b8-8933-4231-8bfa-84367bc59d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87910, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "首", "is_correct": true, "explanation": "正确。首（shǒu，第三声）是量词，用于诗词和歌曲。"}, {"text": "寿", "is_correct": false, "explanation": "寿（shòu，第四声）与首（shǒu，第三声）声调不同，意思是寿命。"}, {"text": "瘦", "is_correct": false, "explanation": "瘦（shòu，第四声）与首（shǒu，第三声）声调不同，意思是身体少肉。"}, {"text": "受", "is_correct": false, "explanation": "受（shòu，第四声）与首（shǒu，第三声）声调不同，意思是接受、遭受。"}], "explanations": {"首": "正确。首（shǒu，第三声）是量词，用于诗词和歌曲。", "寿": "寿（shòu，第四声）与首（shǒu，第三声）声调不同，意思是寿命。", "瘦": "瘦（shòu，第四声）与首（shǒu，第三声）声调不同，意思是身体少肉。", "受": "受（shòu，第四声）与首（shǒu，第三声）声调不同，意思是接受、遭受。"}, "sentence_index": null, "correct_answer": "首"}, "level_3": {"options": [{"text": "首", "is_correct": true, "explanation": "正确。“首”是量词，用于歌曲，“听三首歌”搭配自然。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车，不能用来数“歌”。"}, {"text": "条", "is_correct": false, "explanation": "体貌：“条”用于细长的东西，歌曲不是这种形态。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、桥等大型固定物，不能数歌曲。"}], "explanations": {"首": "正确。“首”是量词，用于歌曲，“听三首歌”搭配自然。", "辆": "搭配：“辆”用于车，不能用来数“歌”。", "条": "体貌：“条”用于细长的东西，歌曲不是这种形态。", "座": "语义：“座”指山、桥等大型固定物，不能数歌曲。"}, "sentence_index": 0, "correct_answer": "首"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写了一首日记。", "explanation": "这里应该用〈篇〉。首用于诗词、歌曲，日记要用“篇”。"}, {"text": "我看了一首比赛。", "explanation": "这里应该用〈场〉。首用于诗词、歌曲，比赛要用“场”。"}, {"text": "我买了一首手机。", "explanation": "这里应该用〈部〉。首只用于诗词、歌曲，手机要用“部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87910, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "首", "is_correct": true, "explanation": "正确。首（shǒu，第三声）是量词，用于诗词和歌曲。"}, {"text": "收", "is_correct": false, "explanation": "收（shōu，第一声）与首（shǒu，第三声）声调不同，意思是收取、收拾。"}, {"text": "售", "is_correct": false, "explanation": "售（shòu，第四声）与首（shǒu，第三声）声调不同，意思是卖出。"}, {"text": "兽", "is_correct": false, "explanation": "兽（shòu，第四声）与首（shǒu，第三声）声调不同，意思是野兽。"}], "explanations": {"首": "正确。首（shǒu，第三声）是量词，用于诗词和歌曲。", "收": "收（shōu，第一声）与首（shǒu，第三声）声调不同，意思是收取、收拾。", "售": "售（shòu，第四声）与首（shǒu，第三声）声调不同，意思是卖出。", "兽": "兽（shòu，第四声）与首（shǒu，第三声）声调不同，意思是野兽。"}, "sentence_index": null, "correct_answer": "首"}, "level_3": {"options": [{"text": "首", "is_correct": true, "explanation": "正确。“首”是量词，用于乐曲，“这首曲子”搭配自然。"}, {"text": "棵", "is_correct": false, "explanation": "语义：“棵”用于植物，曲子不是植物。"}, {"text": "扇", "is_correct": false, "explanation": "体貌：“扇”指门窗之类的平面物件，不能用于曲子。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于带柄的器物，不能用来数“曲子”。"}], "explanations": {"首": "正确。“首”是量词，用于乐曲，“这首曲子”搭配自然。", "棵": "语义：“棵”用于植物，曲子不是植物。", "扇": "体貌：“扇”指门窗之类的平面物件，不能用于曲子。", "把": "搭配：“把”用于带柄的器物，不能用来数“曲子”。"}, "sentence_index": 6, "correct_answer": "首"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上挂着一首画。", "explanation": "这里应该用〈幅〉。首用于诗词、歌曲，画要用“幅”。"}, {"text": "我买了一首椅子。", "explanation": "这里应该用〈把〉。首只用于诗词、歌曲，椅子要用“把”。"}, {"text": "这首裙子很漂亮。", "explanation": "这里应该用〈条〉。首用于诗词、歌曲，裙子要用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation