INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈每天给我唱一个首摇篮曲。", "corrected_sentence": "妈妈每天给我唱一首摇篮曲。", "error_description": "量词重复：“摇篮曲”的量词只能用“首”，前面不能再加“个”。应说“妈妈每天给我唱一首摇篮曲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
