INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87911, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "状况是一件事现在的样子。", "primary_collocate": null, "pronunciation": "zhuàng kuàng", "ipa": "ʈʂwɑŋ˥˩ kʰwɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生说病人的状况已经稳定了。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都问我工作的状况。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天的精神状况不太好。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前的住房状况让很多人担心。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说说这个项目的状况吗？", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活状况有了很大的改变。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子们的学习状况，妈妈很高兴。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老桥现在的状况很危险。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他最近的工作状况不错。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子出了状况，我们只好走路回家。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "健康状况", "label": "复合词"}, {"form": "生活状况", "label": "复合词"}, {"form": "狀況", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一件事现在的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d2912c-6f4e-4394-8528-f3a78e8b990c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87911, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "状况", "is_correct": true, "explanation": "正确：“病人的状况”指病人的情况，“已经稳定了”与之相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”说价钱，不能“稳定”在病人身上，句子不通。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“手术”是一种治疗行为，不能说“病人的手术已经稳定了”。"}, {"text": "课程", "is_correct": false, "explanation": "语义：“课程”指教学内容，与病人的情况无关，句子不通。"}], "explanations": {"状况": "正确：“病人的状况”指病人的情况，“已经稳定了”与之相符。", "价格": "语义：“价格”说价钱，不能“稳定”在病人身上，句子不通。", "手术": "搭配：“手术”是一种治疗行为，不能说“病人的手术已经稳定了”。", "课程": "语义：“课程”指教学内容，与病人的情况无关，句子不通。"}, "sentence_index": 0, "correct_answer": "状况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的状况很大，一家人住很宽敞。", "explanation": "这里应该用〈面积〉。“大”说的是大小，“状况”指情况，不能用来描述面积。"}, {"text": "这套公寓的状况很贵，我们买不起。", "explanation": "这里应该用〈价格〉。“贵”说的是价钱，“状况”指情况，不能用来说贵贱。"}, {"text": "这一座状况让很多人担心。", "explanation": "这里应该用〈种〉。“座”用于山、桥、楼房等大型物体，“状况”是抽象的情况，要用“种”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "状况", "is_correct": true, "explanation": "正确：“学习状况”指学习的情况，与“妈妈很高兴”的语境相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”说身体的重量，不能说“学习体重”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”说滋味，与学习无关，句子不通。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“门票”不能与“学习”搭配，句子不通。"}], "explanations": {"状况": "正确：“学习状况”指学习的情况，与“妈妈很高兴”的语境相符。", "体重": "语义：“体重”说身体的重量，不能说“学习体重”。", "味道": "语义：“味道”说滋味，与学习无关，句子不通。", "门票": "搭配：“门票”不能与“学习”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "状况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的状况很快，半小时就到了。", "explanation": "这里应该用〈速度〉。“快”说的是速度，“状况”不能用来形容快慢。"}, {"text": "这幅画的状况很鲜艳，大家都喜欢看。", "explanation": "这里应该用〈颜色〉。“鲜艳”说的是颜色，“状况”不能用来形容颜色。"}, {"text": "这一把状况让我们很头疼。", "explanation": "这里应该用〈种〉。“把”用于有柄的器具，“状况”是抽象的情况，不能用“把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病人的很状况很稳定。", "corrected_sentence": "病人的状况很稳定。", "error_description": "错误：“状况”前多加了“很”。“很”是程度副词，只能修饰形容词，不能修饰名词“状况”；程度修饰应只用于“稳定”，正确是“病人的状况很稳定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电梯的状况变好着，大家都放心。", "corrected_sentence": "电梯的状况变好了，大家都放心。", "error_description": "错误：“变好”后用了“着”。“着”表示状态持续，表示变化已经完成要用“了”。正确是“变好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
