INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87912, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "情况；事物表现出来的形态。", "primary_collocate": null, "pronunciation": "zhuàng kuàng", "ipa": "ʈʂwɑŋ˥˩ kʰwɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生问了问奶奶最近的身体状况。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的经济状况一直不太好。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的健康状况比去年好多了。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气状况不好，飞机不能起飞。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想了解学生的学习状况。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把现在的状况告诉经理。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上出了状况，我们可能会晚到。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑的使用状况很好，像新的一样。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在检查桥的安全状况。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的政治状况很不稳定。", "target_word": "状况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "身体状况", "label": "复合词"}, {"form": "经济状况", "label": "复合词"}, {"form": "狀況", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物表现出来的情况和形态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d2912c-6f4e-4394-8528-f3a78e8b990c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "状况", "is_correct": true, "explanation": "正确：“身体状况”指身体的情况，与“最近的”搭配自然。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”指心理状态，问的是身体，不能用“身体心情”。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“门票”不能与“身体”搭配，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外表的色彩，不是身体的情况，句子不通。"}], "explanations": {"状况": "正确：“身体状况”指身体的情况，与“最近的”搭配自然。", "心情": "语义：“心情”指心理状态，问的是身体，不能用“身体心情”。", "门票": "搭配：“门票”不能与“身体”搭配，句子不通。", "颜色": "语义：“颜色”指外表的色彩，不是身体的情况，句子不通。"}, "sentence_index": 0, "correct_answer": "状况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个花瓶的状况很漂亮，客人都很喜欢。", "explanation": "这里应该用〈形状〉。“漂亮”说外形好看，“状况”指情况、样子的好坏，不能用来描述器物的形状。"}, {"text": "这只小狗的状况很可爱，大家都想摸一摸。", "explanation": "这里应该用〈样子〉。“可爱”说模样，“状况”指情况和状态，不能用来形容外貌。"}, {"text": "面对这本状况，我们没有办法。", "explanation": "这里应该用〈种〉。“状况”是抽象的情况，要说“这种状况”；“本”用于书册。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "状况", "is_correct": true, "explanation": "正确：“路上出了状况”指路上出现了情况，与后半句“可能会晚到”呼应。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”说滋味，与路上的情况无关，句子不通。"}, {"text": "价钱", "is_correct": false, "explanation": "搭配：“价钱”不能说“路上出了价钱”。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“门票”不能说“路上出了门票”，句子不通。"}], "explanations": {"状况": "正确：“路上出了状况”指路上出现了情况，与后半句“可能会晚到”呼应。", "味道": "语义：“味道”说滋味，与路上的情况无关，句子不通。", "价钱": "搭配：“价钱”不能说“路上出了价钱”。", "门票": "搭配：“门票”不能说“路上出了门票”，句子不通。"}, "sentence_index": 6, "correct_answer": "状况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的状况很慌张，好像出了什么事。", "explanation": "这里应该用〈神色〉。“慌张”说的是神情，“状况”指情况，不能用来描述人的神色。"}, {"text": "这瓶酒的状况很香，打开就闻到了。", "explanation": "这里应该用〈气味〉。“香”说的是气味，“状况”不能用来形容气味。"}, {"text": "这一台政治状况，他们都无能为力。", "explanation": "这里应该用〈种〉。“台”用于机器，“状况”是抽象的情况，不能用“台”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本状况让大家很担心。", "corrected_sentence": "这种状况让大家很担心。", "error_description": "错误在量词“本”。“状况”是抽象的情况，应该用“种”；“本”用于书册。正确是“这种状况”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车子出过一本状况，修了好几天。", "corrected_sentence": "车子出过一次状况，修了好几天。", "error_description": "错误：量词“本”用错了。“本”用于书册；说“出状况”的次数要用“次”。正确是“出过一次状况”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
