INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87913, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一系列是一件接着一件、连在一起的很多事。", "primary_collocate": null, "pronunciation": "yí xì liè", "ipa": "i˧˥ ɕi˥˩ liɛ˥˩", "syllable_count": 3, "sentences": [{"text": "昨天发生了一系列事故，路上堵了很久。", "target_word": "一系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病后，一系列麻烦接着来了。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前出现了一系列意外。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司搬家后，一系列问题出现了。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一系列变化让他很不习惯。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气变冷以后，一系列事情接着发生。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他丢了钱包，又迟到，真是一系列倒霉事。", "target_word": "一系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一系列好消息让全家人都很高兴。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震后，一系列救援行动马上开始。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他离开家以后，一系列的事情改变了他。", "target_word": "一系列", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一件接着一件发生、连在一起的很多事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14cca9b8-8933-4231-8bfa-84367bc59d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87913, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一系列", "is_correct": true, "explanation": "正确。“一系列”表示一件接着一件、连在一起的很多事，符合“发生了……事故”的语境。"}, {"text": "固定", "is_correct": false, "explanation": "语义：“固定”指不变动，不能修饰“事故”。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”形容好看，不能修饰“事故”。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”指可以看透，和“事故”的意思不相关。"}], "explanations": {"一系列": "正确。“一系列”表示一件接着一件、连在一起的很多事，符合“发生了……事故”的语境。", "固定": "语义：“固定”指不变动，不能修饰“事故”。", "美丽": "搭配：“美丽”形容好看，不能修饰“事故”。", "透明": "语义：“透明”指可以看透，和“事故”的意思不相关。"}, "sentence_index": 0, "correct_answer": "一系列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们买了一系列水果。", "explanation": "这里应该用〈一些〉。“一系列”指一件接着一件、相互关联的很多事，买来的水果之间没有这种关系，应该用“一些”。"}, {"text": "我们班有一系列同学。", "explanation": "这里应该用〈一群〉。“一系列”不用来形容人群，应该用“一群”。"}, {"text": "桌上有一系列花。", "explanation": "这里应该用〈一束〉。“一系列”不用于数一束花，应该用“一束”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一系列", "is_correct": true, "explanation": "正确。“一系列”表示一连串事情，与“倒霉事”的语境相符。"}, {"text": "幸运", "is_correct": false, "explanation": "语义：“幸运”与“倒霉”相反，前后矛盾。"}, {"text": "清亮", "is_correct": false, "explanation": "搭配：“清亮”形容声音或眼睛，不能修饰“事”。"}, {"text": "灵巧", "is_correct": false, "explanation": "搭配：“灵巧”形容手或动作，不能修饰“事”。"}], "explanations": {"一系列": "正确。“一系列”表示一连串事情，与“倒霉事”的语境相符。", "幸运": "语义：“幸运”与“倒霉”相反，前后矛盾。", "清亮": "搭配：“清亮”形容声音或眼睛，不能修饰“事”。", "灵巧": "搭配：“灵巧”形容手或动作，不能修饰“事”。"}, "sentence_index": 6, "correct_answer": "一系列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里有一系列树。", "explanation": "这里应该用〈一排〉。“一系列”强调接连发生或相互关联的事，不用来数一排树，应该用“一排”。"}, {"text": "他是一系列老师。", "explanation": "这里应该用〈一位〉。“一系列”不能用来数一个人，应该用“一位”。"}, {"text": "门口站着一系列人。", "explanation": "这里应该用〈一群〉。“一系列”指接连发生、相互关联的事，不用来形容一群人，应该用“一群”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一年，他经历了的一系列挫折。", "corrected_sentence": "这一年，他经历了一系列挫折。", "error_description": "错误：“的”放在“经历了”和“一系列”之间，多余。正确：“经历了一系列挫折”，“一系列”直接修饰“挫折”，中间不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他遇到一个一系列问题，很辛苦。", "corrected_sentence": "他遇到一系列问题，很辛苦。", "error_description": "“一系列”本身已包含“一”的数量，前面不能再加“一个”。应说“一系列问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
