INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87916, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "宗教或神话中所说的主宰世界、有超凡能力的存在。", "primary_collocate": null, "pronunciation": "shén", "ipa": "ʂən˧˥", "syllable_count": 1, "sentences": [{"text": "古人相信神管着天和地。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人到庙里拜神。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他相信世界上有神。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在古希腊，人们拜很多神。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民向神求雨。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说神创造了世界。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民族只信一个神。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神住在天上，人看不见。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的人不信神，只信科学。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的人把太阳当作神。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位神", "label": "量词"}, {"form": "神仙", "label": "复合"}, {"form": "神话", "label": "复合"}], "register": "通用", "sense_fingerprint": "神：宗教或信仰中主宰世界、有超凡能力的存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70440bbe-270b-40e4-ad01-5390c3128607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "神", "is_correct": true, "explanation": "正确：神，宗教或神话中主宰世界、有超凡能力的存在。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shén 韵母不同（ng 与 n），意思是绳子。"}, {"text": "审", "is_correct": false, "explanation": "shěn（第三声）与 shén 声调不同，意思是审查。"}, {"text": "肾", "is_correct": false, "explanation": "shèn（第四声）与 shén 声调不同，意思是肾脏。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shén 声调不同，意思是深浅。"}, {"text": "慎", "is_correct": false, "explanation": "shèn（第四声）与 shén 声调不同，意思是谨慎。"}], "explanations": {"神": "正确：神，宗教或神话中主宰世界、有超凡能力的存在。", "绳": "shéng（第二声）与 shén 韵母不同（ng 与 n），意思是绳子。", "审": "shěn（第三声）与 shén 声调不同，意思是审查。", "肾": "shèn（第四声）与 shén 声调不同，意思是肾脏。", "深": "shēn（第一声）与 shén 声调不同，意思是深浅。", "慎": "shèn（第四声）与 shén 声调不同，意思是谨慎。"}, "sentence_index": null, "correct_answer": "神"}, "level_3": {"options": [{"text": "神", "is_correct": true, "explanation": "正确：神，宗教或神话中主宰天地的存在。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是教书的人，不能主宰天地。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆是吃饭的地方，与主宰天地无关。"}, {"text": "手机", "is_correct": false, "explanation": "配价：“管着天和地”要求有超凡能力的施事，“手机”不能充当。"}], "explanations": {"神": "正确：神，宗教或神话中主宰天地的存在。", "老师": "语义：老师是教书的人，不能主宰天地。", "饭馆": "语义：饭馆是吃饭的地方，与主宰天地无关。", "手机": "配价：“管着天和地”要求有超凡能力的施事，“手机”不能充当。"}, "sentence_index": 0, "correct_answer": "神"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位神很大，可以坐八个人。", "explanation": "这里应该用〈桌子〉。神指宗教中有超凡能力的存在，不指家具，不能说“可以坐八个人”。"}, {"text": "在古希腊，人们拜很多条神。", "explanation": "这里应该用〈位〉。“条”用于长条形的东西，神要用量词“位”。"}, {"text": "我每天骑神去学校。", "explanation": "这里应该用〈自行车〉。神指宗教中有超凡能力的存在，不能被“骑”；“骑”的对象应是自行车、马等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87916, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "神", "is_correct": true, "explanation": "正确：神，宗教或神话中主宰世界、有超凡能力的存在。"}, {"text": "甚", "is_correct": false, "explanation": "shèn（第四声）与 shén 声调不同，意思是很、非常。"}, {"text": "申", "is_correct": false, "explanation": "shēn（第一声）与 shén 声调不同，意思是申请、陈述。"}, {"text": "婶", "is_correct": false, "explanation": "shěn（第三声）与 shén 声调不同，意思是婶婶。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 shén 声调不同，意思是身体。"}], "explanations": {"神": "正确：神，宗教或神话中主宰世界、有超凡能力的存在。", "甚": "shèn（第四声）与 shén 声调不同，意思是很、非常。", "申": "shēn（第一声）与 shén 声调不同，意思是申请、陈述。", "婶": "shěn（第三声）与 shén 声调不同，意思是婶婶。", "身": "shēn（第一声）与 shén 声调不同，意思是身体。"}, "sentence_index": null, "correct_answer": "神"}, "level_3": {"options": [{"text": "神", "is_correct": true, "explanation": "正确：神，宗教中主宰世界的存在。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的书写用具，不是可以信仰的对象。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是储存食物的电器，不是可以信仰的对象。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“信”一般接人、神灵或主义，不接学科名称。"}], "explanations": {"神": "正确：神，宗教中主宰世界的存在。", "黑板": "语义：黑板是教室里的书写用具，不是可以信仰的对象。", "冰箱": "语义：冰箱是储存食物的电器，不是可以信仰的对象。", "数学": "搭配：“信”一般接人、神灵或主义，不接学科名称。"}, "sentence_index": 6, "correct_answer": "神"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古代人家里供着一台神。", "explanation": "这里应该用〈位〉。“台”用于机器、电器，神要用量词“位”。"}, {"text": "他吃坏了肚子，神一下子就疼了。", "explanation": "这里应该用〈胃〉。神指宗教中有超凡能力的存在，不指身体部位，不能说“神疼”。"}, {"text": "这个神很甜，我吃了三个。", "explanation": "这里应该用〈苹果〉。神指宗教中有超凡能力的存在，不指水果，不能说“很甜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古人相信有一只神掌管天地。", "corrected_sentence": "古人相信有一位神掌管天地。", "error_description": "“神”的量词应用“位”，不用“只”。“只”多用于动物，应改为“一位神”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古代的人都敬一棵神。", "corrected_sentence": "古代的人都敬一位神。", "error_description": "“棵”用于树木，“神”的量词应为“位”，应改为“一位神”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
