INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87917, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87917, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "不比是说两个东西放在一起看，这个并不比那个更好或更大。", "primary_collocate": null, "pronunciation": "bù bǐ", "ipa": "pu˥˩ pi˨˩", "syllable_count": 2, "sentences": [{"text": "这本书不比那本厚。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间不比那个大。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的不比蓝色的好看。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服不比那件便宜。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机不比你的新。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果不比那个甜。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的夏天不比上海热。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车不比那辆快。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的狗不比我家的大。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不比那条路近。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个东西相比，这个并不比那个更好或更大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9987eb-5886-4587-85c6-5e6350eb4adf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不比", "is_correct": true, "explanation": "不比：两者相比，这个并不超过那个。此处说“这本书”并不比“那本”厚。"}, {"text": "怕", "is_correct": false, "explanation": "语义：“怕”需要有情绪的主语，“这本书”不会害怕，句子不通。"}, {"text": "想", "is_correct": false, "explanation": "语义：“想”要求有思考能力的主语，书不能思考，句子不通。"}, {"text": "担心", "is_correct": false, "explanation": "搭配：“担心”的主语应是人，不能用“这本书”作主语。"}], "explanations": {"不比": "不比：两者相比，这个并不超过那个。此处说“这本书”并不比“那本”厚。", "怕": "语义：“怕”需要有情绪的主语，“这本书”不会害怕，句子不通。", "想": "语义：“想”要求有思考能力的主语，书不能思考，句子不通。", "担心": "搭配：“担心”的主语应是人，不能用“这本书”作主语。"}, "sentence_index": 0, "correct_answer": "不比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服不比那件很便宜。", "explanation": "“不比”比较句中，形容词前不能加“很”，应说“不比那件便宜”。"}, {"text": "这件衣服那件不比便宜。", "explanation": "语序错误：“不比”应放在比较对象“那件”之前，应说“这件衣服不比那件便宜”。"}, {"text": "这件衣服不比那件最便宜。", "explanation": "“不比”比较两者，后面不能用表示最高级的“最”，应说“不比那件便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不比", "is_correct": true, "explanation": "不比：两者相比，这个并不超过那个。此处说“北京的夏天”并不比“上海”热。"}, {"text": "嫌", "is_correct": false, "explanation": "语义：“嫌”的主语应是有意愿的人，“北京的夏天”不会嫌弃，句子不通。"}, {"text": "盼望", "is_correct": false, "explanation": "搭配：“盼望”需要有意愿的主语，“北京的夏天盼望上海热”不通。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”需要有记忆能力的主语，夏天不能忘记，句子不通。"}], "explanations": {"不比": "不比：两者相比，这个并不超过那个。此处说“北京的夏天”并不比“上海”热。", "嫌": "语义：“嫌”的主语应是有意愿的人，“北京的夏天”不会嫌弃，句子不通。", "盼望": "搭配：“盼望”需要有意愿的主语，“北京的夏天盼望上海热”不通。", "忘记": "语义：“忘记”需要有记忆能力的主语，夏天不能忘记，句子不通。"}, "sentence_index": 6, "correct_answer": "不比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路不比那条路很近。", "explanation": "“不比”比较句中，形容词前不能加“很”，应说“不比那条路近”。"}, {"text": "这条路那条路不比近。", "explanation": "语序错误：“不比”应放在比较对象“那条路”之前。"}, {"text": "这条路不比那条路最近。", "explanation": "“不比”比较两者，后面不能用表示最高级的“最”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个包不比重。", "corrected_sentence": "这个包不比那个重。", "error_description": "错误在于“不比”缺少比较对象，漏掉了“那个”。比较句中“不比”后必须有比较对象，应为“不比那个重”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支笔不比长。", "corrected_sentence": "这支笔不比那支长。", "error_description": "错误在于“不比”缺少比较对象，漏掉了“那支”。比较句中“不比”后必须有比较对象，应为“不比那支长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
