INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87918, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87918, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示在比较中并不超过对方；不及。", "primary_collocate": null, "pronunciation": "bù bǐ", "ipa": "pu˥˩ pi˨˩", "syllable_count": 2, "sentences": [{"text": "我的汉语不比他好。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不比我高多少。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜不比那家贵。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不比昨天冷。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得不比我快。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家不比你家远。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的员工不比那家少。", "target_word": "不比", "complexity_tier": "T3", "furigana": "zhè jiā gōngsī de yuángōng bù bǐ nà jiā shǎo", "sentence_source": "generated"}, {"text": "他的成绩不比我的好。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不比他早到。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试不比上次难。", "target_word": "不比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "比较中并不超过对方，不及", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9987eb-5886-4587-85c6-5e6350eb4adf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不比", "is_correct": true, "explanation": "不比：在比较中表示并不超过对方。此处说“我的汉语”并不超过“他”。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”需要会说话的主语，“汉语”不能说，“说他好”也不是比较，句子不通。"}, {"text": "觉得", "is_correct": false, "explanation": "搭配：“觉得”要求有感知能力的主语，不能以“汉语”作主语。"}, {"text": "认为", "is_correct": false, "explanation": "语义：“认为”表示人的看法，“汉语认为他好”没有意义，句子不通。"}], "explanations": {"不比": "不比：在比较中表示并不超过对方。此处说“我的汉语”并不超过“他”。", "说": "语义：“说”需要会说话的主语，“汉语”不能说，“说他好”也不是比较，句子不通。", "觉得": "搭配：“觉得”要求有感知能力的主语，不能以“汉语”作主语。", "认为": "语义：“认为”表示人的看法，“汉语认为他好”没有意义，句子不通。"}, "sentence_index": 0, "correct_answer": "不比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天不比昨天很冷。", "explanation": "“不比”比较句中，形容词前不能加“很”，应说“不比昨天冷”。"}, {"text": "今天昨天不比冷。", "explanation": "语序错误：“不比”应放在比较对象“昨天”之前。"}, {"text": "今天不比昨天最冷。", "explanation": "“不比”比较两者，后面不能用表示最高级的“最”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不比", "is_correct": true, "explanation": "不比：在比较中表示并不超过对方。此处说“这家公司的员工”并不少于“那家”。"}, {"text": "输给", "is_correct": false, "explanation": "语义：“输给”表示胜负，“那家少”不是可以输赢的结果，句子不通。"}, {"text": "代表", "is_correct": false, "explanation": "搭配：“代表”后接的应是可以被代表的人或事物，“代表那家少”不成立。"}, {"text": "属于", "is_correct": false, "explanation": "配价：“属于”后接领属的名词，不能接“那家少”这样的谓语结构。"}], "explanations": {"不比": "不比：在比较中表示并不超过对方。此处说“这家公司的员工”并不少于“那家”。", "输给": "语义：“输给”表示胜负，“那家少”不是可以输赢的结果，句子不通。", "代表": "搭配：“代表”后接的应是可以被代表的人或事物，“代表那家少”不成立。", "属于": "配价：“属于”后接领属的名词，不能接“那家少”这样的谓语结构。"}, "sentence_index": 6, "correct_answer": "不比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试不比上次很难。", "explanation": "“不比”比较句中，形容词前不能加“很”，应说“不比上次难”。"}, {"text": "这次考试上次不比难。", "explanation": "语序错误：“不比”应放在比较对象“上次”之前。"}, {"text": "这次考试不比上次最难。", "explanation": "“不比”比较两者，后面不能用表示最高级的“最”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作不比那份很轻松。", "corrected_sentence": "这份工作不比那份轻松。", "error_description": "错误：“不比”比较句中，形容词谓语前不能加“很”，应删去“很”，正确为“不比那份轻松”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑不比比那台旧。", "corrected_sentence": "这台电脑不比那台旧。", "error_description": "错误在于“不比”后多加了一个“比”，写成“不比比”。“不比”之后应直接接比较对象，正确应为“不比那台旧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
