INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87920, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "创作文学、艺术等作品时所用的原始材料。", "primary_collocate": null, "pronunciation": "sù cái", "ipa": "su˥˩ tsʰai˧˥", "syllable_count": 2, "sentences": [{"text": "民间故事是作家创作的好素材。", "target_word": "素材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的素材来自真实的事。", "target_word": "素材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演花了两年收集拍片素材。", "target_word": "素材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家从生活中选取创作素材。", "target_word": "素材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人的素材都来自农村。", "target_word": "素材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史是小说家重要的素材。", "target_word": "素材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旅行见闻当成作品的素材。", "target_word": "素材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些创作素材还要再整理一下。", "target_word": "素材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐家用鸟叫声做了创作素材。", "target_word": "素材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的素材能让作品更有意思。", "target_word": "素材", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "素材库", "label": "复合"}, {"form": "创作素材", "label": "复合"}], "register": "通用", "sense_fingerprint": "创作文学艺术作品所用的原始材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfd08e-3d21-43ff-b039-b447ed2d2985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "素材", "is_correct": true, "explanation": "正确：「素材」指创作作品所用的原始材料，「作家创作的好素材」自然。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：「乐器」是演奏用的器具，民间故事不是乐器。"}, {"text": "零食", "is_correct": false, "explanation": "语义：「零食」是吃的东西，故事不能当零食，与创作无关。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：「水泥」是建筑材料，不能作为文学创作的素材。"}], "explanations": {"素材": "正确：「素材」指创作作品所用的原始材料，「作家创作的好素材」自然。", "乐器": "语义：「乐器」是演奏用的器具，民间故事不是乐器。", "零食": "语义：「零食」是吃的东西，故事不能当零食，与创作无关。", "水泥": "语义：「水泥」是建筑材料，不能作为文学创作的素材。"}, "sentence_index": 0, "correct_answer": "素材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂从外地选取素材生产汽车。", "explanation": "这里应该用〈原料〉。素材只指文学、艺术创作的原始材料，工厂生产要用原料。"}, {"text": "这盘菜的素材很新鲜。", "explanation": "这里应该用〈食材〉。素材只用于文学、艺术等创作，菜的原料要说食材。"}, {"text": "工人用素材盖房子。", "explanation": "这里应该用〈建材〉。素材是创作用的原始材料，盖房子要用建筑材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "素材", "is_correct": true, "explanation": "正确：「素材」指作品的原始材料，「当成作品的素材」自然。"}, {"text": "工资", "is_correct": false, "explanation": "语义：「工资」是劳动报酬，不是作品的原始材料。"}, {"text": "股票", "is_correct": false, "explanation": "语义：「股票」是金融产品，与作品创作无关。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：「地址」只用于人或地点，不能说「作品的地址」。"}], "explanations": {"素材": "正确：「素材」指作品的原始材料，「当成作品的素材」自然。", "工资": "语义：「工资」是劳动报酬，不是作品的原始材料。", "股票": "语义：「股票」是金融产品，与作品创作无关。", "地址": "搭配：「地址」只用于人或地点，不能说「作品的地址」。"}, "sentence_index": 6, "correct_answer": "素材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "养猪场的素材很便宜。", "explanation": "这里应该用〈饲料〉。素材指创作用的原始材料，养猪场卖的应是饲料。"}, {"text": "这家药店进了很多素材。", "explanation": "这里应该用〈药材〉。素材指创作用的原始材料，药店进货要用药材。"}, {"text": "钢铁厂每天要用很多素材炼钢。", "explanation": "这里应该用〈原料〉。素材指文学、艺术创作的原始材料，炼钢用的是原料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作家整理了一只创作素材。", "corrected_sentence": "作家整理了一批创作素材。", "error_description": "错误：量词用错。「只」用于动物或成对物品中的单个，不能修饰「创作素材」；素材常用「批」或「些」，应说「一批创作素材」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他收集了很多创作了素材。", "corrected_sentence": "他收集了很多创作素材。", "error_description": "错误：「了」插在「创作」和「素材」之间，打断了名词短语「创作素材」。应说「他收集了很多创作素材」，「了」只放在动词「收集」后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
