INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87922, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体的表面；人的身体上。", "primary_collocate": null, "pronunciation": "shēn shang", "ipa": "ʂən˥ ʂaŋ", "syllable_count": 2, "sentences": [{"text": "他身上全是汗，快去洗个澡吧。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她身上有一股好闻的香味。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打球时，他身上受了点儿伤。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩身上起了很多红点儿。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我身上很痒，可能被蚊子咬了。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身上有一块很大的伤疤。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，我身上都湿了。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚踢完球，身上很脏。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子身上有几道红色的划痕。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身上有烟味，大家都不喜欢。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "身体的表面，汗水、气味、伤口、皮肤状况出现的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 快去 (Zipf 3.41), 洗个 (Zipf 3.02), 澡 (Zipf 3.68)']::text[], '126c10af-4fb6-480f-99ce-28dd5cb5b8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身上", "is_correct": true, "explanation": "正确：身上指身体表面，汗水出在身体表面。"}, {"text": "门口", "is_correct": false, "explanation": "语义：门口指门外的地方，汗不会出在门口。"}, {"text": "桌上", "is_correct": false, "explanation": "搭配：“全是汗”说的是人或物的表面，“桌上”不能与此搭配。"}, {"text": "窗外", "is_correct": false, "explanation": "语义：窗外指窗户以外，汗不会出在窗外。"}], "explanations": {"身上": "正确：身上指身体表面，汗水出在身体表面。", "门口": "语义：门口指门外的地方，汗不会出在门口。", "桌上": "搭配：“全是汗”说的是人或物的表面，“桌上”不能与此搭配。", "窗外": "语义：窗外指窗户以外，汗不会出在窗外。"}, "sentence_index": 0, "correct_answer": "身上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身上很高兴，一直在笑。", "explanation": "这里应该用〈心里〉。身上指身体的表面，“高兴”是内心的感受。"}, {"text": "会议在他身上进行了两个小时。", "explanation": "身上只指身体的表面状况，不能表示会议等活动的场所。"}, {"text": "他身上放着一杯热茶，一直没喝。", "explanation": "这里应该用〈身边〉。身上指身体的表面，茶杯放在人旁边要用〈身边〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身上", "is_correct": true, "explanation": "正确：湿的是人的身体表面，身上指身体表面。"}, {"text": "眼前", "is_correct": false, "explanation": "语义：眼前指眼睛的前方，雨水不会把眼前弄湿。"}, {"text": "心底", "is_correct": false, "explanation": "语义：心底指内心深处，雨淋湿的是身体表面，不是心底。"}, {"text": "脑子里", "is_correct": false, "explanation": "搭配：“湿”说的是衣物或皮肤等表面，“脑子里”不能与“湿”搭配。"}], "explanations": {"身上": "正确：湿的是人的身体表面，身上指身体表面。", "眼前": "语义：眼前指眼睛的前方，雨水不会把眼前弄湿。", "心底": "语义：心底指内心深处，雨淋湿的是身体表面，不是心底。", "脑子里": "搭配：“湿”说的是衣物或皮肤等表面，“脑子里”不能与“湿”搭配。"}, "sentence_index": 6, "correct_answer": "身上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他身上很聪明，总能想出好办法。", "explanation": "这里应该用〈脑子〉。身上指身体的表面，“聪明”说的是脑子的能力。"}, {"text": "这张纸身上写着几行字。", "explanation": "这里应该用〈上面〉。身上指人或动物身体的表面，纸不是身体，写在纸上的字要用〈上面〉。"}, {"text": "他身上有很多朋友，大家都很喜欢他。", "explanation": "这里应该用〈身边〉。身上指身体的表面，朋友在附近要用〈身边〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汗水流他身上，衣服都湿透了。", "corrected_sentence": "汗水流在他身上，衣服都湿透了。", "error_description": "介词错误：处所“他身上”位于动词“流”之后，前面要加“在”，漏掉“在”。正确形式是“汗水流在他身上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚踢完球，身上很脏极了。", "corrected_sentence": "他刚踢完球，身上脏极了。", "error_description": "程度副词错误：“很”和“极了”不能同时修饰“脏”，多了“很”。正确形式是“身上脏极了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
