INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87925, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "初次是第一次做这件事。", "primary_collocate": null, "pronunciation": "chū cì", "ipa": "ʈʂʰu˥ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "初次见到你，我很高兴。", "target_word": "初次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是他初次骑马。", "target_word": "初次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师初次上课，先介绍了自己。", "target_word": "初次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我初次参加比赛，成绩不错。", "target_word": "初次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初次来我家的客人都说很漂亮。", "target_word": "初次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她初次一个人去旅行。", "target_word": "初次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王初次打电话给我，是在昨天。", "target_word": "初次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初次学游泳，我喝了很多水。", "target_word": "初次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他初次在机场见面。", "target_word": "初次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初次使用这个机器，请先看说明。", "target_word": "初次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "初次见面", "label": "复合"}], "register": "书面", "sense_fingerprint": "初次：第一次做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03c657c1-bea8-4c65-833c-a2de6b45be3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87925, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "初次", "is_correct": true, "explanation": "正确答案。“初次”（chū cì）指第一次、头一回。"}, {"text": "除此", "is_correct": false, "explanation": "除 chú（第二声）与 初 chū（第一声）声调不同，此 cǐ（第三声）与 次 cì（第四声）也不同，意思是“除了这个”。"}, {"text": "出事", "is_correct": false, "explanation": "次 cì 与 事 shì 声母不同（c 与 sh），意思是“发生意外”。"}, {"text": "出自", "is_correct": false, "explanation": "次 cì 与 自 zì 声母不同（c 与 z），意思是“来自”。"}], "explanations": {"初次": "正确答案。“初次”（chū cì）指第一次、头一回。", "除此": "除 chú（第二声）与 初 chū（第一声）声调不同，此 cǐ（第三声）与 次 cì（第四声）也不同，意思是“除了这个”。", "出事": "次 cì 与 事 shì 声母不同（c 与 sh），意思是“发生意外”。", "出自": "次 cì 与 自 zì 声母不同（c 与 z），意思是“来自”。"}, "sentence_index": null, "correct_answer": "初次"}, "level_3": {"options": [{"text": "初次", "is_correct": true, "explanation": "正确答案。“初次见到你”指第一次见到你，与“我很高兴”的语境相符。"}, {"text": "整个", "is_correct": false, "explanation": "搭配：“整个”修饰名词或名词性成分，不能直接修饰“见到你”这样的动作，句子不通。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无可奈何，与“见到你，我很高兴”的情绪不符，句子不通。"}, {"text": "逐渐", "is_correct": false, "explanation": "搭配：“逐渐”表示渐进变化，不与“见到你”这种一次性的瞬间动作搭配。"}], "explanations": {"初次": "正确答案。“初次见到你”指第一次见到你，与“我很高兴”的语境相符。", "整个": "搭配：“整个”修饰名词或名词性成分，不能直接修饰“见到你”这样的动作，句子不通。", "只好": "语义：“只好”表示无可奈何，与“见到你，我很高兴”的情绪不符，句子不通。", "逐渐": "搭配：“逐渐”表示渐进变化，不与“见到你”这种一次性的瞬间动作搭配。"}, "sentence_index": 0, "correct_answer": "初次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我初次是班长。", "explanation": "这里应该用〈一直〉，表示状态持续。初次只用于第一次发生的动作，不能修饰表示状态的判断动词。"}, {"text": "我初次参加了三次比赛，成绩不错。", "explanation": "这里的意思是“多次”，与“初次”的“第一次”矛盾，两者不能用于同一件事。"}, {"text": "我又初次参加比赛，成绩不错。", "explanation": "这里的意思是“再次”，与“初次”的“第一次”相反，不能用于同一场比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初次", "is_correct": true, "explanation": "正确答案。“初次打电话给我”指第一次打电话，与“是在昨天”的时间相符。"}, {"text": "经常", "is_correct": false, "explanation": "语义：“经常”表示反复发生，与“是在昨天”专指某一次时间矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示紧接着某件事马上发生，句中没有前一件事；“……是在昨天”是在说明哪一次发生的时间，用“立刻”不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示不定期，不能与“是在昨天”这样确定的时间搭配。"}], "explanations": {"初次": "正确答案。“初次打电话给我”指第一次打电话，与“是在昨天”的时间相符。", "经常": "语义：“经常”表示反复发生，与“是在昨天”专指某一次时间矛盾。", "立刻": "语义：“立刻”表示紧接着某件事马上发生，句中没有前一件事；“……是在昨天”是在说明哪一次发生的时间，用“立刻”不通。", "偶尔": "搭配：“偶尔”表示不定期，不能与“是在昨天”这样确定的时间搭配。"}, "sentence_index": 6, "correct_answer": "初次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我上次初次使用这个机器，觉得很简单。", "explanation": "这里的意思是“之前已经用过”，与“第一次”的“初次”矛盾。"}, {"text": "我以前初次使用过这个机器，觉得很简单。", "explanation": "这里的意思是“过去已经用过”，与“第一次”矛盾，两者不能同用。"}, {"text": "这是我最后初次使用这个机器，觉得很简单。", "explanation": "这里的意思是“末次”，与“第一次”的“初次”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我初次的做这道菜，味道还不错。", "corrected_sentence": "我初次做这道菜，味道还不错。", "error_description": "“初次”是副词，不能加“的”修饰动词。错误形式：初次的做；正确形式：初次做。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很初次来到这座城市，一切都很新鲜。", "corrected_sentence": "她初次来到这座城市，一切都很新鲜。", "error_description": "“初次”是副词，不能被程度副词“很”修饰。错误形式：很初次来到；正确形式：初次来到。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
