INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初次", "is_correct": true, "explanation": "正确答案。“初次见面”指第一次见面，与“是在去年春天”的时间指向相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示紧接着前一件事马上发生，句中没有前一件事；“……是在去年春天”是在说明哪一次见面的时间，用“立刻”不通。"}, {"text": "经常", "is_correct": false, "explanation": "语义：“经常”表示反复发生，与“是在去年春天”专指一次时间不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示不定期，不能与“是在去年春天”这样确定的时间搭配。"}], "explanations": {"初次": "正确答案。“初次见面”指第一次见面，与“是在去年春天”的时间指向相符。", "立刻": "语义：“立刻”表示紧接着前一件事马上发生，句中没有前一件事；“……是在去年春天”是在说明哪一次见面的时间，用“立刻”不通。", "经常": "语义：“经常”表示反复发生，与“是在去年春天”专指一次时间不符。", "偶尔": "搭配：“偶尔”表示不定期，不能与“是在去年春天”这样确定的时间搭配。"}, "sentence_index": 6, "correct_answer": "初次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子上次初次离开家，很想妈妈。", "explanation": "这里的意思是“之前已经有过”，与“第一次”的“初次”矛盾。"}, {"text": "孩子以前初次离开过家，很想妈妈。", "explanation": "这里的意思是“过去已经有过”，与“第一次”矛盾，两者不能同用。"}, {"text": "孩子最后初次离开家，很想妈妈。", "explanation": "这里的意思是“末次”，与“第一次”的“初次”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我初次的来上海，觉得什么都很新鲜。", "corrected_sentence": "我初次来上海，觉得什么都很新鲜。", "error_description": "“初次”是副词，应直接修饰动词，不能加“的”变成定语。错误形式：初次的来上海；正确形式：初次来上海。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们很初次去海边，玩得非常开心。", "corrected_sentence": "他们初次去海边，玩得非常开心。", "error_description": "“初次”是副词，不能被程度副词“很”修饰。错误形式：很初次去海边；正确形式：初次去海边。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
