INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87927, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "激化", "is_correct": true, "explanation": "反义：“激化”指矛盾、争吵变得更尖锐，与“缓和”相对。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”指探讨、考察，与“缓和”没有反义关系。"}, {"text": "摇晃", "is_correct": false, "explanation": "无关：“摇晃”指来回晃动，与“缓和”没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "无关：“收集”指聚拢、搜集，与“缓和”没有反义关系。"}], "correct_answer": "激化", "explanations": {"激化": "反义：“激化”指矛盾、争吵变得更尖锐，与“缓和”相对。", "研究": "无关：“研究”指探讨、考察，与“缓和”没有反义关系。", "摇晃": "无关：“摇晃”指来回晃动，与“缓和”没有反义关系。", "收集": "无关：“收集”指聚拢、搜集，与“缓和”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87927, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "缓和是紧张的心情、关系或局势自己变得轻松、平稳一些。", "primary_collocate": null, "pronunciation": "huǎn hé", "ipa": "xwan˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "听到好消息，她紧张的心情缓和了。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完他的解释，紧张的局面缓和了一些。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家的关系慢慢缓和了。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完音乐，我的紧张情绪缓和了不少。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停以后，城里的紧张局面缓和了。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友笑着说了几句，现场的气氛缓和下来。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过谈判，两国的矛盾缓和了。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气转暖，今年的用电紧张也缓和了。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑了笑，屋里紧张的空气缓和了。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一会儿，两个人的争吵缓和下来了。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缓和了", "label": "完成体"}, {"form": "缓和过", "label": "经历体"}, {"form": "缓和缓和", "label": "重叠"}, {"form": "缓和剂", "label": "复合词"}], "register": "中性", "sense_fingerprint": "紧张的心情、关系或情况自己变轻松（不带宾语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87927, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缓和", "is_correct": true, "explanation": "正确：缓和指紧张的心情自己变轻松，与听到好消息后心情放松的语境相符。"}, {"text": "加重", "is_correct": false, "explanation": "语义：听到好消息，心情应当放松，“加重”与好消息的语境相反。"}, {"text": "升级", "is_correct": false, "explanation": "语义：听到好消息，紧张应当减轻，“升级”指程度加深，与语境相反。"}, {"text": "膨胀", "is_correct": false, "explanation": "搭配：“膨胀”用于体积、欲望等增大，不说紧张的心情膨胀。"}], "explanations": {"缓和": "正确：缓和指紧张的心情自己变轻松，与听到好消息后心情放松的语境相符。", "加重": "语义：听到好消息，心情应当放松，“加重”与好消息的语境相反。", "升级": "语义：听到好消息，紧张应当减轻，“升级”指程度加深，与语境相反。", "膨胀": "搭配：“膨胀”用于体积、欲望等增大，不说紧张的心情膨胀。"}, "sentence_index": 0, "correct_answer": "缓和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的体重缓和了不少。", "explanation": "这里应该用〈减轻〉。缓和用于紧张的情绪、局势，体重下降要用减轻。"}, {"text": "他的视力缓和了不少。", "explanation": "这里应该用〈减退〉。缓和用于紧张的情绪、局势，不用于视力等生理机能的衰退。"}, {"text": "来参观的人数缓和了不少。", "explanation": "这里应该用〈减少〉。缓和不用于人数、数量的变化，人数减少要说减少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缓和", "is_correct": true, "explanation": "正确：缓和指矛盾变平稳，与“经过谈判”的结果相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于房间、卫生等，不说矛盾打扫了。"}, {"text": "分裂", "is_correct": false, "explanation": "搭配：“分裂”说国家、组织等分开，不说矛盾分裂。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”用于任务、工作，不说矛盾完成。"}], "explanations": {"缓和": "正确：缓和指矛盾变平稳，与“经过谈判”的结果相符。", "打扫": "搭配：“打扫”用于房间、卫生等，不说矛盾打扫了。", "分裂": "搭配：“分裂”说国家、组织等分开，不说矛盾分裂。", "完成": "搭配：“完成”用于任务、工作，不说矛盾完成。"}, "sentence_index": 6, "correct_answer": "缓和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的钱包缓和了不少。", "explanation": "这里应该用〈变瘪〉。缓和用于紧张的情绪、局势，不用于钱包这类物品，钱包空了要说瘪。"}, {"text": "他的汽车缓和了不少。", "explanation": "这里应该用〈减速〉。缓和用于局势、气氛、关系，车速的变化要用减速或加速。"}, {"text": "这家公司的规模缓和了不少。", "explanation": "这里应该用〈扩大〉。缓和指紧张的局势或情绪变平稳，规模的增大要用扩大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听了她的话，我的紧张心情缓和了出来。", "corrected_sentence": "听了她的话，我的紧张心情缓和了下来。", "error_description": "补语选用错误。“缓和”表示紧张逐渐松弛下来，应用“下来”，不能用“出来”。应说“缓和了下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议开始以后，双方的紧张情绪缓和了了。", "corrected_sentence": "会议开始以后，双方的紧张情绪缓和了。", "error_description": "句末多加了一个“了”。“缓和了”已经表示变化完成，“了”不能重复使用。应说“缓和了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87928, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "激化", "is_correct": true, "explanation": "反义：“激化”指矛盾、局势变得更尖锐，与“缓和”相对。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”指把东西归类、安排好，与“缓和”没有反义关系。"}, {"text": "扩展", "is_correct": false, "explanation": "无关：“扩展”指范围扩大，与使紧张的局势变平稳没有反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "无关：“保存”指留存、妥善保管，与“缓和”没有反义关系。"}], "correct_answer": "激化", "explanations": {"激化": "反义：“激化”指矛盾、局势变得更尖锐，与“缓和”相对。", "整理": "无关：“整理”指把东西归类、安排好，与“缓和”没有反义关系。", "扩展": "无关：“扩展”指范围扩大，与使紧张的局势变平稳没有反义关系。", "保存": "无关：“保存”指留存、妥善保管，与“缓和”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
