INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87928, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使紧张的局势、气氛或情绪变得和缓、平稳。", "primary_collocate": null, "pronunciation": "huǎn hé", "ipa": "xwan˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他讲了一个笑话，缓和了会场的气氛。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国谈了三天，终于缓和了边境局势。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师笑着说话，缓和了教室里的紧张气氛。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的几句话缓和了大家的紧张情绪。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用音乐缓和一下现场的气氛。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们来劝架，才缓和了他们的矛盾。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的话缓和了病人家属的紧张心情。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把声音放轻，想缓和一下紧张的气氛。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方都让了一步，缓和了紧张的关系。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热茶和笑声缓和了会议室里的气氛。", "target_word": "缓和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缓和了", "label": "完成体"}, {"form": "缓和过", "label": "经历体"}, {"form": "缓和缓和", "label": "重叠"}, {"form": "缓和剂", "label": "复合词"}], "register": "中性", "sense_fingerprint": "使紧张的局势、气氛、关系或情绪变得平稳（带宾语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缓和", "is_correct": true, "explanation": "正确：缓和指使紧张的气氛变平稳，与讲笑话让会场轻松的语境相符。"}, {"text": "吸收", "is_correct": false, "explanation": "搭配：“吸收”的对象是养分、知识、意见等，不能说吸收会场的气氛。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”用于车、船、飞机等，不能说驾驶气氛。"}, {"text": "批准", "is_correct": false, "explanation": "配价：“批准”的宾语是申请、计划、决定等，不能以“气氛”作宾语。"}], "explanations": {"缓和": "正确：缓和指使紧张的气氛变平稳，与讲笑话让会场轻松的语境相符。", "吸收": "搭配：“吸收”的对象是养分、知识、意见等，不能说吸收会场的气氛。", "驾驶": "搭配：“驾驶”用于车、船、飞机等，不能说驾驶气氛。", "批准": "配价：“批准”的宾语是申请、计划、决定等，不能以“气氛”作宾语。"}, "sentence_index": 0, "correct_answer": "缓和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最近他的工作负担缓和了不少。", "explanation": "这里应该用〈减轻〉。缓和用于局势、气氛、关系等，负担、压力要用减轻。"}, {"text": "他把绳子缓和了一点。", "explanation": "这里应该用〈松开〉。缓和表示局势或关系变得平稳，不用于松动绳子这类具体物体。"}, {"text": "两国的贸易额缓和了不少。", "explanation": "这里应该用〈减少〉。缓和只用于紧张的局势、气氛，额度、数量的下降要用减少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缓和", "is_correct": true, "explanation": "正确：缓和指使紧张的心情变平稳，与医生的话安抚家属的语境相符。"}, {"text": "监督", "is_correct": false, "explanation": "配价：“监督”的对象是人或工作，不能以“心情”作宾语。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”用于任务、工作，不说完成紧张的心情。"}, {"text": "登记", "is_correct": false, "explanation": "搭配：“登记”用于姓名、物品等，不能说登记心情。"}], "explanations": {"缓和": "正确：缓和指使紧张的心情变平稳，与医生的话安抚家属的语境相符。", "监督": "配价：“监督”的对象是人或工作，不能以“心情”作宾语。", "完成": "搭配：“完成”用于任务、工作，不说完成紧张的心情。", "登记": "搭配：“登记”用于姓名、物品等，不能说登记心情。"}, "sentence_index": 6, "correct_answer": "缓和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他躺在沙发上，缓和了一下身体。", "explanation": "这里应该用〈放松〉。缓和用于局势、气氛、关系，不指身体的松弛，身体放松要说放松。"}, {"text": "消防队缓和了火灾警报。", "explanation": "这里应该用〈解除〉。缓和指局势、气氛变平稳，不用于解除警报这类措施。"}, {"text": "他的工资缓和了不少。", "explanation": "这里应该用〈增加〉。缓和用于局势、气氛、关系，工资的变化要用增加或减少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次会谈缓和地了两国之间的紧张关系。", "corrected_sentence": "这次会谈缓和了两国之间的紧张关系。", "error_description": "“缓和”后面多加了“地”，又接“了”。应说“缓和了”。“地”用于修饰动词，要放在动词之前，不能放在动词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场谈话缓和下来双方的敌对情绪。", "corrected_sentence": "这场谈话缓和了双方的敌对情绪。", "error_description": "“下来”用错了位置和用法。“缓和”带宾语“双方的敌对情绪”时，应用“了”，说“缓和了”。“缓和下来”是不及物用法，后面不能再接宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
