INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87929, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "几是问有多少个，数目不太大。", "primary_collocate": null, "pronunciation": "jǐ", "ipa": "tɕi˨˩˦", "syllable_count": 1, "sentences": [{"text": "你们班有几个人？", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你家门口有几棵树？", "target_word": "几", "complexity_tier": "T3", "furigana": "nǐ jiā ménkǒu yǒu jǐ kē shù", "sentence_source": "generated"}, {"text": "你想买几张票？", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一个月看几本书？", "target_word": "几", "complexity_tier": "T3", "furigana": "tā yí gè yuè kàn jǐ běn shū", "sentence_source": "generated"}, {"text": "你一天喝几杯水？", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你们学校有几个门？", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请问，你要几个？", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你昨天睡了几个小时？", "target_word": "几", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上有几个杯子？", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你家养了几只猫？", "target_word": "几", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "几个", "label": "复合"}, {"form": "几点", "label": "复合"}], "register": "中性", "sense_fingerprint": "询问不太大的数目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9987eb-5886-4587-85c6-5e6350eb4adf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87929, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "几", "is_correct": true, "explanation": "几 jǐ：询问有多少个，数目不太大。"}, {"text": "技", "is_correct": false, "explanation": "jì（第四声）与 jǐ（第三声）声调不同，“技”意思是技能。"}, {"text": "积", "is_correct": false, "explanation": "jī（第一声）与 jǐ（第三声）声调不同，“积”意思是积累。"}, {"text": "吉", "is_correct": false, "explanation": "jí（第二声）与 jǐ（第三声）声调不同，“吉”意思是吉祥。"}, {"text": "籍", "is_correct": false, "explanation": "jí（第二声）与 jǐ（第三声）声调不同，“籍”意思是户籍或书籍。"}], "explanations": {"几": "几 jǐ：询问有多少个，数目不太大。", "技": "jì（第四声）与 jǐ（第三声）声调不同，“技”意思是技能。", "积": "jī（第一声）与 jǐ（第三声）声调不同，“积”意思是积累。", "吉": "jí（第二声）与 jǐ（第三声）声调不同，“吉”意思是吉祥。", "籍": "jí（第二声）与 jǐ（第三声）声调不同，“籍”意思是户籍或书籍。"}, "sentence_index": null, "correct_answer": "几"}, "level_3": {"options": [{"text": "几", "is_correct": true, "explanation": "几：询问“你们班”有多少人，数目不太大。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能放在“有”后作数量成分，“有很个人”不通。"}, {"text": "都", "is_correct": false, "explanation": "语法：“都”是副词，不能直接修饰“个人”，“有都个人”不通。"}, {"text": "是", "is_correct": false, "explanation": "语法：“是”是动词，不能放在“有”后再接数量结构，“有是个人”不通。"}], "explanations": {"几": "几：询问“你们班”有多少人，数目不太大。", "很": "语法：“很”是程度副词，不能放在“有”后作数量成分，“有很个人”不通。", "都": "语法：“都”是副词，不能直接修饰“个人”，“有都个人”不通。", "是": "语法：“是”是动词，不能放在“有”后再接数量结构，“有是个人”不通。"}, "sentence_index": 0, "correct_answer": "几"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个月看本几书。", "explanation": "这里应该用〈几本〉。“几”必须放在量词“本”之前，写成“本几书”顺序颠倒，不成词组。"}, {"text": "他一个月看几的书。", "explanation": "这里应该用〈几本〉。“几”询问或表示数目时要直接接量词，“的”打断了数量结构。"}, {"text": "他一个月看几个本书。", "explanation": "这里应该用〈几本〉。“几”后只接一个量词，“个本”重复了量词，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87929, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "几", "is_correct": true, "explanation": "几 jǐ：询问有多少个，数目不太大。"}, {"text": "记", "is_correct": false, "explanation": "jì（第四声）与 jǐ（第三声）声调不同，“记”意思是记录。"}, {"text": "基", "is_correct": false, "explanation": "jī（第一声）与 jǐ（第三声）声调不同，“基”意思是基础。"}, {"text": "级", "is_correct": false, "explanation": "jí（第二声）与 jǐ（第三声）声调不同，“级”意思是等级或年级。"}, {"text": "季", "is_correct": false, "explanation": "jì（第四声）与 jǐ（第三声）声调不同，“季”意思是季节。"}, {"text": "寄", "is_correct": false, "explanation": "jì（第四声）与 jǐ（第三声）声调不同，“寄”意思是邮寄。"}], "explanations": {"几": "几 jǐ：询问有多少个，数目不太大。", "记": "jì（第四声）与 jǐ（第三声）声调不同，“记”意思是记录。", "基": "jī（第一声）与 jǐ（第三声）声调不同，“基”意思是基础。", "级": "jí（第二声）与 jǐ（第三声）声调不同，“级”意思是等级或年级。", "季": "jì（第四声）与 jǐ（第三声）声调不同，“季”意思是季节。", "寄": "jì（第四声）与 jǐ（第三声）声调不同，“寄”意思是邮寄。"}, "sentence_index": null, "correct_answer": "几"}, "level_3": {"options": [{"text": "几", "is_correct": true, "explanation": "几：询问对方要多少个，数目不太大。"}, {"text": "也", "is_correct": false, "explanation": "语法：“也”是副词，不能用作数量成分，“请问，你要也个”不通。"}, {"text": "就", "is_correct": false, "explanation": "语法：“就”是副词，不能放在“要”后作数量成分，“你要就个”不通。"}, {"text": "又", "is_correct": false, "explanation": "语法：“又”是副词，不能修饰“个”，“你要又个”不通。"}], "explanations": {"几": "几：询问对方要多少个，数目不太大。", "也": "语法：“也”是副词，不能用作数量成分，“请问，你要也个”不通。", "就": "语法：“就”是副词，不能放在“要”后作数量成分，“你要就个”不通。", "又": "语法：“又”是副词，不能修饰“个”，“你要又个”不通。"}, "sentence_index": 6, "correct_answer": "几"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你家养了几只只猫。", "explanation": "这里应该用〈几只猫〉。“几”后只接一个量词，“只只”重复了量词，不能这样说。"}, {"text": "你家养了几的猫。", "explanation": "这里应该用〈几只猫〉。“几”询问数目时要直接接量词，“的”打断了数量结构。"}, {"text": "你家养了只几猫。", "explanation": "这里应该用〈几只猫〉。“几”必须放在量词“只”之前，“只几”颠倒后不成词组。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家养了几猫。", "corrected_sentence": "他家养了几只猫。", "error_description": "错误在于“几”后漏掉了量词“只”，写成“几猫”。询问数目时需要量词，应为“几只猫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你昨天吃了个几包子？", "corrected_sentence": "你昨天吃了几个包子？", "error_description": "错误在于“几”和“个”的顺序颠倒，写成“个几”。“几”应放在量词“个”之前，正确应为“几个包子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
