INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87930, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问数目（多用于十以内）；也表示不确定的数目。", "primary_collocate": null, "pronunciation": "jǐ", "ipa": "tɕi˨˩˦", "syllable_count": 1, "sentences": [{"text": "你家有几口人？", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们班有几个同学？", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上有几本书。", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我等了他几天。", "target_word": "几", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你今年几岁了？", "target_word": "几", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天只睡几个小时。", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过几天我们再见面。", "target_word": "几", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一共买了几个苹果？", "target_word": "几", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里只剩下几个学生。", "target_word": "几", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年他变化很大。", "target_word": "几", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "几个", "label": "复合"}, {"form": "几点", "label": "复合"}], "register": "中性", "sense_fingerprint": "疑问数目（十以内）或表示不定的少量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9987eb-5886-4587-85c6-5e6350eb4adf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87930, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "几", "is_correct": true, "explanation": "几 jǐ：疑问代词，询问数目，多用于十以内，也可表示不确定的少量。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jǐ（第三声）声调不同，“机”意思是机器。"}, {"text": "集", "is_correct": false, "explanation": "jí（第二声）与 jǐ（第三声）声调不同，“集”意思是集合或集市。"}, {"text": "记", "is_correct": false, "explanation": "jì（第四声）与 jǐ（第三声）声调不同，“记”意思是记住或记录。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jǐ（第三声）声调不同，“鸡”意思是鸡类动物。"}, {"text": "急", "is_correct": false, "explanation": "jí（第二声）与 jǐ（第三声）声调不同，“急”意思是着急。"}], "explanations": {"几": "几 jǐ：疑问代词，询问数目，多用于十以内，也可表示不确定的少量。", "机": "jī（第一声）与 jǐ（第三声）声调不同，“机”意思是机器。", "集": "jí（第二声）与 jǐ（第三声）声调不同，“集”意思是集合或集市。", "记": "jì（第四声）与 jǐ（第三声）声调不同，“记”意思是记住或记录。", "鸡": "jī（第一声）与 jǐ（第三声）声调不同，“鸡”意思是鸡类动物。", "急": "jí（第二声）与 jǐ（第三声）声调不同，“急”意思是着急。"}, "sentence_index": null, "correct_answer": "几"}, "level_3": {"options": [{"text": "几", "is_correct": true, "explanation": "几：疑问代词，询问“你家”有多少口人，与句子的询问语气一致。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是副词，不能放在“有”后作数量成分，“你家有很口人”不通。"}, {"text": "都", "is_correct": false, "explanation": "语法：“都”是副词，不能直接修饰“口人”，“你家有都口人”不通。"}, {"text": "是", "is_correct": false, "explanation": "语法：“是”是动词，不能放在“有”后再接数量结构，“你家有是口人”不通。"}], "explanations": {"几": "几：疑问代词，询问“你家”有多少口人，与句子的询问语气一致。", "很": "语法：“很”是副词，不能放在“有”后作数量成分，“你家有很口人”不通。", "都": "语法：“都”是副词，不能直接修饰“口人”，“你家有都口人”不通。", "是": "语法：“是”是动词，不能放在“有”后再接数量结构，“你家有是口人”不通。"}, "sentence_index": 0, "correct_answer": "几"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我等了他天几。", "explanation": "这里应该用〈几天〉。“几”必须放在“天”之前，“天几”顺序颠倒。"}, {"text": "他一天只喝几的水。", "explanation": "这里应该用〈几杯〉。“几”后面的名词要有量词，水不能直接跟在“几”后。"}, {"text": "我等了他几的天。", "explanation": "这里应该用〈几天〉。“几”表示数目时要直接接量词“天”，“的”打断了数量结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87930, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "几", "is_correct": true, "explanation": "几 jǐ：疑问代词，询问数目，多用于十以内，也可表示不确定的少量。"}, {"text": "季", "is_correct": false, "explanation": "jì（第四声）与 jǐ（第三声）声调不同，“季”意思是季节。"}, {"text": "寄", "is_correct": false, "explanation": "jì（第四声）与 jǐ（第三声）声调不同，“寄”意思是邮寄。"}, {"text": "级", "is_correct": false, "explanation": "jí（第二声）与 jǐ（第三声）声调不同，“级”意思是等级或年级。"}, {"text": "基", "is_correct": false, "explanation": "jī（第一声）与 jǐ（第三声）声调不同，“基”意思是基础。"}, {"text": "击", "is_correct": false, "explanation": "jī（第一声）与 jǐ（第三声）声调不同，“击”意思是打击。"}], "explanations": {"几": "几 jǐ：疑问代词，询问数目，多用于十以内，也可表示不确定的少量。", "季": "jì（第四声）与 jǐ（第三声）声调不同，“季”意思是季节。", "寄": "jì（第四声）与 jǐ（第三声）声调不同，“寄”意思是邮寄。", "级": "jí（第二声）与 jǐ（第三声）声调不同，“级”意思是等级或年级。", "基": "jī（第一声）与 jǐ（第三声）声调不同，“基”意思是基础。", "击": "jī（第一声）与 jǐ（第三声）声调不同，“击”意思是打击。"}, "sentence_index": null, "correct_answer": "几"}, "level_3": {"options": [{"text": "几", "is_correct": true, "explanation": "几：表示不确定的少量天数，与“过……天我们再见面”的时间表达一致。"}, {"text": "也", "is_correct": false, "explanation": "语法：“也”是副词，不能直接修饰“天”，“过也天”不通。"}, {"text": "又", "is_correct": false, "explanation": "语法：“又”是副词，不能直接修饰“天”，“过又天”不通。"}, {"text": "各", "is_correct": false, "explanation": "搭配：“各”需要与“个”等量词同用，不能直接修饰“天”。"}], "explanations": {"几": "几：表示不确定的少量天数，与“过……天我们再见面”的时间表达一致。", "也": "语法：“也”是副词，不能直接修饰“天”，“过也天”不通。", "又": "语法：“又”是副词，不能直接修饰“天”，“过又天”不通。", "各": "搭配：“各”需要与“个”等量词同用，不能直接修饰“天”。"}, "sentence_index": 6, "correct_answer": "几"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几是他的书。", "explanation": "这里应该用〈这几本〉。“这几”单用不能作主语，后面要接量词和名词。"}, {"text": "你今年几的岁了？", "explanation": "这里应该用〈几岁〉。“几”与“岁”之间不能加“的”，否则数量结构不成立。"}, {"text": "这些几人很高兴。", "explanation": "这里应该用〈这几个人〉。“几”不能直接接名词“人”，中间需有量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你们公司有几部门？", "corrected_sentence": "你们公司有几个部门？", "error_description": "错误在于“几”后漏掉了量词“个”，写成“几部门”。询问“几”与名词之间需要量词，应为“几个部门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班一共有个几女生？", "corrected_sentence": "我们班一共有几个女生？", "error_description": "错误在于“几”和“个”的顺序颠倒，写成“个几”。“几”应放在量词“个”之前，正确应为“几个女生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
