INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87931, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公主是国王或皇帝的女儿。", "primary_collocate": null, "pronunciation": "gōng zhǔ", "ipa": "kʊŋ˥ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "公主住在很大的城堡里。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王有一个漂亮的女儿，她是公主。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公主穿着白色的裙子。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公主过生日，国王请了很多客人。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的公主爱上了一个年轻人。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位公主每天都要学习骑马。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王子想和公主一起去花园。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿说她长大后想当公主。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公主很喜欢那只小白猫。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王把公主送到了另一个国家。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "小公主", "label": "复合"}], "register": "中性", "sense_fingerprint": "国王或皇帝的女儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '323a0647-864a-43f9-9cfa-c61cbd356ead') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公主", "is_correct": true, "explanation": "正确。公主是能住在城堡里的人，符合“住在很大的城堡里”的语境。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是机构，不能住在城堡里。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“住在”的主语必须是人或动物，桌子不能充当。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的物质，不能住在城堡里。"}], "explanations": {"公主": "正确。公主是能住在城堡里的人，符合“住在很大的城堡里”的语境。", "公司": "语义：公司是机构，不能住在城堡里。", "桌子": "配价：“住在”的主语必须是人或动物，桌子不能充当。", "空气": "语义：空气是无形的物质，不能住在城堡里。"}, "sentence_index": 0, "correct_answer": "公主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国王的儿子是一位很勇敢的公主。", "explanation": "这里应该用〈王子〉。公主指国王或皇帝的女儿，国王的儿子不能叫公主。"}, {"text": "这位公主的父亲是一个普通的农民。", "explanation": "这里应该用〈姑娘〉。公主指国王或皇帝的女儿，父亲是普通农民就不能称公主。"}, {"text": "那位公主下令修建了长城。", "explanation": "这里应该用〈皇帝〉。下令修建是君主才有的权力，公主不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公主", "is_correct": true, "explanation": "正确。“和……一起去花园”需要能自主行动的人，公主符合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能主动去花园，也不能和王子一起行动。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“和……一起”的对象必须能自主行动，冰箱不能充当。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不能和王子结伴去花园。"}], "explanations": {"公主": "正确。“和……一起去花园”需要能自主行动的人，公主符合。", "石头": "语义：石头不能主动去花园，也不能和王子一起行动。", "冰箱": "配价：“和……一起”的对象必须能自主行动，冰箱不能充当。", "雨": "语义：雨是天气现象，不能和王子结伴去花园。"}, "sentence_index": 6, "correct_answer": "公主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她总让别人伺候，真是个公主。", "explanation": "这里用的是“娇气、爱被伺候的人”的引申义，不是“国王或皇帝的女儿”的本义。"}, {"text": "我在街上遇到了一头公主。", "explanation": "这里应该用〈位〉。公主指人，不能用量词“头”。"}, {"text": "宴会上坐着一条公主。", "explanation": "这里应该用〈位〉。公主指人，不能用量词“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个王国有两只公主。", "corrected_sentence": "那个王国有两位公主。", "error_description": "错误：量词用“只”，说成“两只公主”。正确：应说“两位公主”。“公主”指人，量词应用“位”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只可爱的小公主在花园里玩。", "corrected_sentence": "那位可爱的小公主在花园里玩。", "error_description": "错误：量词用“只”，说成“那只可爱的小公主”。正确：应说“那位可爱的小公主”。“公主”指人，量词应用“位”或“个”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
