INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87933, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "割是用刀把东西切开或切下来。", "primary_collocate": null, "pronunciation": "gē", "ipa": "kɤ˥", "syllable_count": 1, "sentences": [{"text": "农民们正忙着割稻子。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用小刀割下一块布。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶蹲在地上割韭菜。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把镰刀很锋利，一下就割断了草。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去市场割了两斤猪肉。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拿刀的时候小心，别割到手。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每年秋天都要割玉米。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把树上的绳子割开了。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天一起去山上割草吧。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用刀割开了信封。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "割了", "label": "体标"}, {"form": "割着", "label": "体标"}, {"form": "割过", "label": "体标"}, {"form": "割草", "label": "复合"}], "register": "中性", "sense_fingerprint": "割：用刀把东西切开或切下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03c657c1-bea8-4c65-833c-a2de6b45be3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87933, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "割", "is_correct": true, "explanation": "正确答案。割（gē）：用刀把东西切开或切下来。"}, {"text": "喝", "is_correct": false, "explanation": "hē（第一声）与 gē 声母不同（h／g），意思是喝。"}, {"text": "科", "is_correct": false, "explanation": "kē（第一声）与 gē 声母不同（k／g），意思是科目。"}, {"text": "个", "is_correct": false, "explanation": "gè（第四声）与 gē（第一声）声调不同，意思是个。"}, {"text": "格", "is_correct": false, "explanation": "gé（第二声）与 gē 声调不同，意思是格子。"}], "explanations": {"割": "正确答案。割（gē）：用刀把东西切开或切下来。", "喝": "hē（第一声）与 gē 声母不同（h／g），意思是喝。", "科": "kē（第一声）与 gē 声母不同（k／g），意思是科目。", "个": "gè（第四声）与 gē（第一声）声调不同，意思是个。", "格": "gé（第二声）与 gē 声调不同，意思是格子。"}, "sentence_index": null, "correct_answer": "割"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“稻子”作宾语，“忙着唱稻子”不成立。"}, {"text": "割", "is_correct": true, "explanation": "正确答案。“割”指用刀具切下，与“农民们忙着割稻子”相符。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“剪”要用剪刀等工具，不说用镰刀剪稻子。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”是用脚压，与收割稻子的动作不符。"}], "explanations": {"唱": "搭配：“唱”不能带“稻子”作宾语，“忙着唱稻子”不成立。", "割": "正确答案。“割”指用刀具切下，与“农民们忙着割稻子”相符。", "剪": "搭配：“剪”要用剪刀等工具，不说用镰刀剪稻子。", "踩": "语义：“踩”是用脚压，与收割稻子的动作不符。"}, "sentence_index": 0, "correct_answer": "割"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用小刀在木板上割了一朵花。", "explanation": "这里应该用〈刻〉。刻是在物体表面雕出图案，割指切断或切下，不说割花。"}, {"text": "工人用铁铲割出了一个深坑。", "explanation": "这里应该用〈挖〉。挖是掘土成坑，割指用刀等切断或切下，不用于挖坑。"}, {"text": "他用剪刀把头发割短了。", "explanation": "这里应该用〈剪〉。剪是用剪刀裁断，割多指用刀、镰等切断或切下，剪头发要用剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87933, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "割", "is_correct": true, "explanation": "正确答案。割（gē）：用刀把东西切开或切下来。"}, {"text": "根", "is_correct": false, "explanation": "gēn 比 gē 多一个鼻音韵尾 n，意思是根。"}, {"text": "隔", "is_correct": false, "explanation": "gé（第二声）与 gē 声调不同，意思是隔开。"}, {"text": "各", "is_correct": false, "explanation": "gè（第四声）与 gē 声调不同，意思是各自。"}, {"text": "颗", "is_correct": false, "explanation": "kē（第一声）与 gē 声母不同（k／g），量词意思是颗。"}], "explanations": {"割": "正确答案。割（gē）：用刀把东西切开或切下来。", "根": "gēn 比 gē 多一个鼻音韵尾 n，意思是根。", "隔": "gé（第二声）与 gē 声调不同，意思是隔开。", "各": "gè（第四声）与 gē 声调不同，意思是各自。", "颗": "kē（第一声）与 gē 声母不同（k／g），量词意思是颗。"}, "sentence_index": null, "correct_answer": "割"}, "level_3": {"options": [{"text": "劈", "is_correct": false, "explanation": "语义：“劈”是用斧子把木头分开，与收割玉米的动作不符。"}, {"text": "割", "is_correct": true, "explanation": "正确答案。“割”指用刀具切下，与“爷爷每年秋天都要割玉米”相符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹去表面的东西，与割下玉米的动作无关。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”不能带“玉米”作宾语，“都要拍玉米”不成立。"}], "explanations": {"劈": "语义：“劈”是用斧子把木头分开，与收割玉米的动作不符。", "割": "正确答案。“割”指用刀具切下，与“爷爷每年秋天都要割玉米”相符。", "擦": "语义：“擦”是抹去表面的东西，与割下玉米的动作无关。", "拍": "搭配：“拍”不能带“玉米”作宾语，“都要拍玉米”不成立。"}, "sentence_index": 6, "correct_answer": "割"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸用刀割了土豆的皮。", "explanation": "这里应该用〈削〉。削用于去掉表皮，割指切断或切下，不说割皮。"}, {"text": "他用斧子割断了那根木头。", "explanation": "这里应该用〈砍〉。割多用于刀、镰等薄刃工具，用斧子砍断粗木要用砍。"}, {"text": "他用斧头把木柴割开了。", "explanation": "这里应该用〈劈〉。劈是用斧子把木柴分开，割多指用薄刃工具切断或切下，不说割开木柴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶正在院子里割了韭菜。", "corrected_sentence": "奶奶正在院子里割韭菜。", "error_description": "体标错误：“正在”表示动作正在进行，不能与“了”同用。应去掉“了”，说“正在割韭菜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用刀割了开那个纸箱。", "corrected_sentence": "她用刀割开了那个纸箱。", "error_description": "“割了开”错误：“了”不能插在结果补语“开”之前，应说“割开了”，把“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
