INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87934, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用刀等把物体切断或切下。", "primary_collocate": null, "pronunciation": "gē", "ipa": "kɤ˥", "syllable_count": 1, "sentences": [{"text": "爸爸用刀割了一块肉。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民正在地里割麦子。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心割破了手指。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我把绳子割开。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用小刀割下一段绳子。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，爷爷每天早上去割草。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着镰刀割稻子。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀很快，一下就能割断绳子。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给你割一点肉吧。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他割过很多年的麦子。", "target_word": "割", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "割了", "label": "体标"}, {"form": "割着", "label": "体标"}, {"form": "割过", "label": "体标"}, {"form": "割草", "label": "复合"}], "register": "中性", "sense_fingerprint": "割：用刀等把物体切断或切下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03c657c1-bea8-4c65-833c-a2de6b45be3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87934, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "割", "is_correct": true, "explanation": "正确答案。割（gē）：用刀等把物体切断或切下。"}, {"text": "喝", "is_correct": false, "explanation": "hē（第一声）与 gē 声母不同（h／g），意思是喝。"}, {"text": "科", "is_correct": false, "explanation": "kē（第一声）与 gē 声母不同（k／g），意思是科目。"}, {"text": "个", "is_correct": false, "explanation": "gè（第四声）与 gē（第一声）声调不同，意思是个。"}, {"text": "格", "is_correct": false, "explanation": "gé（第二声）与 gē 声调不同，意思是格子。"}], "explanations": {"割": "正确答案。割（gē）：用刀等把物体切断或切下。", "喝": "hē（第一声）与 gē 声母不同（h／g），意思是喝。", "科": "kē（第一声）与 gē 声母不同（k／g），意思是科目。", "个": "gè（第四声）与 gē（第一声）声调不同，意思是个。", "格": "gé（第二声）与 gē 声调不同，意思是格子。"}, "sentence_index": null, "correct_answer": "割"}, "level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热做熟，与用刀切下一块肉的动作不符。"}, {"text": "割", "is_correct": true, "explanation": "正确答案。“割”指用刀把东西切断或切下，与“用刀割了一块肉”相符。"}, {"text": "称", "is_correct": false, "explanation": "搭配：“称”指用秤测重量，不能说“用刀称了一块肉”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛掷，与用刀切下一块肉的动作无关。"}], "explanations": {"煮": "语义：“煮”是加热做熟，与用刀切下一块肉的动作不符。", "割": "正确答案。“割”指用刀把东西切断或切下，与“用刀割了一块肉”相符。", "称": "搭配：“称”指用秤测重量，不能说“用刀称了一块肉”。", "扔": "语义：“扔”是抛掷，与用刀切下一块肉的动作无关。"}, "sentence_index": 0, "correct_answer": "割"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用斧子把那棵大树割倒了。", "explanation": "这里应该用〈砍〉。割多指用刀、镰等薄刃工具切断或切下，用斧子砍倒大树要用砍。"}, {"text": "妈妈用刀割了苹果的皮。", "explanation": "这里应该用〈削〉。去掉果皮要用削，割指切断或切下一部分，不说割皮。"}, {"text": "他用剪刀把头发割短了。", "explanation": "这里应该用〈剪〉。剪是用剪刀裁断，割多指用刀、镰等切断或切下，剪头发要用剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87934, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "割", "is_correct": true, "explanation": "正确答案。割（gē）：用刀等把物体切断或切下。"}, {"text": "根", "is_correct": false, "explanation": "gēn 比 gē 多一个鼻音韵尾 n，意思是根。"}, {"text": "隔", "is_correct": false, "explanation": "gé（第二声）与 gē 声调不同，意思是隔开。"}, {"text": "各", "is_correct": false, "explanation": "gè（第四声）与 gē 声调不同，意思是各自。"}, {"text": "棵", "is_correct": false, "explanation": "kē（第一声）与 gē 声母不同（k／g），量词意思是棵。"}], "explanations": {"割": "正确答案。割（gē）：用刀等把物体切断或切下。", "根": "gēn 比 gē 多一个鼻音韵尾 n，意思是根。", "隔": "gé（第二声）与 gē 声调不同，意思是隔开。", "各": "gè（第四声）与 gē 声调不同，意思是各自。", "棵": "kē（第一声）与 gē 声母不同（k／g），量词意思是棵。"}, "sentence_index": null, "correct_answer": "割"}, "level_3": {"options": [{"text": "剪", "is_correct": false, "explanation": "搭配：“剪”要用剪刀等工具，“拿着镰刀剪稻子”不成立。"}, {"text": "扫", "is_correct": false, "explanation": "语义：“扫”是清扫，与用镰刀割下稻子的动作不符。"}, {"text": "割", "is_correct": true, "explanation": "正确答案。“割”指用刀具切下，与“拿着镰刀割稻子”相符。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”是用脚压，与用镰刀割稻子的动作无关。"}], "explanations": {"剪": "搭配：“剪”要用剪刀等工具，“拿着镰刀剪稻子”不成立。", "扫": "语义：“扫”是清扫，与用镰刀割下稻子的动作不符。", "割": "正确答案。“割”指用刀具切下，与“拿着镰刀割稻子”相符。", "踩": "语义：“踩”是用脚压，与用镰刀割稻子的动作无关。"}, "sentence_index": 6, "correct_answer": "割"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用小刀在木板上割了一个名字。", "explanation": "这里应该用〈刻〉。刻是在物体表面雕出痕迹，割指切断或切下，不说割名字。"}, {"text": "工人用铁铲割了一个大坑。", "explanation": "这里应该用〈挖〉。挖是掘土成坑，割指用刀等切断或切下，不用于挖坑。"}, {"text": "农民用斧头割开了一根木柴。", "explanation": "这里应该用〈劈〉。劈是用斧子把木柴分开，割多指用薄刃工具切断或切下，不说割开木柴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_va