INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把绳子割。", "corrected_sentence": "他把绳子割断。", "error_description": "“把”字句中动词“割”后缺少结果补语。应说“他把绳子割断。”，用“断”表示切断的结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥割了过三次麦子。", "corrected_sentence": "我哥哥割过三次麦子。", "error_description": "“割了过”错误：“了”和“过”不能同时用在动词后。应去掉“了”，说“割过三次麦子”，表示曾经有过的经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
