INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87935, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老生是戏里演年纪大的男人的人。", "primary_collocate": null, "pronunciation": "lǎo shēng", "ipa": "lau˨˩ ʂəŋ˥", "syllable_count": 2, "sentences": [{"text": "京剧里的老生常常演年纪大的男人。", "target_word": "老生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上的老生穿着黑衣服，声音很大。", "target_word": "老生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老生唱了一段有名的京剧。", "target_word": "老生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷最爱看戏，他最喜欢听老生唱。", "target_word": "老生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是剧团里最有名的老生。", "target_word": "老生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学唱戏，先从老生学起。", "target_word": "老生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老生演的是一位老将军。", "target_word": "老生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老生唱得慢，花脸唱得大声。", "target_word": "老生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上我在剧院看了一场老生的戏。", "target_word": "老生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老生的胡子是假的，用线挂在耳朵上。", "target_word": "老生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "戏曲中扮演年纪大的男人的角色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d23fd0e-84cc-4b7b-8d40-c450f027c617') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87935, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老生", "is_correct": true, "explanation": "正确：老生，戏曲中扮演年纪大的男人的角色。"}, {"text": "考生", "is_correct": false, "explanation": "kǎo shēng 与 lǎo shēng 声母不同（k 与 l），意思是参加考试的人。"}, {"text": "老师", "is_correct": false, "explanation": "lǎo shī 与 lǎo shēng 韵母不同（-i 与 -eng），意思是教书的人。"}, {"text": "老僧", "is_correct": false, "explanation": "lǎo sēng 与 lǎo shēng 声母不同（s 与 sh），意思是年老的和尚。"}, {"text": "老伤", "is_correct": false, "explanation": "lǎo shāng 与 lǎo shēng 韵母不同（-ang 与 -eng），意思是旧伤。"}, {"text": "好生", "is_correct": false, "explanation": "hǎo shēng 与 lǎo shēng 声母不同（h 与 l），意思是好好地、仔细地。"}, {"text": "老身", "is_correct": false, "explanation": "lǎo shēn 与 lǎo shēng 韵母不同（-en 与 -eng），意思是老年女子的自称，多见于戏曲。"}], "explanations": {"老生": "正确：老生，戏曲中扮演年纪大的男人的角色。", "考生": "kǎo shēng 与 lǎo shēng 声母不同（k 与 l），意思是参加考试的人。", "老师": "lǎo shī 与 lǎo shēng 韵母不同（-i 与 -eng），意思是教书的人。", "老僧": "lǎo sēng 与 lǎo shēng 声母不同（s 与 sh），意思是年老的和尚。", "老伤": "lǎo shāng 与 lǎo shēng 韵母不同（-ang 与 -eng），意思是旧伤。", "好生": "hǎo shēng 与 lǎo shēng 声母不同（h 与 l），意思是好好地、仔细地。", "老身": "lǎo shēn 与 lǎo shēng 韵母不同（-en 与 -eng），意思是老年女子的自称，多见于戏曲。"}, "sentence_index": null, "correct_answer": "老生"}, "level_3": {"options": [{"text": "老生", "is_correct": true, "explanation": "正确：老生是戏曲中扮演年纪大的男人的角色，能演这类人物。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是看戏的人，不演戏，与“常常演”矛盾。"}, {"text": "钢琴", "is_correct": false, "explanation": "配价：“演”的施事须是能表演的人，钢琴不能充当。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：空调不能演戏，“演年纪大的男人”只说人的表演。"}], "explanations": {"老生": "正确：老生是戏曲中扮演年纪大的男人的角色，能演这类人物。", "观众": "语义：观众是看戏的人，不演戏，与“常常演”矛盾。", "钢琴": "配价：“演”的施事须是能表演的人，钢琴不能充当。", "空调": "搭配：空调不能演戏，“演年纪大的男人”只说人的表演。"}, "sentence_index": 0, "correct_answer": "老生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老生的脸上画满了颜色鲜艳的脸谱。", "explanation": "这里应该用〈花脸〉。老生靠扮相和髯口，不画脸谱，脸谱是花脸的特征。"}, {"text": "老生年轻英俊，唱腔很优美。", "explanation": "这里应该用〈小生〉。老生扮演中老年男子，年轻英俊的男角要用小生。"}, {"text": "老生扮演一位年老的婆婆。", "explanation": "这里应该用〈老旦〉。老生扮演男性角色，年老的婆婆要用老旦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87935, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老生", "is_correct": true, "explanation": "正确：老生是戏曲中扮演中老年男子的角色，演的是老将军这类人物。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所不是人，不会演戏，句意不通。"}, {"text": "台风", "is_correct": false, "explanation": "语义：台风是天气现象，不会演戏，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会演戏，与“演的是一位老将军”矛盾。"}], "explanations": {"老生": "正确：老生是戏曲中扮演中老年男子的角色，演的是老将军这类人物。", "厕所": "语义：厕所不是人，不会演戏，句意不通。", "台风": "语义：台风是天气现象，不会演戏，句意不通。", "石头": "语义：石头不会演戏，与“演的是一位老将军”矛盾。"}, "sentence_index": 6, "correct_answer": "老生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老生穿着凤冠霞帔，十分漂亮。", "explanation": "这里应该用〈旦角〉。凤冠霞帔是女性角色的服饰，老生是男性角色。"}, {"text": "老生的鼻子上抹着一块白粉。", "explanation": "这里应该用〈丑角〉。白鼻子是丑角的化妆特征，老生不这样化妆。"}, {"text": "老生的头上插着一支金钗。", "explanation": "这里应该用〈青衣〉。金钗是女性角色的头饰，老生是男性角色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今晚的戏里有两只老生，他们都唱得很好。", "corrected_sentence": "今晚的戏里有两位老生，他们都唱得很好。", "error_description": "量词错误：老生指人，应用“位”或“个”，“只”用于动物。错在“两只老生”，应为“两位老生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在戏班子里认识了一老生。", "corrected_sentence": "我在戏班子里认识了一位老生。", "error_description": "漏用量词：数词“一”和名词之间要有量词。错在“一老生”，应为“一位老生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87937, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安全", "is_correct": true, "explanation": "安全与“危险”构成反义，指不会受伤或出事，与本义相对。"}, {"text": "简单", "is_correct": false, "explanation": "简单与危险不构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与危险不构成反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹形容人多、声音大，与危险不构成反义关系。"}], "correct_answer": "安全", "explanations": {"安全": "安全与“危险”构成反义，指不会受伤或出事，与本义相对。", "简单": "简单与危险不构成反义关系。", "明亮": "明亮形容光线或颜色，与危险不构成反义关系。", "热闹": "热闹形容人多、声音大，与危险不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87937, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安全", "is_correct": true, "explanation": "安全与“危险”构成反义，指不会受伤或出事，与本义相对。"}, {"text": "容易", "is_correct": false, "explanation": "容易与危险不构成反义关系，容易的反义是困难。"}, {"text": "普通", "is_correct": false, "explanation": "普通与危险不构成反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚与危险不构成反义关系。"}], "correct_answer": "安全", "explanations": {"安全": "安全与“危险”构成反义，指不会受伤或出事，与本义相对。", "容易": "容易与危险不构成反义关系，容易的反义是困难。", "普通": "普通与危险不构成反义关系。", "清楚": "清楚与危险不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87937, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "危险是可能会受伤，或者出事。", "primary_collocate": null, "pronunciation": "wēi xiǎn", "ipa": "wei˥ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "晚上一个人走山路很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子玩火太危险了，会受伤。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别站在车前面，那样很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爬到很高的树上，妈妈说这样危险，叫他下来。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很急，下河游泳非常危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车的时候不戴头盔，这样很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀很快，小孩拿着很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雪的时候开车特别危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做的工作很危险，家人都很担心。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路时一直看手机，非常危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "危险品", "label": "复合"}, {"form": "危险性", "label": "复合"}, {"form": "危險", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做某事可能让人受伤或出事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f824fbd0-5911-4073-b89d-fbb10fb08bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87937, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "危险", "is_correct": true, "explanation": "危险（wēi xiǎn）：可能受伤或出事，是本题的目标词。"}, {"text": "微小", "is_correct": false, "explanation": "xiǎo 与 xiǎn 的韵母不同（o 与 n），意思是微小，不是危险。"}, {"text": "威胁", "is_correct": false, "explanation": "xié 与 xiǎn 的韵母与声调都不同，意思是威胁。"}, {"text": "威信", "is_correct": false, "explanation": "xìn 与 xiǎn 的韵母与声调都不同，意思是威信（威望与信誉）。"}], "explanations": {"危险": "危险（wēi xiǎn）：可能受伤或出事，是本题的目标词。", "微小": "xiǎo 与 xiǎn 的韵母不同（o 与 n），意思是微小，不是危险。", "威胁": "xié 与 xiǎn 的韵母与声调都不同，意思是威胁。", "威信": "xìn 与 xiǎn 的韵母与声调都不同，意思是威信（威望与信誉）。"}, "sentence_index": null, "correct_answer": "危险"}, "level_3": {"options": [{"text": "危险", "is_correct": true, "explanation": "危险：可能受伤或出事，符合晚上一个人走山路的情境。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”形容价格低，不能用来形容晚上走山路这件事。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：热闹指人多、有声音，与“一个人”的情境矛盾。"}, {"text": "热烈", "is_correct": false, "explanation": "搭配：“热烈”多用来形容气氛或情绪，不能修饰走山路这件事。"}], "explanations": {"危险": "危险：可能受伤或出事，符合晚上一个人走山路的情境。", "便宜": "搭配：“便宜”形容价格低，不能用来形容晚上走山路这件事。", "热闹": "语义：热闹指人多、有声音，与“一个人”的情境矛盾。", "热烈": "搭配：“热烈”多用来形容气氛或情绪，不能修饰走山路这件事。"}, "sentence_index": 0, "correct_answer": "危险"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的情节很危险，我一直不敢眨眼。", "explanation": "这里应该用〈惊险〉。危险指可能受伤或出事，不用来形容情节的刺激，形容情节要用惊险。"}, {"text": "这次面试的发型很危险。", "explanation": "这里应该用〈好看〉。危险说的是可能受伤或出事，不能用来形容发型。"}, {"text": "这堂课很危险，同学们都很喜欢。", "explanation": "这里应该用〈有趣〉。危险不能用来形容课堂的趣味，这堂课应说很有趣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87937, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "危险", "is_correct": true, "explanation": "危险（wēi xiǎn）：可能受伤或出事，是本题的目标词。"}, {"text": "微笑", "is_correct": false, "explanation": "xiào 与 xiǎn 的韵母与声调都不同，意思是微笑。"}, {"text": "微信", "is_correct": false, "explanation": "xìn 与 xiǎn 的韵母与声调都不同，意思是微信（社交软件）。"}, {"text": "威严", "is_correct": false, "explanation": "yán 与 xiǎn 的声母与声调都不同，意思是威严。"}], "explanations": {"危险": "危险（wēi xiǎn）：可能受伤或出事，是本题的目标词。", "微笑": "xiào 与 xiǎn 的韵母与声调都不同，意思是微笑。", "微信": "xìn 与 xiǎn 的韵母与声调都不同，意思是微信（社交软件）。", "威严": "yán 与 xiǎn 的声母与声调都不同，意思是威严。"}, "sentence_index": null, "correct_answer": "危险"}, "level_3": {"options": [{"text": "危险", "is_correct": true, "explanation": "危险：可能伤到人，符合刀很快、小孩拿着的情境。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容物体坚固，不能用来形容拿着刀的状态。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容环境或物体含水，与拿刀的情境不搭配。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：冷清指没有人、很安静，与小孩拿着刀的情境不合。"}], "explanations": {"危险": "危险：可能伤到人，符合刀很快、小孩拿着的情境。", "结实": "搭配：“结实”形容物体坚固，不能用来形容拿着刀的状态。", "潮湿": "搭配：“潮湿”形容环境或物体含水，与拿刀的情境不搭配。", "冷清": "语义：冷清指没有人、很安静，与小孩拿着刀的情境不合。"}, "sentence_index": 6, "correct_answer": "危险"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试前他的心里很危险，手心都出汗了。", "explanation": "这里应该用〈紧张〉。危险说的是可能受伤或出事，形容人的心理状态要用紧张，不能说心里很危险。"}, {"text": "他这次比赛的发挥很危险。", "explanation": "这里应该用〈稳定〉。危险说的是可能受伤或出事，形容发挥的好坏要用稳定，不能说发挥很危险。"}, {"text": "这首歌的旋律很危险。", "explanation": "这里应该用〈动听〉。危险说的是可能受伤或出事，不能用来评价旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation