INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河的水流很急，游泳很危险性。", "corrected_sentence": "这条河的水流很急，游泳很危险。", "error_description": "“危险”是形容词，“很”之后不能接名词性的“危险性”；应去掉“性”，说“游泳很危险”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨天的山路很滑，走起来很危险性。", "corrected_sentence": "雨天的山路很滑，走起来很危险。", "error_description": "“危险”是形容词，“很”之后不能接名词性的“危险性”；应说“很危险”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87938, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安全", "is_correct": true, "explanation": "安全与“危险”构成反义，指没有不幸或损害，与本义相对。"}, {"text": "简单", "is_correct": false, "explanation": "简单与危险不构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与危险不构成反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹形容人多、声音大，与危险不构成反义关系。"}], "correct_answer": "安全", "explanations": {"安全": "安全与“危险”构成反义，指没有不幸或损害，与本义相对。", "简单": "简单与危险不构成反义关系。", "明亮": "明亮形容光线或颜色，与危险不构成反义关系。", "热闹": "热闹形容人多、声音大，与危险不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
