INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87938, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有可能发生不幸或受到损害的；不安全。", "primary_collocate": null, "pronunciation": "wēi xiǎn", "ipa": "wei˥ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这座桥坏了，现在过去很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋旧房子随时会倒，住在里面很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上风浪太大，出海很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司欠了很多钱，情况越来越危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病很重，现在的情况很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路没有路灯，天黑后很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在高速路上停车是很危险的。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电线露在外面，摸它很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有很多野兽，没有向导就进去太危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把重要的钱都放在一家公司，这样做很危险。", "target_word": "危险", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "危险品", "label": "复合"}, {"form": "危险性", "label": "复合"}, {"form": "危險", "label": "繁体"}], "register": "中性", "sense_fingerprint": "处境或事物不安全，可能发生不幸或损害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 条路 (Zipf 3.25), 路灯 (Zipf 3.63), 天黑 (Zipf 3.56)']::text[], 'f824fbd0-5911-4073-b89d-fbb10fb08bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87938, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "危险", "is_correct": true, "explanation": "危险（wēi xiǎn）：有可能发生不幸或受到损害，是本题的目标词。"}, {"text": "微小", "is_correct": false, "explanation": "xiǎo 与 xiǎn 的韵母不同（o 与 n），意思是微小，不是危险。"}, {"text": "威胁", "is_correct": false, "explanation": "xié 与 xiǎn 的韵母与声调都不同，意思是威胁。"}, {"text": "威信", "is_correct": false, "explanation": "xìn 与 xiǎn 的韵母与声调都不同，意思是威信（威望与信誉）。"}], "explanations": {"危险": "危险（wēi xiǎn）：有可能发生不幸或受到损害，是本题的目标词。", "微小": "xiǎo 与 xiǎn 的韵母不同（o 与 n），意思是微小，不是危险。", "威胁": "xié 与 xiǎn 的韵母与声调都不同，意思是威胁。", "威信": "xìn 与 xiǎn 的韵母与声调都不同，意思是威信（威望与信誉）。"}, "sentence_index": null, "correct_answer": "危险"}, "level_3": {"options": [{"text": "危险", "is_correct": true, "explanation": "危险：桥坏了，现在过去可能出事，符合句中的情境。"}, {"text": "安全", "is_correct": false, "explanation": "语义：安全与危险意思相反，桥坏了不能说安全。"}, {"text": "热烈", "is_correct": false, "explanation": "搭配：“热烈”多用来形容气氛或情绪，不能修饰过桥这件事。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：热闹指人多、场面活跃，与“桥坏了”的情境不合。"}], "explanations": {"危险": "危险：桥坏了，现在过去可能出事，符合句中的情境。", "安全": "语义：安全与危险意思相反，桥坏了不能说安全。", "热烈": "搭配：“热烈”多用来形容气氛或情绪，不能修饰过桥这件事。", "热闹": "语义：热闹指人多、场面活跃，与“桥坏了”的情境不合。"}, "sentence_index": 0, "correct_answer": "危险"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗的节奏很危险。", "explanation": "这里应该用〈流畅〉。危险说的是处境不安全，不能用来形容诗的节奏。"}, {"text": "这幅画的颜色很危险。", "explanation": "这里应该用〈鲜艳〉。危险说的是处境不安全，不能用来形容颜色。"}, {"text": "他的字写得很危险。", "explanation": "这里应该用〈工整〉。危险不能用来评价字的好坏，字写得整齐要说工整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87938, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "危险", "is_correct": true, "explanation": "危险（wēi xiǎn）：有可能发生不幸或受到损害，是本题的目标词。"}, {"text": "微笑", "is_correct": false, "explanation": "xiào 与 xiǎn 的韵母与声调都不同，意思是微笑。"}, {"text": "微信", "is_correct": false, "explanation": "xìn 与 xiǎn 的韵母与声调都不同，意思是微信（社交软件）。"}, {"text": "威严", "is_correct": false, "explanation": "yán 与 xiǎn 的声母与声调都不同，意思是威严。"}], "explanations": {"危险": "危险（wēi xiǎn）：有可能发生不幸或受到损害，是本题的目标词。", "微笑": "xiào 与 xiǎn 的韵母与声调都不同，意思是微笑。", "微信": "xìn 与 xiǎn 的韵母与声调都不同，意思是微信（社交软件）。", "威严": "yán 与 xiǎn 的声母与声调都不同，意思是威严。"}, "sentence_index": null, "correct_answer": "危险"}, "level_3": {"options": [{"text": "危险", "is_correct": true, "explanation": "危险：高速路上停车可能出事，符合句中的情境。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：轻松指没有压力、不紧张，与高速路上停车的危险情境不合。"}, {"text": "乖巧", "is_correct": false, "explanation": "搭配：“乖巧”形容人的性情或举止，不能用来形容停车这件事。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容态度或待人的情绪，不能修饰停车这件事。"}], "explanations": {"危险": "危险：高速路上停车可能出事，符合句中的情境。", "轻松": "语义：轻松指没有压力、不紧张，与高速路上停车的危险情境不合。", "乖巧": "搭配：“乖巧”形容人的性情或举止，不能用来形容停车这件事。", "热情": "搭配：“热情”形容态度或待人的情绪，不能修饰停车这件事。"}, "sentence_index": 6, "correct_answer": "危险"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听到消息以后，心情很危险。", "explanation": "这里应该用〈平静〉。危险说的是处境或事物不安全，不能用来形容人的心情。"}, {"text": "这份工作很危险，每天只要坐在办公室。", "explanation": "这里应该用〈轻松〉。危险说的是处境不安全，与每天只要坐在办公室的情况不符，这里要说轻松。"}, {"text": "这首歌很危险。", "explanation": "这里应该用〈动听〉。危险不能用来评价歌曲好听与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条旧船已经漏水，出海很危险性。", "corrected_sentence": "这条旧船已经漏水，出海很危险。", "error_description": "“危险”是形容词，“很”之后不能接名词性的“危险性”；应去掉“性”，说“出海很危险”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把全部积蓄借给别人，这样做很危险性。", "corrected_sentence": "他把全部积蓄借给别人，这样做很危险。", "error_description": "“危险”是形容词，“很”之后不能接名词性的“危险性”；应说“很危险”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
