INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87941, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "力气是身体里能搬东西、推东西的劲儿。", "primary_collocate": null, "pronunciation": "lì qi", "ipa": "li⁵¹ tɕʰi", "syllable_count": 2, "sentences": [{"text": "他力气很大，一个人搬起了桌子。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子太重，我没有力气搬。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈花了很大力气才推开门。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑了一个小时，他一点力气也没有了。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩力气小，拿不动这包米。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，我才有力气爬山。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家很累，要花很多力气。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有力气，经常帮邻居搬东西。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用尽力气推车，车还是不动。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，力气没有以前大。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "力气活", "label": "复合"}], "register": "口语", "sense_fingerprint": "身体里能搬、推东西的劲儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43e9cbc-284b-4337-94c6-a22041e14477') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "力气", "is_correct": true, "explanation": "力气是身体里能搬东西、推东西的劲儿。"}, {"text": "离奇", "is_correct": false, "explanation": "lí qí（第二声）与 lì qi（第四声、轻声）声调不同，意思是奇怪、不寻常。"}, {"text": "立起", "is_correct": false, "explanation": "lìqǐ 与 lìqi 第二个音节声调不同，意思是竖立起来。"}, {"text": "栗子", "is_correct": false, "explanation": "zi 与 qi 声母不同（z 与 q），意思是板栗。"}, {"text": "力求", "is_correct": false, "explanation": "qiú 与 qi 韵母不同，意思是竭力追求。"}], "explanations": {"力气": "力气是身体里能搬东西、推东西的劲儿。", "离奇": "lí qí（第二声）与 lì qi（第四声、轻声）声调不同，意思是奇怪、不寻常。", "立起": "lìqǐ 与 lìqi 第二个音节声调不同，意思是竖立起来。", "栗子": "zi 与 qi 声母不同（z 与 q），意思是板栗。", "力求": "qiú 与 qi 韵母不同，意思是竭力追求。"}, "sentence_index": null, "correct_answer": "力气"}, "level_3": {"options": [{"text": "力气", "is_correct": true, "explanation": "力气：“很大”修饰力气，与后句“一个人搬起了桌子”相呼应。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”说长短，不说“很大”。"}, {"text": "价钱", "is_correct": false, "explanation": "搭配：“价钱”说高低，不说“很大”。"}, {"text": "气色", "is_correct": false, "explanation": "搭配：“气色”只说好、差，不说“很大”。"}], "explanations": {"力气": "力气：“很大”修饰力气，与后句“一个人搬起了桌子”相呼应。", "时间": "搭配：“时间”说长短，不说“很大”。", "价钱": "搭配：“价钱”说高低，不说“很大”。", "气色": "搭配：“气色”只说好、差，不说“很大”。"}, "sentence_index": 0, "correct_answer": "力气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在数学上很有力气。", "explanation": "这里应该用〈能力〉。力气指身体的劲儿，不用于数学、技能等方面，应说“有能力”。"}, {"text": "这支球队的力气很强，我们都很有信心。", "explanation": "这里应该用〈实力〉。球队、国家的整体能力说“实力”，力气只指身体的劲儿。"}, {"text": "他对这份工作的力气很大，每天都很努力。", "explanation": "这里应该用〈干劲〉。对工作的热情和积极说“干劲”，力气只指身体的劲儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87941, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力气", "is_correct": true, "explanation": "力气：“花很多”搭配“力气”，表示搬家要付出的体力。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“花”不搭配“眼泪”，应说“流”。"}, {"text": "笑容", "is_correct": false, "explanation": "语义：前句“搬家很累”，后句“笑容”与之矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“花”不搭配“颜色”，颜色不是用“花”来消耗的。"}], "explanations": {"力气": "力气：“花很多”搭配“力气”，表示搬家要付出的体力。", "眼泪": "搭配：“花”不搭配“眼泪”，应说“流”。", "笑容": "语义：前句“搬家很累”，后句“笑容”与之矛盾。", "颜色": "搭配：“花”不搭配“颜色”，颜色不是用“花”来消耗的。"}, "sentence_index": 6, "correct_answer": "力气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药很有力气，吃了就好。", "explanation": "这里应该用〈效果〉。药物的作用说“效果”，力气只指人或动物的体力。"}, {"text": "他的思想很有力气，影响了很多人。", "explanation": "这里应该用〈影响力〉。抽象的作用说“影响力”，力气指身体的劲儿。"}, {"text": "这台发动机的力气很大，每分钟能转很多圈。", "explanation": "这里应该用〈马力〉。机器的动力大小说“马力”，力气只指人或动物的体力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很大力气，能一个人扛起袋子。", "corrected_sentence": "他有很大力气，能一个人扛起袋子。", "error_description": "错误：“力气”前缺少动词“有”。正确：“有很大力气”，“有”用于表示拥有力气。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只剩下一根力气。", "corrected_sentence": "他只剩下一股力气。", "error_description": "错误在量词。“力气”用“股”计量，不用“根”；“根”用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
