INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87942, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人或动物筋肉的力量。", "primary_collocate": null, "pronunciation": "lì qi", "ipa": "li⁵¹ tɕʰi", "syllable_count": 2, "sentences": [{"text": "牛的力气比马还大。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这匹马力气很大，能拉很重的车。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天锻炼，力气越来越大。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象用鼻子举起树，力气真大。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子力气不小，能把我拉过去。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病了三天，我连一点力气都没有。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他力气大得像一头牛。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员的力气比一般人大。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗力气小，拉不动这根绳子。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人没有年轻人的力气。", "target_word": "力气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "力气活", "label": "复合"}], "register": "口语", "sense_fingerprint": "人或动物筋肉的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43e9cbc-284b-4337-94c6-a22041e14477') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "力气", "is_correct": true, "explanation": "力气指人或动物筋肉的力量。"}, {"text": "离奇", "is_correct": false, "explanation": "lí qí（第二声）与 lì qi（第四声、轻声）声调不同，意思是奇怪、不寻常。"}, {"text": "立起", "is_correct": false, "explanation": "lìqǐ 与 lìqi 第二个音节声调不同，意思是竖立起来。"}, {"text": "栗子", "is_correct": false, "explanation": "zi 与 qi 声母不同（z 与 q），意思是板栗。"}, {"text": "力求", "is_correct": false, "explanation": "qiú 与 qi 韵母不同，意思是竭力追求。"}], "explanations": {"力气": "力气指人或动物筋肉的力量。", "离奇": "lí qí（第二声）与 lì qi（第四声、轻声）声调不同，意思是奇怪、不寻常。", "立起": "lìqǐ 与 lìqi 第二个音节声调不同，意思是竖立起来。", "栗子": "zi 与 qi 声母不同（z 与 q），意思是板栗。", "力求": "qiú 与 qi 韵母不同，意思是竭力追求。"}, "sentence_index": null, "correct_answer": "力气"}, "level_3": {"options": [{"text": "力气", "is_correct": true, "explanation": "力气：“牛的……比马还大”指牛的筋肉力量，正确。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“比马还大”来比较。"}, {"text": "价钱", "is_correct": false, "explanation": "搭配：“价钱”说高低，不说“比马还大”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”没有大小之分，不能与牛马比较。"}], "explanations": {"力气": "力气：“牛的……比马还大”指牛的筋肉力量，正确。", "颜色": "搭配：“颜色”不能用“比马还大”来比较。", "价钱": "搭配：“价钱”说高低，不说“比马还大”。", "名字": "语义：“名字”没有大小之分，不能与牛马比较。"}, "sentence_index": 0, "correct_answer": "力气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在设计方面很有力气。", "explanation": "这里应该用〈能力〉。力气指身体的劲儿，不用于设计等技能，应说“有能力”。"}, {"text": "这座桥的力气很大，能承受很重的车。", "explanation": "这里应该用〈承载能力〉。桥梁能承受的重量说“承载能力”，力气指人或动物的筋肉。"}, {"text": "这个水库的力气很大，能发很多电。", "explanation": "这里应该用〈水力〉。水流的推动力说“水力”，力气指人或动物的筋肉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力气", "is_correct": true, "explanation": "力气：“他……大得像一头牛”描述的是体力，正确。"}, {"text": "路程", "is_correct": false, "explanation": "搭配：“路程”说长短、远近，不说“大得像一头牛”。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”说长短，不说“大得像一头牛”。"}, {"text": "书", "is_correct": false, "explanation": "语义：“他书大得像一头牛”不通，“书”不是人身上的力量，不能这样描述。"}], "explanations": {"力气": "力气：“他……大得像一头牛”描述的是体力，正确。", "路程": "搭配：“路程”说长短、远近，不说“大得像一头牛”。", "时间": "搭配：“时间”说长短，不说“大得像一头牛”。", "书": "语义：“他书大得像一头牛”不通，“书”不是人身上的力量，不能这样描述。"}, "sentence_index": 6, "correct_answer": "力气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电池里储存着很多力气，能让手机用一天。", "explanation": "这里应该用〈能量〉。力气指人或动物肌肉的力量，电池储存的是能量。"}, {"text": "这位老人的力气很大，一生气就骂人。", "explanation": "这里应该用〈脾气〉。一生气就骂人、性情好坏说“脾气”，力气指身体的力量。"}, {"text": "这是公司发展的力气。", "explanation": "这里应该用〈动力〉。推动发展的作用说“动力”，力气只指身体的力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那匹马有一头力气，能拉动大车。", "corrected_sentence": "那匹马有一股力气，能拉动大车。", "error_description": "错误在量词。“力气”用“股”计量，不用“头”；“头”用于牛、猪等动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他花了很大地力气才把车推上坡。", "corrected_sentence": "他花了很大力气才把车推上坡。", "error_description": "错误：“很大”修饰“力气”时不能插入“地”（“地”只用于修饰动词的状语）。正确：“很大力气”或“很大的力气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
