INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用绳子做了一只圈，挂在门上。", "corrected_sentence": "他用绳子做了一个圈，挂在门上。", "error_description": "错误：“一只圈”的量词“只”用错，应为“一个圈”。“只”多用于动物或成对物品中的一个，圆圈要用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
