INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87949, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "肌肤是我们身体外面的那一层皮。", "primary_collocate": null, "pronunciation": "jī fū", "ipa": "tɕi˥ fu˥", "syllable_count": 2, "sentences": [{"text": "冬天天气很干，我的肌肤总是觉得紧。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，夏天出门要保护好肌肤。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的肌肤很白，像雪一样。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳太大了，晒得我的肌肤又红又疼。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿的肌肤很软，要小心照顾。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水对肌肤很好，用完以后不干。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海风吹过脸上，肌肤感到一阵凉。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，她的肌肤有点过敏。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海边住了很多年，肌肤是深色的。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完澡后，我在肌肤上涂了一点护肤霜。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "身体最外面的一层皮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d23fd0e-84cc-4b7b-8d40-c450f027c617') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肌肤", "is_correct": true, "explanation": "肌肤：身体外面的皮，冬天干燥后会觉得紧，与语境相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能觉得紧，主语须是身体部位。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑没有身体感觉，不能说觉得紧。"}, {"text": "玉体", "is_correct": false, "explanation": "语域：玉体是敬称或文言，不用于这类日常描述。"}], "explanations": {"肌肤": "肌肤：身体外面的皮，冬天干燥后会觉得紧，与语境相符。", "天空": "语义：天空不能觉得紧，主语须是身体部位。", "电脑": "语义：电脑没有身体感觉，不能说觉得紧。", "玉体": "语域：玉体是敬称或文言，不用于这类日常描述。"}, "sentence_index": 0, "correct_answer": "肌肤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的肌肤太长了，该去理发了。", "explanation": "这里应该用〈头发〉。头发长了才要理发，肌肤不会长长。"}, {"text": "我的书包的肌肤破了一个洞，要换一个新的。", "explanation": "这里应该用〈外层〉。肌肤指人身上的皮，书包的外层不能叫肌肤。"}, {"text": "这台机器的肌肤有一道裂缝，要修理了。", "explanation": "肌肤只用于人或动物的身体，机器外壳要说外壳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肌肤", "is_correct": true, "explanation": "肌肤：人身上的皮肤，能感到风吹过的凉，与“海风吹过脸上”相符。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，没有身体感觉，不能感到凉。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是书，不能感到一阵凉。"}, {"text": "皮囊", "is_correct": false, "explanation": "语域：皮囊是文学色彩很浓的说法，与这句日常描述不合。"}], "explanations": {"肌肤": "肌肤：人身上的皮肤，能感到风吹过的凉，与“海风吹过脸上”相符。", "地铁": "语义：地铁是交通工具，没有身体感觉，不能感到凉。", "词典": "语义：词典是书，不能感到一阵凉。", "皮囊": "语域：皮囊是文学色彩很浓的说法，与这句日常描述不合。"}, "sentence_index": 6, "correct_answer": "肌肤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸上有一条肌肤，很干燥。", "explanation": "这里“肌肤”的量词〈条〉用于细长的东西，表示一层皮要用〈层〉。"}, {"text": "这个苹果的肌肤破了一个洞，已经烂了。", "explanation": "这里应该用〈果皮〉。肌肤只指人身上的皮肤，苹果的外皮不能叫肌肤。"}, {"text": "这个孩子的肌肤太长了，应该剪一剪。", "explanation": "这里应该用〈指甲〉。指甲长了要剪，肌肤不会长长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我脸上有一只肌肤晒伤了。", "corrected_sentence": "我脸上有一层肌肤晒伤了。", "error_description": "“肌肤”的量词用错：应说“一层肌肤”，不用“一只”（“只”用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "婴儿的肌肤非常很软。", "corrected_sentence": "婴儿的肌肤非常软。", "error_description": "程度副词重复：“非常”和“很”不能连用，应说“肌肤非常软”或“肌肤很软”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
