INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人的皮肤和肌肉；多指皮肤。", "primary_collocate": null, "pronunciation": "jī fū", "ipa": "tɕi˥ fu˥", "syllable_count": 2, "sentences": [{"text": "他每天跑步，肌肤有光泽，身体也很健康。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷风吹在肌肤上，像小刀一样。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手轻轻摸了摸孩子的肌肤。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服很软，贴着肌肤很舒服。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气热，汗水从肌肤上流下来。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受了伤，肌肤上有一道红印。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的肌肤变得很薄，也很干。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天喝水，所以肌肤很好。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水落在肌肤上，凉凉的。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边玩了一天，肌肤都黑了。", "target_word": "肌肤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人体的皮肤和肌肉，多指皮肤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d23fd0e-84cc-4b7b-8d40-c450f027c617') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肌肤", "is_correct": true, "explanation": "肌肤：人的皮肤和肌肉，跑步后有光泽，与“身体也很健康”相符。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不能有光泽。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是书，不会因跑步而有光泽。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是电器，不是身体部位，说不出跑步后的光泽。"}], "explanations": {"肌肤": "肌肤：人的皮肤和肌肉，跑步后有光泽，与“身体也很健康”相符。", "数学": "语义：数学是学科，不能有光泽。", "词典": "语义：词典是书，不会因跑步而有光泽。", "电视": "语义：电视是电器，不是身体部位，说不出跑步后的光泽。"}, "sentence_index": 0, "correct_answer": "肌肤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的背上有一颗肌肤被晒伤了。", "explanation": "〈颗〉用于小而圆的东西，不能用来数一层皮肤，这里应说〈层〉。"}, {"text": "这块木头的肌肤很光滑，摸起来很舒服。", "explanation": "肌肤指人或动物的皮肉，木头的表面要说表面，不能说肌肤。"}, {"text": "她的肌肤越来越长，快要盖住眼睛了。", "explanation": "这里应该用〈头发〉。头发长长会盖住眼睛，肌肤不会长长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肌肤", "is_correct": true, "explanation": "肌肤：人的皮肤，老人的皮肤变薄变干，与语境相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不会变薄变干，主语须是人的身体。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不会变薄变干。"}, {"text": "玉体", "is_correct": false, "explanation": "语域：玉体是敬称或文言，与这句日常描述不合。"}], "explanations": {"肌肤": "肌肤：人的皮肤，老人的皮肤变薄变干，与语境相符。", "天空": "语义：天空不会变薄变干，主语须是人的身体。", "地铁": "语义：地铁是交通工具，不会变薄变干。", "玉体": "语域：玉体是敬称或文言，与这句日常描述不合。"}, "sentence_index": 6, "correct_answer": "肌肤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子的肌肤被划破了一道口子。", "explanation": "肌肤只指人或动物身上的皮肉，桌面要说表面。"}, {"text": "他的肌肤又长又硬，每次都要用剪刀剪。", "explanation": "这里应该用〈指甲〉。指甲长了要剪，肌肤不会长长。"}, {"text": "这朵花的肌肤开得很美，很多人来看。", "explanation": "这里应该用〈花瓣〉。肌肤指人或动物身上的皮肉，花的外层要说花瓣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "太阳把他的肌肤晒很黑。", "corrected_sentence": "太阳把他的肌肤晒得很黑。", "error_description": "程度补语缺少“得”：应说“晒得很黑”，不能直接说“晒很黑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她脸上有一个薄薄的肌肤。", "corrected_sentence": "她脸上有一层薄薄的肌肤。", "error_description": "“肌肤”的量词用错：应说“一层肌肤”，不用“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
