INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学术", "is_correct": true, "explanation": "正确：“做学术”指从事学问研究，与“要诚实”相配。"}, {"text": "夜间", "is_correct": false, "explanation": "语义：“夜间”与“诚实”和“抄别人的”的语境无关，句子不通。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：“扫帚”不是可以做的事情，句子不通。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语，与“做学术要诚实”的书面语域不合。"}], "explanations": {"学术": "正确：“做学术”指从事学问研究，与“要诚实”相配。", "夜间": "语义：“夜间”与“诚实”和“抄别人的”的语境无关，句子不通。", "扫帚": "语义：“扫帚”不是可以做的事情，句子不通。", "八卦": "语域：“八卦”是口语，与“做学术要诚实”的书面语域不合。"}, "sentence_index": 6, "correct_answer": "学术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们请了一位学术来上课。", "explanation": "这里应该用〈老师〉。学术指学问，不指人。"}, {"text": "他每天都去学术。", "explanation": "这里应该用〈学校〉。学术指学问，不指地点，他去的是学校。"}, {"text": "他从书架上拿下来一张学术。", "explanation": "这里应该用〈论文〉。学术指学问，是抽象的，不能拿在手里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在学术很有成就。", "corrected_sentence": "她在学术上很有成就。", "error_description": "错误：“在学术”后缺少“上”。表示在某方面要说“在学术上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位学术团体很有名。", "corrected_sentence": "这个学术团体很有名。", "error_description": "错误在量词“位”。“位”用于人；学术团体是组织，应该用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
