INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87955, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "原油是从地下挖出来、还没有加工过的油。", "primary_collocate": null, "pronunciation": "yuán yóu", "ipa": "ɥɛn˧˥ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这桶原油是从地下挖出来的。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原油不能直接放进汽车里。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把原油送到工厂去加工。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原油又黑又黏，味道很重。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有很多原油。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原油要先加工，才能变成汽油。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那根长管子是用来运原油的。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上装满了原油。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原油洒在海面上，鱼都死了。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂每天要用一百吨原油。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "桶", "label": "量词"}, {"form": "吨", "label": "量词"}, {"form": "原油价格", "label": "复合"}], "register": "中性", "sense_fingerprint": "从地下挖出来、没有加工过的油", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43e9cbc-284b-4337-94c6-a22041e14477') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽油", "is_correct": false, "explanation": "语义：汽油是原油加工后的成品，不是从地下直接挖出来的。"}, {"text": "原油", "is_correct": true, "explanation": "原油是从地下挖出来、未经加工的油，与句中“从地下挖出来的”相符。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶来自牲畜，不是从地下挖出来的。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是从地下挖出来的，也不用“桶”来量。"}], "explanations": {"汽油": "语义：汽油是原油加工后的成品，不是从地下直接挖出来的。", "原油": "原油是从地下挖出来、未经加工的油，与句中“从地下挖出来的”相符。", "牛奶": "语义：牛奶来自牲畜，不是从地下挖出来的。", "空气": "语义：空气不是从地下挖出来的，也不用“桶”来量。"}, "sentence_index": 0, "correct_answer": "原油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶原油已经过滤、精炼，可以直接用在发动机上。", "explanation": "这里应该用〈成品油〉。原油是未加工的，不能说它已经过滤、精炼过。"}, {"text": "这批原油纯度很高，可以直接加进油箱当汽油用。", "explanation": "这里应该用〈汽油〉。原油未经加工，不能直接当汽油用。"}, {"text": "这批原油已经分装成瓶，等着上架出售。", "explanation": "这里应该用〈柴油〉。原油没有加工，不能直接分装成瓶上架出售。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行李", "is_correct": false, "explanation": "语义：长管子不能用来运行李。"}, {"text": "原油", "is_correct": true, "explanation": "原油是可以用管道输送的液体，与句意相符。"}, {"text": "砖头", "is_correct": false, "explanation": "搭配：管道只能输送液体或气体，“砖头”是固体，不与“用管子运”搭配。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材是固体，不能用长管子输送。"}], "explanations": {"行李": "语义：长管子不能用来运行李。", "原油": "原油是可以用管道输送的液体，与句意相符。", "砖头": "搭配：管道只能输送液体或气体，“砖头”是固体，不与“用管子运”搭配。", "木材": "语义：木材是固体，不能用长管子输送。"}, "sentence_index": 6, "correct_answer": "原油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "加油站里卖的都是原油，可以直接加进汽车。", "explanation": "这里应该用〈汽油〉。原油没有加工，加油站卖的、汽车用的是汽油。"}, {"text": "妈妈每天用原油炒菜。", "explanation": "这里应该用〈食用油〉。原油不能吃，炒菜用的是食用油。"}, {"text": "这瓶原油是炼油厂刚做好的成品。", "explanation": "这里应该用〈成品油〉。原油是炼油厂的原料，不是加工后的成品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂运来了三个原油。", "corrected_sentence": "工厂运来了三吨原油。", "error_description": "错误：“三个原油”；正确：“三吨原油”。原油是液体，应用“吨”或“桶”计量，不能用通用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管道把一只原油送到海边了。", "corrected_sentence": "管道把一吨原油送到海边了。", "error_description": "错误：“一只原油”；正确：“一吨原油”。原油是液体，应用“吨”或“桶”计量，“只”不能用来量原油。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
