INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87956, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从地下开采出来、未经加工的石油。", "primary_collocate": null, "pronunciation": "yuán yóu", "ipa": "ɥɛn˧˥ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这个油田每年开采大量原油。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原油价格最近涨了不少。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国从国外进口了很多原油。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原油经过加工，可以做成汽油和柴油。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门卖原油。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原油的价格影响很多国家的经济。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上钻井平台每天生产原油。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原油没有加工，不能直接使用。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际市场上的原油价格上个月下降了。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条管道把原油运到海边。", "target_word": "原油", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "桶", "label": "量词"}, {"form": "吨", "label": "量词"}, {"form": "原油价格", "label": "复合"}], "register": "中性", "sense_fingerprint": "开采出来、未经加工的石油，作为能源商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43e9cbc-284b-4337-94c6-a22041e14477') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽油", "is_correct": false, "explanation": "语义：汽油是加工后的成品，不能说“开采”。"}, {"text": "原油", "is_correct": true, "explanation": "原油是从地下开采出来的，与“开采大量”搭配，符合句意。"}, {"text": "玉米", "is_correct": false, "explanation": "搭配：“开采”一般用于矿产、石油等，不说“开采玉米”。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶不是矿产资源，不能从油田开采。"}], "explanations": {"汽油": "语义：汽油是加工后的成品，不能说“开采”。", "原油": "原油是从地下开采出来的，与“开采大量”搭配，符合句意。", "玉米": "搭配：“开采”一般用于矿产、石油等，不说“开采玉米”。", "牛奶": "语义：牛奶不是矿产资源，不能从油田开采。"}, "sentence_index": 0, "correct_answer": "原油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批原油已经提炼好了，可以直接装车运走。", "explanation": "这里应该用〈成品油〉。原油还没有加工，不能说它已经提炼好了。"}, {"text": "加油站的原油都是从炼油厂运来的。", "explanation": "这里应该用〈汽油〉。原油是炼油厂的原料，不会从炼油厂运到加油站。"}, {"text": "我们每天在厨房里用原油炒菜。", "explanation": "这里应该用〈食用油〉。原油不可食用，不能用来炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面包", "is_correct": false, "explanation": "语义：海上钻井平台不生产面包，句意不通。"}, {"text": "原油", "is_correct": true, "explanation": "原油是钻井平台生产的产品，与句意相符。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：海上钻井平台生产的是油气，不说“生产钢铁”。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉是农作物，不是钻井平台的产品。"}], "explanations": {"面包": "语义：海上钻井平台不生产面包，句意不通。", "原油": "原油是钻井平台生产的产品，与句意相符。", "钢铁": "搭配：海上钻井平台生产的是油气，不说“生产钢铁”。", "香蕉": "语义：香蕉是农作物，不是钻井平台的产品。"}, "sentence_index": 6, "correct_answer": "原油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "加油站里卖的都是原油。", "explanation": "这里应该用〈汽油〉。原油要先加工，加油站卖的是汽油。"}, {"text": "这瓶原油是用花生榨出来的。", "explanation": "这里应该用〈花生油〉。原油是从地下开采的石油，不是用花生榨的。"}, {"text": "这桶原油已经精炼好，可以直接给飞机加油。", "explanation": "这里应该用〈成品油〉。原油未经加工，不能直接给飞机用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "油田送来了两个原油。", "corrected_sentence": "油田送来了两桶原油。", "error_description": "错误：“两个原油”；正确：“两桶原油”。原油是液体，应用“桶”或“吨”计量，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "油轮把原油运了到码头。", "corrected_sentence": "油轮把原油运到了码头。", "error_description": "错误：“运了到”；正确：“运到了”。结果补语“到”要紧跟动词，“了”放在补语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
