INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87957, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "膜是很薄很薄的一层东西，盖在别的东西上面。", "primary_collocate": null, "pronunciation": "mó", "ipa": "mwo˧˥", "syllable_count": 1, "sentences": [{"text": "热牛奶凉了以后，上面会结一层膜。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新买的手机屏幕上有一层膜，先撕掉吧。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豆浆放了一会儿，表面起了一层膜。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户上贴了一层膜，外面看不见里面。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油漆干了以后，墙上会形成一层膜。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小心地把膜贴在屏幕上。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这层膜太薄了，一碰就破。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子外面的膜撕下来了吗？", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤凉了，上面结着一层白色的膜。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布外面涂着一层膜，雨水进不去。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层膜", "label": "量词"}, {"form": "一张膜", "label": "量词"}, {"form": "薄膜", "label": "复合词"}, {"form": "保鲜膜", "label": "复合词"}], "register": "中性", "sense_fingerprint": "盖在物体表面的很薄的一层东西（日常生活）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87957, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "膜", "is_correct": true, "explanation": "正确：膜指盖在物体表面的很薄的一层东西。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 mó（第二声）声调不同，意思是用手触碰。"}, {"text": "墨", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是墨水。"}, {"text": "抹", "is_correct": false, "explanation": "mǒ（第三声）与 mó（第二声）声调不同，意思是擦、涂。"}, {"text": "默", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是沉默。"}], "explanations": {"膜": "正确：膜指盖在物体表面的很薄的一层东西。", "摸": "mō（第一声）与 mó（第二声）声调不同，意思是用手触碰。", "墨": "mò（第四声）与 mó（第二声）声调不同，意思是墨水。", "抹": "mǒ（第三声）与 mó（第二声）声调不同，意思是擦、涂。", "默": "mò（第四声）与 mó（第二声）声调不同，意思是沉默。"}, "sentence_index": null, "correct_answer": "膜"}, "level_3": {"options": [{"text": "膜", "is_correct": true, "explanation": "正确：膜指盖在物体表面的很薄一层，热牛奶凉后表面会结这样一层。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“结”用于膜、皮、霜、冰等凝结的薄层，水不会在牛奶表面结成一层。"}, {"text": "灰", "is_correct": false, "explanation": "搭配：灰一般说“落”或“积”，不说“结”。"}, {"text": "雾", "is_correct": false, "explanation": "语义：雾是空气中的水汽，不会在热牛奶表面结成一层薄膜。"}], "explanations": {"膜": "正确：膜指盖在物体表面的很薄一层，热牛奶凉后表面会结这样一层。", "水": "搭配：“结”用于膜、皮、霜、冰等凝结的薄层，水不会在牛奶表面结成一层。", "灰": "搭配：灰一般说“落”或“积”，不说“结”。", "雾": "语义：雾是空气中的水汽，不会在热牛奶表面结成一层薄膜。"}, "sentence_index": 0, "correct_answer": "膜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "西瓜的膜很厚，削起来很费劲。", "explanation": "这里应该用〈皮〉。膜指覆盖在物体表面的薄层，西瓜外面厚实的表皮要说皮。"}, {"text": "下雪了，地上铺了厚厚的一层膜。", "explanation": "这里应该用〈雪〉。膜是很薄的一层东西，厚厚地铺在地上的应是雪。"}, {"text": "他用一层膜擦干净了桌子。", "explanation": "这里应该用〈抹布〉。擦桌子要用抹布，膜是覆盖在表面的薄层，不能用来擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87957, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "膜", "is_correct": true, "explanation": "正确：膜指盖在物体表面的很薄的一层东西。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 mó（第二声）声调不同，意思是用手触碰。"}, {"text": "末", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是末尾。"}, {"text": "沫", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是泡沫。"}, {"text": "漠", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是沙漠。"}], "explanations": {"膜": "正确：膜指盖在物体表面的很薄的一层东西。", "摸": "mō（第一声）与 mó（第二声）声调不同，意思是用手触碰。", "末": "mò（第四声）与 mó（第二声）声调不同，意思是末尾。", "沫": "mò（第四声）与 mó（第二声）声调不同，意思是泡沫。", "漠": "mò（第四声）与 mó（第二声）声调不同，意思是沙漠。"}, "sentence_index": null, "correct_answer": "膜"}, "level_3": {"options": [{"text": "膜", "is_correct": true, "explanation": "正确：这层膜太薄，一碰就破，说的是盖在表面的薄片。"}, {"text": "光", "is_correct": false, "explanation": "语义：光不会“太薄”或“一碰就破”，与句子的意思不符。"}, {"text": "盒", "is_correct": false, "explanation": "搭配：“层”用于量平面的薄片，盒子是有形的容器，不说“这层盒”。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不是薄片，“太薄”“一碰就破”说的都不是房间。"}], "explanations": {"膜": "正确：这层膜太薄，一碰就破，说的是盖在表面的薄片。", "光": "语义：光不会“太薄”或“一碰就破”，与句子的意思不符。", "盒": "搭配：“层”用于量平面的薄片，盒子是有形的容器，不说“这层盒”。", "房间": "语义：房间不是薄片，“太薄”“一碰就破”说的都不是房间。"}, "sentence_index": 6, "correct_answer": "膜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用一层膜把木桌擦得很亮。", "explanation": "这里应该用〈蜡〉。擦亮木桌要靠蜡之类的材料，膜是覆盖在表面的薄层，不能用来擦。"}, {"text": "他一口气喝光了一层膜。", "explanation": "这里应该用〈汤〉。膜是覆盖在表面的薄层，不能喝，喝光的应是汤。"}, {"text": "妈妈给孩子穿上了一层膜，让他去上学。", "explanation": "这里应该用〈衣服〉。膜是覆盖在表面的薄层，穿在身上的应是衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "煮过的牛奶放凉后，表面会结一颗膜。", "corrected_sentence": "煮过的牛奶放凉后，表面会结一层膜。", "error_description": "量词错误。“颗”用于颗粒状的东西，膜是薄片，应说“一层膜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗户上的膜撕下了来吗？", "corrected_sentence": "窗户上的膜撕下来了吗？", "error_description": "补语错误。“撕下来”是一个补语结构，“了”要放在“来”之后，不能插在“下”和“来”之间，应说“撕下来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
