INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生物体内的薄层组织，或科学、医学上用来覆盖、过滤的人工薄片。", "primary_collocate": null, "pronunciation": "mó", "ipa": "mwo˧˥", "syllable_count": 1, "sentences": [{"text": "鸡蛋壳里面有一层很薄的膜。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洋葱外面有一层膜，要先撕掉。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细胞外面包着一层膜，保护里面的东西。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家做出了一种膜，能把海水变成淡水。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种膜能让水通过，却能挡住脏东西。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肠子里面有一层膜，保护着身体。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肺里有一层很薄的膜，氧气就是通过它进入血液的。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋壳里的膜可以用来做实验。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛外面有一层透明的膜，保护着眼球。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用一层特别的膜盖住了伤口。", "target_word": "膜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层膜", "label": "量词"}, {"form": "一片膜", "label": "量词"}, {"form": "细胞膜", "label": "复合词"}, {"form": "耳膜", "label": "复合词"}, {"form": "薄膜", "label": "复合词"}], "register": "中性", "sense_fingerprint": "生物体内的薄层组织或科学医学用途的人工薄片（生物、科学、医学）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87958, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "膜", "is_correct": true, "explanation": "正确：膜指生物体内或物体表面的薄层组织或薄片。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 mó（第二声）声调不同，意思是用手触碰。"}, {"text": "末", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是末尾。"}, {"text": "沫", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是泡沫。"}, {"text": "漠", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是沙漠。"}], "explanations": {"膜": "正确：膜指生物体内或物体表面的薄层组织或薄片。", "摸": "mō（第一声）与 mó（第二声）声调不同，意思是用手触碰。", "末": "mò（第四声）与 mó（第二声）声调不同，意思是末尾。", "沫": "mò（第四声）与 mó（第二声）声调不同，意思是泡沫。", "漠": "mò（第四声）与 mó（第二声）声调不同，意思是沙漠。"}, "sentence_index": null, "correct_answer": "膜"}, "level_3": {"options": [{"text": "膜", "is_correct": true, "explanation": "正确：鸡蛋壳内侧那一层很薄的组织就是膜。"}, {"text": "壳", "is_correct": false, "explanation": "语义：壳在蛋的外面，不在壳里面，句子说的是壳里面的薄层。"}, {"text": "蛋黄", "is_correct": false, "explanation": "语义：蛋黄是蛋内的内容物，不是一层很薄的薄片。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“层”不用来量书，书也不会是一层很薄的东西。"}], "explanations": {"膜": "正确：鸡蛋壳内侧那一层很薄的组织就是膜。", "壳": "语义：壳在蛋的外面，不在壳里面，句子说的是壳里面的薄层。", "蛋黄": "语义：蛋黄是蛋内的内容物，不是一层很薄的薄片。", "书": "搭配：“层”不用来量书，书也不会是一层很薄的东西。"}, "sentence_index": 0, "correct_answer": "膜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块岩石的中间夹了一层膜，很厚。", "explanation": "这里应该用〈岩层〉。膜指生物组织或覆盖物的薄片，岩石中间成层的地质结构要说岩层。"}, {"text": "人身上最硬的膜是牙齿。", "explanation": "这里应该用〈部分〉之类的说法。膜是很薄、柔软的组织，牙齿坚硬，不是膜。"}, {"text": "鸡蛋的膜很硬，一敲就碎。", "explanation": "这里应该用〈壳〉。膜很薄、柔软，坚硬、一敲就碎的外层要说壳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87958, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "膜", "is_correct": true, "explanation": "正确：膜指生物体内或物体表面的薄层组织或薄片。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 mó（第二声）声调不同，意思是用手触碰。"}, {"text": "墨", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是墨水。"}, {"text": "抹", "is_correct": false, "explanation": "mǒ（第三声）与 mó（第二声）声调不同，意思是擦、涂。"}, {"text": "默", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是沉默。"}], "explanations": {"膜": "正确：膜指生物体内或物体表面的薄层组织或薄片。", "摸": "mō（第一声）与 mó（第二声）声调不同，意思是用手触碰。", "墨": "mò（第四声）与 mó（第二声）声调不同，意思是墨水。", "抹": "mǒ（第三声）与 mó（第二声）声调不同，意思是擦、涂。", "默": "mò（第四声）与 mó（第二声）声调不同，意思是沉默。"}, "sentence_index": null, "correct_answer": "膜"}, "level_3": {"options": [{"text": "膜", "is_correct": true, "explanation": "正确：肺里那层很薄的组织就是膜，氧气通过它进入血液。"}, {"text": "纸", "is_correct": false, "explanation": "语义：肺里没有纸，纸也不能让氧气通过，与句子的生理意思不符。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰是水冻结成的固体，肺里不会有冰，与句子的意思不符。"}, {"text": "壳", "is_correct": false, "explanation": "语义：壳是坚硬的外层，不是很薄的柔软组织，也不能让氧气通过。"}], "explanations": {"膜": "正确：肺里那层很薄的组织就是膜，氧气通过它进入血液。", "纸": "语义：肺里没有纸，纸也不能让氧气通过，与句子的生理意思不符。", "冰": "语义：冰是水冻结成的固体，肺里不会有冰，与句子的意思不符。", "壳": "语义：壳是坚硬的外层，不是很薄的柔软组织，也不能让氧气通过。"}, "sentence_index": 6, "correct_answer": "膜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树的膜很厚，要用刀削掉。", "explanation": "这里应该用〈树皮〉。膜是覆盖物的薄层，树木外面粗厚的表皮要说树皮。"}, {"text": "医生用一块膜擦干了伤口。", "explanation": "这里应该用〈棉布〉。膜是覆盖在表面的薄片，擦拭伤口要用棉布，膜不用来擦。"}, {"text": "医生让病人把一层膜喝了下去。", "explanation": "这里应该用〈药水〉。膜是薄片，不能喝，喝下去的应是药水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鸡蛋壳内侧贴着一层很薄膜。", "corrected_sentence": "鸡蛋壳内侧贴着一层很薄的膜。", "error_description": "“很薄膜”漏了“的”。形容词修饰名词时要说“很薄的膜”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生用一层特别的膜了敷在伤口上。", "corrected_sentence": "医生用一层特别的膜敷在伤口上。", "error_description": "“了”放错了位置。“了”不能插在名词“膜”和动词“敷”之间，此句不需要“了”，应说“敷在伤口上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
