INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87962, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用计策使敌方内部互相猜疑、不和。", "primary_collocate": null, "pronunciation": "fǎn jiàn", "ipa": "fan˨˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "将军想用假信反间敌人。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定反间对方的两个大将。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王用一封假信反间了敌国的两位谋臣。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法反间敌人，让他们互相怀疑。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想反间敌军，就写了一封假信。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方正在反间我们，大家要小心。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用金子反间敌人的将军。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军师说：“我们可以反间他们。”", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要反间敌国的两位大臣，让他们互相猜疑。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上有人用美女反间过敌人的大臣。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反间了", "label": "体标"}, {"form": "反间过", "label": "体标"}, {"form": "反間", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "用计策离间敌方，使其内部猜疑；军事、历史语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5429df9e-59d2-4ea4-a29b-edbfe11afe3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87962, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反间", "is_correct": true, "explanation": "正确答案：反间（fǎn jiàn），即用计策离间敌方内部。"}, {"text": "翻建", "is_correct": false, "explanation": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻修、重建。"}, {"text": "反剪", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是反剪双手。"}, {"text": "眼见", "is_correct": false, "explanation": "yǎn（第三声）与 fǎn（第三声）声母不同（y 与 f），意思是亲眼看见。"}], "explanations": {"反间": "正确答案：反间（fǎn jiàn），即用计策离间敌方内部。", "翻建": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻修、重建。", "反剪": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是反剪双手。", "眼见": "yǎn（第三声）与 fǎn（第三声）声母不同（y 与 f），意思是亲眼看见。"}, "sentence_index": null, "correct_answer": "反间"}, "level_3": {"options": [{"text": "反间", "is_correct": true, "explanation": "正确：反间即用计离间敌方，与“假信”和“敌人”的语境相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”与“敌人”及“假信”所代表的敌对手段相矛盾，不能用假信去保护敌人。"}, {"text": "表彰", "is_correct": false, "explanation": "语义：“表彰”是褒奖，与用假信对付敌人的意图不符。"}, {"text": "招待", "is_correct": false, "explanation": "搭配：“招待”针对宾客，不能以“用假信”为方式招待敌人。"}], "explanations": {"反间": "正确：反间即用计离间敌方，与“假信”和“敌人”的语境相合。", "保护": "语义：“保护”与“敌人”及“假信”所代表的敌对手段相矛盾，不能用假信去保护敌人。", "表彰": "语义：“表彰”是褒奖，与用假信对付敌人的意图不符。", "招待": "搭配：“招待”针对宾客，不能以“用假信”为方式招待敌人。"}, "sentence_index": 0, "correct_answer": "反间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敌人一冲进来，我们就立刻反间他们。", "explanation": "这里应该用〈反击〉。反间是用计离间敌方内部，不是立刻还击敌人。"}, {"text": "大家都反间这个计划，不愿意执行。", "explanation": "这里应该用〈反对〉。反间是离间敌方内部，不用于表示反对某个计划。"}, {"text": "我们要想办法反间敌人的粮草，让他们断粮。", "explanation": "这里应该用〈烧毁〉。反间的对象须是人或人群，“粮草”是物，不能被离间；针对粮草应使用“烧毁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反间", "is_correct": true, "explanation": "正确：反间即用金子离间敌方将军，与“敌人的将军”的语境相合。"}, {"text": "支援", "is_correct": false, "explanation": "语义：“支援”是帮助己方，与“敌人的将军”矛盾。"}, {"text": "铸造", "is_correct": false, "explanation": "搭配：“铸造”的对象是器物或货币，不能用于“将军”。"}, {"text": "拥戴", "is_correct": false, "explanation": "语义：“拥戴”是拥护领袖，不能用来对付敌人的将军。"}], "explanations": {"反间": "正确：反间即用金子离间敌方将军，与“敌人的将军”的语境相合。", "支援": "语义：“支援”是帮助己方，与“敌人的将军”矛盾。", "铸造": "搭配：“铸造”的对象是器物或货币，不能用于“将军”。", "拥戴": "语义：“拥戴”是拥护领袖，不能用来对付敌人的将军。"}, "sentence_index": 6, "correct_answer": "反间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司每年都在电视上反间新产品。", "explanation": "这里应该用〈宣传〉。反间是离间敌方内部，不用于向大众介绍产品。"}, {"text": "医生反间了那位病人。", "explanation": "这里应该用〈救助〉。反间是离间敌方内部的手段，与医生救治病人无关。"}, {"text": "他总在朋友之间反间，让他们渐渐疏远。", "explanation": "这里应该用〈挑拨〉。反间只用于敌方内部，不能用于朋友之间；朋友间制造隔阂应说“挑拨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在用假消息反间了敌人。", "corrected_sentence": "我们正在用假消息反间敌人。", "error_description": "“正在”表示动作正在进行，不能与动态助词“了”同用。应去掉“反间”后面的“了”，写作：我们正在用假消息反间敌人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们派人把敌方的谋士反间。", "corrected_sentence": "他们派人把敌方的谋士反间了。", "error_description": "“把”字句中，动词“反间”后须有补语或“了”等成分，单独作谓语不成立。应加“了”，写作：他们派人把敌方的谋士反间了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87963, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87963, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87963, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "航天是人乘坐飞船等到地球大气层以外的太空去飞行。", "primary_collocate": null, "pronunciation": "háng tiān", "ipa": "xɑŋ˧˥ tʰi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "他曾两次航天，积累了丰富的经验。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "小时候，他就希望有一天能够航天。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "首次航天的宇航员，要先接受大量训练。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "他是中国第一位成功航天的人。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "想要航天，就必须先接受严格的训练。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "长时间航天，对身体的考验很大。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "许多孩子都梦想长大后能够航天。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "她说航天时，舷窗外能看到整个地球。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "他们准备了三年，下个月即将首次航天。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "在航天前，他给家人打了一个电话。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}], "morphological_forms": [{"form": "航天员", "label": "复合"}, {"form": "航天器", "label": "复合"}, {"form": "航天局", "label": "复合"}], "register": "书面", "sense_fingerprint": "人乘飞船到大气层外太空飞行（宇航员的经历）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咳嗽", "is_correct": false, "explanation": "搭配：“积累丰富的经验”不能以“咳嗽”为行为基础，句子读不通"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指出生，只能发生一次，不能“两次”，与句意冲突"}, {"text": "航天", "is_correct": true, "explanation": "正确：“两次航天”指两次乘火箭飞往太空，才能“积累丰富的经验”"}, {"text": "打哈欠", "is_correct": false, "explanation": "搭配：“打哈欠”是身体的反射动作，不能“积累丰富的经验”，句子读不通"}], "explanations": {"咳嗽": "搭配：“积累丰富的经验”不能以“咳嗽”为行为基础，句子读不通", "诞生": "语义：“诞生”指出生，只能发生一次，不能“两次”，与句意冲突", "航天": "正确：“两次航天”指两次乘火箭飞往太空，才能“积累丰富的经验”", "打哈欠": "搭配：“打哈欠”是身体的反射动作，不能“积累丰富的经验”，句子读不通"}, "sentence_index": 0, "correct_answer": "航天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们乘坐的客机每小时航天八百公里。", "explanation": "这里应该用〈飞行〉。航天专指在大气层以外的宇宙空间飞行，客机在大气层内飞行，要说飞行"}, {"text": "这艘货轮要在太平洋上航天半个月。", "explanation": "这里应该用〈航行〉。航行指船只或飞机在水面、空中行进，货轮在海上只能说航行，不能说航天"}, {"text": "这支远洋船队计划航天三个月。", "explanation": "这里应该用〈远航〉。远航指船只长途航行，航天只用于大气层外的宇宙飞行，船队不能说航天"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：“出生”只能发生一次，孩子不能“能够”去出生，句意不通"}, {"text": "失业", "is_correct": false, "explanation": "搭配：“梦想长大后能够”后接的是孩子向往的目标，“失业”不是可以去追求的目标"}, {"text": "航天", "is_correct": true, "explanation": "正确：“梦想长大后能够航天”指希望将来能乘火箭飞往太空"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“呼吸”是人的本能，不是长大后要去实现的梦想，句意不通"}], "explanations": {"出生": "语义：“出生”只能发生一次，孩子不能“能够”去出生，句意不通", "失业": "搭配：“梦想长大后能够”后接的是孩子向往的目标，“失业”不是可以去追求的目标", "航天": "正确：“梦想长大后能够航天”指希望将来能乘火箭飞往太空", "呼吸": "语义：“呼吸”是人的本能，不是长大后要去实现的梦想，句意不通"}, "sentence_index": 6, "correct_answer": "航天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暑假我们去欧洲航天了两个星期。", "explanation": "这里应该用〈旅行〉。航天只指在大气层以外的宇宙空间飞行，去欧洲只能说旅行"}, {"text": "他每天早上在泳池航天。", "explanation": "这里应该用〈游泳〉。航天是宇宙飞行，泳池里的活动只能说游泳"}, {"text": "航班下午三点准时航天。", "explanation": "这里应该用〈起飞〉。普通航班在大气层内起飞，不在宇宙空间飞行，只能说起飞"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾三次航天着，每次都很顺利。", "corrected_sentence": "他曾三次航天，每次都很顺利。", "error_description": "错误在“航天”后多了“着”。“航天”是一次性的动作，不能带“着”表示持续，应去掉“着”，写作“他曾三次航天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们将在下个月航天过。", "corrected_sentence": "他们将在下个月航天。", "error_description": "错误在“航天”后多了“过”。“过”表示已经发生过的经历，而“下个月”是将来，应去掉“过”，写作“将在下个月航天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
