INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87964, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在地球大气层以外的宇宙空间飞行。", "primary_collocate": null, "pronunciation": "háng tiān", "ipa": "xɑŋ˧˥ tʰi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "这艘飞船已经航天三天了，一切正常。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "他们航天了十天，才返回地球。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "航天的时候，飞船里几乎没有重力。", "target_word": "航天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞船离开地球后，已经航天两天了。", "target_word": "航天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次航天，他们一共绕地球转了十六圈。", "target_word": "航天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航天时，人在飞船里会飘起来。", "target_word": "航天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大气层以外航天，不能用普通的飞机。", "target_word": "航天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞船在航天时的速度非常快。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "听说他明年要参与一次航天。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}, {"text": "人在航天期间，要吃特别的食物。", "target_word": "航天", "complexity_tier": "T3", "furigana": "háng tiān", "sentence_source": "generated"}], "morphological_forms": [{"form": "航天员", "label": "复合"}, {"form": "航天器", "label": "复合"}, {"form": "航天局", "label": "复合"}], "register": "书面", "sense_fingerprint": "在大气层外的宇宙空间飞行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人或动物的诞生，飞船不能“出生”，句意不通"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”的主语只能是人或动物，飞船不能“感冒”"}, {"text": "航天", "is_correct": true, "explanation": "正确：“飞船已经航天三天了”指飞船在大气层外的宇宙空间飞行三天"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”只用于有身体的人或动物，飞船不能“咳嗽”"}], "explanations": {"出生": "语义：“出生”指人或动物的诞生，飞船不能“出生”，句意不通", "感冒": "搭配：“感冒”的主语只能是人或动物，飞船不能“感冒”", "航天": "正确：“飞船已经航天三天了”指飞船在大气层外的宇宙空间飞行三天", "咳嗽": "搭配：“咳嗽”只用于有身体的人或动物，飞船不能“咳嗽”"}, "sentence_index": 0, "correct_answer": "航天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这艘渡轮昨天在海上航天了一整天。", "explanation": "这里应该用〈航行〉。航天只指在大气层以外的宇宙空间飞行，渡轮在海上只能说航行"}, {"text": "这架飞机在云层里航天了两小时。", "explanation": "这里应该用〈飞行〉。飞机在大气层内飞行，云层中只能说飞行，航天指大气层外的宇宙飞行"}, {"text": "这架滑翔机在山谷上空航天。", "explanation": "这里应该用〈滑翔〉。滑翔机靠气流在大气层内滑行，不在宇宙空间，只能说滑翔"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”只能发生一次，不能在大气层外“诞生”，句意不通"}, {"text": "失业", "is_correct": false, "explanation": "搭配：“失业”的主语是人，且与“不能用普通的飞机”的句意无关，无法成立"}, {"text": "航天", "is_correct": true, "explanation": "正确：“在大气层以外航天”指在宇宙空间飞行，所以不能用普通的飞机"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：大气层以外的空间没有可供人正常呼吸的空气，“呼吸”与句子的因果不合"}], "explanations": {"诞生": "语义：“诞生”只能发生一次，不能在大气层外“诞生”，句意不通", "失业": "搭配：“失业”的主语是人，且与“不能用普通的飞机”的句意无关，无法成立", "航天": "正确：“在大气层以外航天”指在宇宙空间飞行，所以不能用普通的飞机", "呼吸": "语义：大气层以外的空间没有可供人正常呼吸的空气，“呼吸”与句子的因果不合"}, "sentence_index": 6, "correct_answer": "航天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们计划在珠峰航天两周。", "explanation": "这里应该用〈登山〉。航天指在大气层以外的宇宙空间飞行，珠峰在地面，只能说登山"}, {"text": "这位潜水员在海底航天三十分钟。", "explanation": "这里应该用〈潜水〉。航天是宇宙飞行，海底的活动只能说潜水"}, {"text": "我们每天傍晚在公园航天。", "explanation": "这里应该用〈散步〉。航天不用于地面活动，公园里的活动只能说散步"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这艘飞船计划航天了十五天。", "corrected_sentence": "这艘飞船计划航天十五天。", "error_description": "错误在“航天”后多了“了”。“计划”指将来的安排，不能与表示完成的“了”搭配，应去掉“了”，写作“计划航天十五天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宇航员明天航天了。", "corrected_sentence": "宇航员明天航天。", "error_description": "错误在“航天”后多了“了”。“明天”是将来，“了”表示已经完成，二者不合，应去掉“了”，写作“明天航天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
