INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87966, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人数多、规模大的会议。", "primary_collocate": null, "pronunciation": "dà huì", "ipa": "ta˥˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "明天上午学校要开大会。", "target_word": "大会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大会九点开始，请大家早点来。", "target_word": "大会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次大会有两千多人参加。", "target_word": "大会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长在大会上说了几句话。", "target_word": "大会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大会结束后，大家一起吃了饭。", "target_word": "大会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每年开一次大会。", "target_word": "大会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在大会上得了奖。", "target_word": "大会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大会的会场很大，坐满了人。", "target_word": "大会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说这个大会要开三天。", "target_word": "大会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们都去体育馆参加大会。", "target_word": "大会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "全体大会", "label": "复合"}, {"form": "代表大会", "label": "复合"}], "register": "中性", "sense_fingerprint": "人数多、规模大的会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9987eb-5886-4587-85c6-5e6350eb4adf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87966, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大会", "is_correct": true, "explanation": "正确答案。大会读作 dà huì，指人数多、规模大的会议。"}, {"text": "大火", "is_correct": false, "explanation": "dà huǒ 与 dà huì 只在第二个音节上不同：韵母 uo/ui、声调第三声/第四声。大火意思是大的火灾。"}, {"text": "大祸", "is_correct": false, "explanation": "dà huò 与 dà huì 第二个音节韵母不同（uo/ui），大祸意思是重大灾祸。"}, {"text": "大伙", "is_correct": false, "explanation": "dà huǒ 与 dà huì 第一个音节相同，第二个音节韵母与声调不同。大伙是口语「大家」的意思。"}], "explanations": {"大会": "正确答案。大会读作 dà huì，指人数多、规模大的会议。", "大火": "dà huǒ 与 dà huì 只在第二个音节上不同：韵母 uo/ui、声调第三声/第四声。大火意思是大的火灾。", "大祸": "dà huò 与 dà huì 第二个音节韵母不同（uo/ui），大祸意思是重大灾祸。", "大伙": "dà huǒ 与 dà huì 第一个音节相同，第二个音节韵母与声调不同。大伙是口语「大家」的意思。"}, "sentence_index": null, "correct_answer": "大会"}, "level_3": {"options": [{"text": "大会", "is_correct": true, "explanation": "正确答案。「学校要开大会」指规模较大的全校性会议。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：「明天上午」与晚会（晚上举行）的时间相冲突。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：学校不举办婚礼，与「学校要开」的语境不符。"}, {"text": "雨季", "is_correct": false, "explanation": "语义：雨季是季节，不是可以举办的活动，与「学校要开」搭配不通。"}], "explanations": {"大会": "正确答案。「学校要开大会」指规模较大的全校性会议。", "晚会": "语义：「明天上午」与晚会（晚上举行）的时间相冲突。", "婚礼": "语义：学校不举办婚礼，与「学校要开」的语境不符。", "雨季": "语义：雨季是季节，不是可以举办的活动，与「学校要开」搭配不通。"}, "sentence_index": 0, "correct_answer": "大会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和三个朋友在大会上吃了一顿饭。", "explanation": "这里应该用〈聚餐〉。大会指人数多、规模大的正式会议，三个朋友吃饭不能说在大会上。"}, {"text": "我们在大会上聊了一晚上天。", "explanation": "这里应该用〈聚会〉。大会有正式议程、规模大，朋友私下聊天应说聚会。"}, {"text": "我的三个朋友在大会上结了婚。", "explanation": "这里应该用〈婚礼〉。大会是正式会议，结婚要在婚礼上举行，不能说在大会上结婚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87966, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大会", "is_correct": true, "explanation": "正确答案。大会读作 dà huì，指人数多、规模大的会议。"}, {"text": "打回", "is_correct": false, "explanation": "dǎ huí 与 dà huì 声母韵母几乎相同，只是两个音节的声调不同（第三声/第四声，第二声/第四声）。打回意思是打回去、退回。"}, {"text": "带回", "is_correct": false, "explanation": "dài huí 与 dà huì 读音相近：第一个音节韵母不同（ai/a），第二个音节声调不同（第二声/第四声）。带回意思是把东西或人带着回来。"}, {"text": "大惑", "is_correct": false, "explanation": "dà huò 与 dà huì 第二个音节韵母不同，大惑意思是十分迷惑（如大惑不解）。"}], "explanations": {"大会": "正确答案。大会读作 dà huì，指人数多、规模大的会议。", "打回": "dǎ huí 与 dà huì 声母韵母几乎相同，只是两个音节的声调不同（第三声/第四声，第二声/第四声）。打回意思是打回去、退回。", "带回": "dài huí 与 dà huì 读音相近：第一个音节韵母不同（ai/a），第二个音节声调不同（第二声/第四声）。带回意思是把东西或人带着回来。", "大惑": "dà huò 与 dà huì 第二个音节韵母不同，大惑意思是十分迷惑（如大惑不解）。"}, "sentence_index": null, "correct_answer": "大会"}, "level_3": {"options": [{"text": "大会", "is_correct": true, "explanation": "正确答案。「在大会上得了奖」指在大型会议中获奖。"}, {"text": "考场", "is_correct": false, "explanation": "语义：得奖一般不在考场上发生，与语境不符。"}, {"text": "书房", "is_correct": false, "explanation": "语义：书房与比赛、得奖的场合无关，不合语境。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房与得奖无关，不合语境。"}], "explanations": {"大会": "正确答案。「在大会上得了奖」指在大型会议中获奖。", "考场": "语义：得奖一般不在考场上发生，与语境不符。", "书房": "语义：书房与比赛、得奖的场合无关，不合语境。", "病房": "语义：病房与得奖无关，不合语境。"}, "sentence_index": 6, "correct_answer": "大会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妹妹在大会上学会了游泳。", "explanation": "这里应该用〈游泳班〉。大会是多人参加的正式会议，学游泳要去游泳班，不能说在大会上学会。"}, {"text": "我们在大会上给妈妈过了一次生日。", "explanation": "这里应该用〈生日会〉。大会是正式会议，给家人过生日应说生日会。"}, {"text": "我们晚上在大会上跳舞，一直跳到深夜。", "explanation": "这里应该用〈晚会〉。大会是正式会议，晚上联欢跳舞应说晚会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校昨天开了一只大会，很多老师都来了。", "corrected_sentence": "学校昨天开了一次大会，很多老师都来了。", "error_description": "「大会」的量词应用「次」或「场」，「只」用于动物等，不能用于大会。正确说法是「一次大会」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校明天要做大会。", "corrected_sentence": "学校明天要开大会。", "error_description": "「大会」常与动词「开」搭配，应说「开大会」，「做大会」搭配错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
