INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87967, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87967, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "用于应答，表示同意对方的话，相当于“对啊”。", "primary_collocate": null, "pronunciation": "kě bú shì", "ipa": "kʰɤ˨˩ pu˧˥ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "这电影真好看！——可不是，我看了两遍。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业太多了。——可不是，写不完。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，天气冷多了。——可不是！", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱歌真好听。——可不是，像歌星一样。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上车太多了。——可不是，总是堵车。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明比去年高多了。——可不是，快一米八了。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你妈做的饺子真香。——可不是，我吃了二十个。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我花钱花得太多了。——可不是，该省点了。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩的感情真好。——可不是，天天在一起。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛我们赢了！——可不是，大家都很高兴。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可不是嘛", "label": "语气词形式"}], "register": "口语", "sense_fingerprint": "别人说话时同意对方，意思是对啊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19caa3-16e4-4fcd-a031-4c3dbc5187f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87967, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可不是", "is_correct": true, "explanation": "正确：“可不是”表示同意对方的话，与“看了两遍”的语境相符。"}, {"text": "呸", "is_correct": false, "explanation": "语义：“呸”表示唾弃，与“好看”的赞叹相反。"}, {"text": "咳", "is_correct": false, "explanation": "语义：“咳”是咳嗽声，不能用来表示同意。"}, {"text": "不客气", "is_correct": false, "explanation": "语义：“不客气”用来回应感谢，对方是在称赞电影，不是道谢。"}], "explanations": {"可不是": "正确：“可不是”表示同意对方的话，与“看了两遍”的语境相符。", "呸": "语义：“呸”表示唾弃，与“好看”的赞叹相反。", "咳": "语义：“咳”是咳嗽声，不能用来表示同意。", "不客气": "语义：“不客气”用来回应感谢，对方是在称赞电影，不是道谢。"}, "sentence_index": 0, "correct_answer": "可不是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "谢谢你的帮忙！——可不是。", "explanation": "这里应该用〈不客气〉。“可不是”只用来同意对方已经说出的陈述，不能用来回应道谢。"}, {"text": "他唱歌很难听。——可不是，他唱得很好。", "explanation": "这里误把“可不是”当作反驳语来用。它只能顺着对方的话表示同意，接上相反的评价就前后矛盾。"}, {"text": "对不起，我来晚了。——可不是。", "explanation": "这里应该用〈没关系〉。“可不是”只用来同意对方的看法，不能用来回应道歉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可不是", "is_correct": true, "explanation": "正确：“可不是”表示同意对方的话，与“饺子真香”后“吃了二十个”的语境相符。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，与“饺子真香”的赞叹不相合。"}, {"text": "对不起", "is_correct": false, "explanation": "语义：“对不起”用来道歉，不能表示同意对方的称赞。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”多用于呼唤或接电话，不接在赞叹之后表示同意。"}], "explanations": {"可不是": "正确：“可不是”表示同意对方的话，与“饺子真香”后“吃了二十个”的语境相符。", "嘘": "语义：“嘘”表示让人安静，与“饺子真香”的赞叹不相合。", "对不起": "语义：“对不起”用来道歉，不能表示同意对方的称赞。", "喂": "搭配：“喂”多用于呼唤或接电话，不接在赞叹之后表示同意。"}, "sentence_index": 6, "correct_answer": "可不是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "各位领导：可不是，本项工作已经全面完成。", "explanation": "这里应该用〈确实〉。“可不是”是口语应答语，书面的通知和致辞中要用“确实”。"}, {"text": "请坐！——可不是。", "explanation": "这里应该用〈谢谢〉。“可不是”只用来同意对方已经说出的陈述，不能用来回应请人入座。"}, {"text": "你吃饭了吗？——可不是，我还没吃。", "explanation": "这里应该直接回答问题。“可不是”只用来同意对方已经说出的陈述，不能当作对疑问的直接回答。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌真好听！——可不是的，我听了好几遍。", "corrected_sentence": "这首歌真好听！——可不是，我听了好几遍。", "error_description": "错误：“可不是的”。正确：“可不是”。“可不是”是叹词，独立用于应答，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试我们班得了第一！——可不是了，老师都很高兴。", "corrected_sentence": "这次考试我们班得了第一！——可不是，老师都很高兴。", "error_description": "错误：“可不是了”。正确：“可不是”。“可不是”是叹词，独立用于应答，后面不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87968, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
