INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87968, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "用于应答，表示同意对方的话，相当于“确实如此”。", "primary_collocate": null, "pronunciation": "kě bú shì", "ipa": "kʰɤ˨˩ pu˧˥ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "今天真热啊！——可不是，我都出了一身汗。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜太贵了。——可不是，我也这么想。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得对，现在工作真难找。——可不是！", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近天天下雨，烦死了。——可不是嘛！", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这孩子长得真快。——可不是，一年高了十厘米。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王的汉语说得真好。——可不是，他学了十年。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试太难了，我没写完。——可不是，我也是。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的东西又新鲜又便宜。——可不是！", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间过得真快，又到周末了。——可不是！", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天又迟到了。——可不是，已经第三次了。", "target_word": "可不是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可不是嘛", "label": "语气词形式"}], "register": "口语", "sense_fingerprint": "应答用语：同意对方，相当于确实如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19caa3-16e4-4fcd-a031-4c3dbc5187f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可不是", "is_correct": true, "explanation": "正确：“可不是”表示同意对方的话，与“出了一身汗”的语境相符。"}, {"text": "哼", "is_correct": false, "explanation": "语义：“哼”表示不满或轻蔑，与对方说“真热”的感叹不相合，也不表示同意。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，回应“真热”没有意义。"}, {"text": "再见", "is_correct": false, "explanation": "语义：“再见”用于告别，不能用来同意对方“真热”的感叹。"}], "explanations": {"可不是": "正确：“可不是”表示同意对方的话，与“出了一身汗”的语境相符。", "哼": "语义：“哼”表示不满或轻蔑，与对方说“真热”的感叹不相合，也不表示同意。", "嘘": "语义：“嘘”表示让人安静，回应“真热”没有意义。", "再见": "语义：“再见”用于告别，不能用来同意对方“真热”的感叹。"}, "sentence_index": 0, "correct_answer": "可不是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "帮我把门关上。——可不是。", "explanation": "这里应该用〈好〉。“可不是”只用来同意对方已经说出的陈述，不能用来应答祈使句。"}, {"text": "你说明天下雨？——可不是，明天不会下雨。", "explanation": "这里误把“可不是”当作反驳语来用。它只能顺着对方的话表示同意，接上相反的看法就前后矛盾。"}, {"text": "你明天来不来？——可不是。", "explanation": "“可不是”只用来同意对方已经说出的陈述，不用来回答“来不来”这类疑问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可不是", "is_correct": true, "explanation": "正确：“可不是”表示同意对方的话，与“我也是”的认同语气相符。"}, {"text": "呸", "is_correct": false, "explanation": "语义：“呸”表示唾弃或厌恶，与对方“考试太难”的话不相合。"}, {"text": "咳", "is_correct": false, "explanation": "语义：“咳”是咳嗽或清嗓子的声音，不能接在此处表示认同。"}, {"text": "没关系", "is_correct": false, "explanation": "语义：“没关系”用来回应道歉，对方没有道歉，不能接“我也是”。"}], "explanations": {"可不是": "正确：“可不是”表示同意对方的话，与“我也是”的认同语气相符。", "呸": "语义：“呸”表示唾弃或厌恶，与对方“考试太难”的话不相合。", "咳": "语义：“咳”是咳嗽或清嗓子的声音，不能接在此处表示认同。", "没关系": "语义：“没关系”用来回应道歉，对方没有道歉，不能接“我也是”。"}, "sentence_index": 6, "correct_answer": "可不是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "谢谢你送我回家！——可不是。", "explanation": "这里应该用〈不客气〉。“可不是”只用来同意对方的看法，不能用来回应道谢。"}, {"text": "尊敬的各位来宾：可不是，本次会议取得了圆满成功。", "explanation": "这里应该用〈确实〉。“可不是”是口语应答语，正式致辞中要用“确实”。"}, {"text": "早上好！——可不是。", "explanation": "这里应该用〈你好〉。“可不是”只用来同意对方已经说出的陈述，不能用来回应问候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路上真堵啊！——可不是了，车多得很。", "corrected_sentence": "路上真堵啊！——可不是，车多得很。", "error_description": "错误：“可不是了”。正确：“可不是”。“可不是”是叹词，单独用于应答，后面不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王又把钥匙忘在家里了。——很可不是，他总是这样。", "corrected_sentence": "小王又把钥匙忘在家里了。——可不是，他总是这样。", "error_description": "错误：“很可不是”。正确：“可不是”。“可不是”是叹词，前面不能加程度副词“很”来修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
