INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成年女子的通称。", "primary_collocate": null, "pronunciation": "fù nǚ", "ipa": "fu˥˩ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "那位妇女在公园里带着孩子玩。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多妇女早上去市场买菜。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子里的妇女都会做衣服。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位妇女在车站问我路怎么走。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妇女们坐在树下聊天。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她帮助过很多生活困难的妇女。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂里有不少妇女工作。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位年轻妇女手里拿着一把伞。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位妇女正在河边洗衣服。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生请那位妇女先坐下。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "婦女", "label": "繁体"}], "register": "中性偏书面", "sense_fingerprint": "成年女子的通称，指女人这一群体或其中一员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ac39683-0e14-4009-8f9a-c5a67e844ca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妇女", "is_correct": true, "explanation": "正确：“妇女”指成年女子，与“那位……带着孩子玩”的语境相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不能带着别的孩子在公园玩，句中“带着孩子”的主语必须是成年人。"}, {"text": "宝宝", "is_correct": false, "explanation": "语义：宝宝还不会带别的孩子玩，句中“带着孩子”的主语须是能照顾他人的人。"}, {"text": "胎儿", "is_correct": false, "explanation": "语义：胎儿还在母体中，不可能在公园里带着孩子玩。"}], "explanations": {"妇女": "正确：“妇女”指成年女子，与“那位……带着孩子玩”的语境相符。", "婴儿": "语义：婴儿不能带着别的孩子在公园玩，句中“带着孩子”的主语必须是成年人。", "宝宝": "语义：宝宝还不会带别的孩子玩，句中“带着孩子”的主语须是能照顾他人的人。", "胎儿": "语义：胎儿还在母体中，不可能在公园里带着孩子玩。"}, "sentence_index": 0, "correct_answer": "妇女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的妹妹是一位妇女，她今年才十岁。", "explanation": "这里应该用〈女孩〉。“妇女”指成年女子，不能用来称呼十岁的孩子。"}, {"text": "我爷爷是一位妇女，他每天都去公园散步。", "explanation": "这里应该用〈老人〉。“妇女”指女性，不能用来指男性的爷爷。"}, {"text": "那位妇女还不到十八岁，还不能参加选举。", "explanation": "这里应该用〈未成年人〉。“妇女”指成年女子，不到十八岁的人不能称为妇女。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妇女", "is_correct": true, "explanation": "正确：“妇女”指成年女子，符合“这家工厂里有不少……工作”的语境。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不能在工厂里工作。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能在工厂里工作。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不会工作。"}], "explanations": {"妇女": "正确：“妇女”指成年女子，符合“这家工厂里有不少……工作”的语境。", "婴儿": "语义：婴儿不能在工厂里工作。", "小猫": "语义：小猫是动物，不能在工厂里工作。", "桌子": "语义：桌子是物品，不会工作。"}, "sentence_index": 6, "correct_answer": "妇女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小猫是妇女。", "explanation": "“妇女”专指成年女性这类人，不能用来指猫这样的动物。"}, {"text": "我的同学叫妇女。", "explanation": "“妇女”是泛称，不是人名，不能用来给人取名。"}, {"text": "我的妇女在厨房做饭。", "explanation": "这里应该用〈妻子〉。“妇女”是泛指女性的名词，不能用来指自己的妻子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
