INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87971, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吊是用绳子把东西挂起来，让它在空中。", "primary_collocate": null, "pronunciation": "diào", "ipa": "tjɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "他用绳子把铃铛吊在半空中。", "target_word": "吊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶上吊着一盏大灯。", "target_word": "吊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在舞台上方吊了很多彩带。", "target_word": "吊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这块牌子吊在门前。", "target_word": "吊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫看着吊在空中的小鱼干。", "target_word": "吊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把广告牌吊在商店门口。", "target_word": "吊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把沙袋吊在树上练拳。", "target_word": "吊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把干辣椒吊在窗前，风一吹就晃。", "target_word": "吊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日的晚上，我们把小灯笼吊在树枝上。", "target_word": "吊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把大钟吊到了塔顶。", "target_word": "吊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吊着", "label": "体标"}, {"form": "吊了", "label": "体标"}, {"form": "吊过", "label": "体标"}], "register": "口语", "sense_fingerprint": "用绳子把东西挂起，使其悬在空中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167a7954-97b5-4a26-941f-142692a13d69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87971, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "票", "is_correct": false, "explanation": "声母不同：piào 的 p 与 diào 的 d 不同，意思是票。"}, {"text": "吊", "is_correct": true, "explanation": "正确答案：吊（diào），指用绳子把东西挂起来，使其悬在空中。"}, {"text": "庙", "is_correct": false, "explanation": "声母不同：miào 的 m 与 diào 的 d 不同，意思是庙。"}, {"text": "电", "is_correct": false, "explanation": "韵母不同：diàn 的 an 与 diào 的 ao 不同，意思是电。"}, {"text": "雕", "is_correct": false, "explanation": "声调不同：diāo（第一声）与 diào（第四声）只差声调，意思是雕刻。"}], "explanations": {"票": "声母不同：piào 的 p 与 diào 的 d 不同，意思是票。", "吊": "正确答案：吊（diào），指用绳子把东西挂起来，使其悬在空中。", "庙": "声母不同：miào 的 m 与 diào 的 d 不同，意思是庙。", "电": "韵母不同：diàn 的 an 与 diào 的 ao 不同，意思是电。", "雕": "声调不同：diāo（第一声）与 diào（第四声）只差声调，意思是雕刻。"}, "sentence_index": null, "correct_answer": "吊"}, "level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：「扔」是抛掷，动作结束后不表示悬挂静止在半空中，与「用绳子悬挂」不合。"}, {"text": "吊", "is_correct": true, "explanation": "正确答案：吊，用绳子把铃铛悬挂在半空中。"}, {"text": "摇", "is_correct": false, "explanation": "语义：「摇」是晃动，不表示把东西悬挂在空中。"}, {"text": "按", "is_correct": false, "explanation": "搭配：「按」不带「在半空中」的悬挂补足语，不能说按在半空中。"}], "explanations": {"扔": "语义：「扔」是抛掷，动作结束后不表示悬挂静止在半空中，与「用绳子悬挂」不合。", "吊": "正确答案：吊，用绳子把铃铛悬挂在半空中。", "摇": "语义：「摇」是晃动，不表示把东西悬挂在空中。", "按": "搭配：「按」不带「在半空中」的悬挂补足语，不能说按在半空中。"}, "sentence_index": 0, "correct_answer": "吊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说完话就吊了电话。", "explanation": "这里应该用〈挂〉。吊是用绳子把东西悬起来，挂电话是把听筒放回原处，不能说吊电话。"}, {"text": "他热得满头大汗，随手吊了一下额头的汗。", "explanation": "这里应该用〈擦〉。擦汗是用毛巾抹去汗水，吊是用绳子把东西悬起来，不能用来表示擦汗。"}, {"text": "他吊上了衬衫的扣子。", "explanation": "这里应该用〈扣〉。吊指悬挂东西，扣扣子是把扣子扣进扣眼，不能用吊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87971, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跳", "is_correct": false, "explanation": "声母不同：tiào 的 t 与 diào 的 d 不同，意思是跳。"}, {"text": "吊", "is_correct": true, "explanation": "正确答案：吊（diào），指用绳子把东西挂起来，使其悬在空中。"}, {"text": "笑", "is_correct": false, "explanation": "声母不同：xiào 的 x 与 diào 的 d 不同，意思是笑。"}, {"text": "到", "is_correct": false, "explanation": "介音不同：dào 没有 i 介音，diào 有 i 介音，意思是到。"}, {"text": "翘", "is_correct": false, "explanation": "声母不同：qiào 的 q 与 diào 的 d 不同，意思是翘起。"}], "explanations": {"跳": "声母不同：tiào 的 t 与 diào 的 d 不同，意思是跳。", "吊": "正确答案：吊（diào），指用绳子把东西挂起来，使其悬在空中。", "笑": "声母不同：xiào 的 x 与 diào 的 d 不同，意思是笑。", "到": "介音不同：dào 没有 i 介音，diào 有 i 介音，意思是到。", "翘": "声母不同：qiào 的 q 与 diào 的 d 不同，意思是翘起。"}, "sentence_index": null, "correct_answer": "吊"}, "level_3": {"options": [{"text": "扛", "is_correct": false, "explanation": "语义：「扛」是用肩膀承担，不表示把沙袋悬挂在树上。"}, {"text": "吊", "is_correct": true, "explanation": "正确答案：吊，把沙袋悬挂在树上练拳。"}, {"text": "踢", "is_correct": false, "explanation": "语义：「踢」是用脚撞击，与句中悬挂沙袋的动作不符。"}, {"text": "挤", "is_correct": false, "explanation": "配价：「挤」带「在树上」只表示挤入，不能用于悬挂沙袋。"}], "explanations": {"扛": "语义：「扛」是用肩膀承担，不表示把沙袋悬挂在树上。", "吊": "正确答案：吊，把沙袋悬挂在树上练拳。", "踢": "语义：「踢」是用脚撞击，与句中悬挂沙袋的动作不符。", "挤": "配价：「挤」带「在树上」只表示挤入，不能用于悬挂沙袋。"}, "sentence_index": 6, "correct_answer": "吊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在纸上吊了三个字。", "explanation": "这里应该用〈写〉。写字是用笔书写文字，吊是用绳子悬挂，不能说吊字。"}, {"text": "他给客人吊了一杯茶。", "explanation": "这里应该用〈泡〉。泡茶是用热水冲泡茶叶，吊是用绳子悬挂，不能说吊茶。"}, {"text": "他一早起来吊了一下地。", "explanation": "这里应该用〈扫〉。扫地是用扫帚清理地面，吊是用绳子悬挂，不能说吊地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把旗子吊大门上方。", "corrected_sentence": "他把旗子吊在大门上方。", "error_description": "错误：「吊大门上方」漏了介词「在」；正确：「吊在大门上方」。表示悬挂的处所要用「在」引出，不能直接接处所名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋檐上吊了着一串红辣椒，风一吹就晃。", "corrected_sentence": "屋檐上吊着一串红辣椒，风一吹就晃。", "error_description": "错误：「吊」后多加了「了」，「了着」不成立；「吊着」表示状态持续，不能再加「了」。正确：「屋檐上吊着一串红辣椒」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87973, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "正确答案：“正常”与“怪”（不一般）构成反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”描述温度或感受，与“不一般”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”描述光线，与“怪”的“不寻常”不构成反义。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”指排列有序，与“怪”没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "正确答案：“正常”与“怪”（不一般）构成反义关系。", "温暖": "“温暖”描述温度或感受，与“不一般”没有反义关系。", "明亮": "“明亮”描述光线，与“怪”的“不寻常”不构成反义。", "整齐": "“整齐”指排列有序，与“怪”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87973, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "正确答案：“正常”与“怪”（不一般）构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相对，与“怪”的“不一般”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”指排列有序，与“怪”没有反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "“温和”形容性情或态度，与“不一般”没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "正确答案：“正常”与“怪”（不一般）构成反义关系。", "安静": "“安静”与“吵闹”相对，与“怪”的“不一般”没有反义关系。", "整齐": "“整齐”指排列有序，与“怪”没有反义关系。", "温和": "“温和”形容性情或态度，与“不一般”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87973, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "怪是不一般，让人觉得有点怕或者奇怪。", "primary_collocate": null, "pronunciation": "guài", "ipa": "kwaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "半夜里，窗外有一个怪影子。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天的样子很怪，我看了有点害怕。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房子晚上有点怪，我不敢进去。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我做了一个很怪的梦，吓醒了。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那条黑路上的灯光很怪。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山洞里很黑，里面有点怪，大家都停住了。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的笑声听起来很怪，让人害怕。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看着我，眼神怪怪的。", "target_word": "怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的森林安静得有点怪。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个老人说话很怪，孩子们都躲开他。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "怪怪的", "label": "重叠"}], "register": "口语", "sense_fingerprint": "不一般，让人有点害怕或不安", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14cca9b8-8933-4231-8bfa-84367bc59d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87973, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "怪", "is_correct": true, "explanation": "正确答案：怪（guài，第四声），意思是不一般、让人有点害怕。"}, {"text": "快", "is_correct": false, "explanation": "kuài 与 guài 声母不同（k 与 g，送气与否），意思是快。"}, {"text": "拐", "is_correct": false, "explanation": "guǎi（第三声）与 guài（第四声）声调不同，意思是拐弯。"}, {"text": "挂", "is_correct": false, "explanation": "guà 与 guài 韵母不同（a 与 ai），意思是挂起来。"}, {"text": "贵", "is_correct": false, "explanation": "guì 与 guài 韵母不同（i 与 ai），意思是价格高。"}], "explanations": {"怪": "正确答案：怪（guài，第四声），意思是不一般、让人有点害怕。", "快": "kuài 与 guài 声母不同（k 与 g，送气与否），意思是快。", "拐": "guǎi（第三声）与 guài（第四声）声调不同，意思是拐弯。", "挂": "guà 与 guài 韵母不同（a 与 ai），意思是挂起来。", "贵": "guì 与 guài 韵母不同（i 与 ai），意思是价格高。"}, "sentence_index": null, "correct_answer": "怪"}, "level_3": {"options": [{"text": "怪", "is_correct": true, "explanation": "正确答案：“怪”指不一般、让人害怕，可以修饰“影子”。"}, {"text": "亮", "is_correct": false, "explanation": "语义：半夜里窗外光线暗，“亮”与“半夜”的情境相矛盾。"}, {"text": "红", "is_correct": false, "explanation": "体貌：影子是暗色的轮廓，不用“红”来描写。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”描述人的感受，不能用来修饰影子。"}], "explanations": {"怪": "正确答案：“怪”指不一般、让人害怕，可以修饰“影子”。", "亮": "语义：半夜里窗外光线暗，“亮”与“半夜”的情境相矛盾。", "红": "体貌：影子是暗色的轮廓，不用“红”来描写。", "饿": "语义：“饿”描述人的感受，不能用来修饰影子。"}, "sentence_index": 0, "correct_answer": "怪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这学期他的进步很怪，老师都为他高兴。", "explanation": "这里应该用〈惊人〉。怪指不一般、让人觉得奇怪，不用来形容进步的程度；赞叹进步要用惊人。"}, {"text": "这座大桥很怪，大家都赞叹它的气势。", "explanation": "这里应该用〈雄伟〉。怪只表示不寻常、让人觉得奇怪，不表示壮观、令人敬佩；赞叹建筑的气势要用雄伟。"}, {"text": "这个女孩长得很怪，大家都夸她有气质。", "explanation": "这里应该用〈漂亮〉。怪指不寻常、让人觉得奇怪，形容外貌好看要用漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used =