INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87975, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "航行是船在水上走，或者飞机在天上飞。", "primary_collocate": null, "pronunciation": "háng xíng", "ipa": "xɑŋ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这条船在海上航行了三天。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在高高的天上航行，很平稳。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船在河里慢慢航行。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长说，明天天气好，可以出海航行。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大海上风很大，船不能航行。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐船沿着长江航行到上海。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河很浅，大船没法航行。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海上航行过一个月。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那艘船正航行着，突然下起大雨。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，船在黑黑的海上航行，只有灯亮着。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "航行了", "label": "完成体"}, {"form": "航行着", "label": "持续体"}, {"form": "航行过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "船在水上走或飞机在天上飞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d23fd0e-84cc-4b7b-8d40-c450f027c617') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87975, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航行", "is_correct": true, "explanation": "正确：航行，船在水上行进，与“在海上”“三天”相符。"}, {"text": "飞", "is_correct": false, "explanation": "搭配：“飞”指鸟或飞机在空中移动，船不能飞。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是人走着消遣，船不能散步。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是人或动物休息，船不会睡觉。"}], "explanations": {"航行": "正确：航行，船在水上行进，与“在海上”“三天”相符。", "飞": "搭配：“飞”指鸟或飞机在空中移动，船不能飞。", "散步": "语义：散步是人走着消遣，船不能散步。", "睡觉": "语义：睡觉是人或动物休息，船不会睡觉。"}, "sentence_index": 0, "correct_answer": "航行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车在高速公路上航行，速度很快。", "explanation": "这里应该用〈行驶〉。航行只用于船或飞机，汽车在路上移动要用行驶。"}, {"text": "我一个人在山路上航行，走了很久。", "explanation": "这里应该用〈行走〉。航行指船或飞机的行进，人在路上走要用行走。"}, {"text": "小鸟在树林上空航行，叫声很好听。", "explanation": "这里应该用〈飞翔〉。航行指船或飞机的行进，鸟在空中飞要用飞翔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87975, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航行", "is_correct": true, "explanation": "正确：航行，船在水上行进，与“没法”和“大船”相符。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“跳舞”要求人或动物，大船不能跳舞。"}, {"text": "打电话", "is_correct": false, "explanation": "语义：大船不会打电话，与句意不合。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”的主体是人，大船不能唱歌。"}], "explanations": {"航行": "正确：航行，船在水上行进，与“没法”和“大船”相符。", "跳舞": "搭配：“跳舞”要求人或动物，大船不能跳舞。", "打电话": "语义：大船不会打电话，与句意不合。", "唱歌": "搭配：“唱歌”的主体是人，大船不能唱歌。"}, "sentence_index": 6, "correct_answer": "航行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这列火车在铁轨上航行，很准时。", "explanation": "这里应该用〈运行〉。航行只用于船或飞机，火车在轨道上行进要用运行。"}, {"text": "孩子们在草地上航行，玩得很开心。", "explanation": "这里应该用〈奔跑〉。航行只用于船或飞机，人在地上跑要用奔跑。"}, {"text": "这只猫在屋顶上航行，动作很轻。", "explanation": "这里应该用〈跳跃〉。航行指船或飞机的行进，猫在屋顶上跳要用跳跃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这艘渔船昨天在湖面上航行着两个小时。", "corrected_sentence": "这艘渔船昨天在湖面上航行了两个小时。", "error_description": "体标用错：昨天已经完成的一段时间要用完成体“了”，说“航行了两个小时”；持续体“着”不能带时段表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没在北冰洋航行了。", "corrected_sentence": "他从来没在北冰洋航行过。", "error_description": "体标用错：“从来没”表示没有这种经历，应使用经历体“过”，说“没航行过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
