INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "船只在水上行驶或飞机在空中飞行。", "primary_collocate": null, "pronunciation": "háng xíng", "ipa": "xɑŋ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "轮船在大海里平稳地航行。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那架飞机已经航行了十个小时。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的人坐木船在海上航行很危险。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货船按时从港口出发，向北航行。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想坐船在湖上航行一次。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在云上航行，窗外很亮。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的船航行了一个星期才到岛上。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，小船只能慢慢航行。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘大船第一次出海航行，大家都很高兴。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长说，今晚船要在海上航行一夜。", "target_word": "航行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "航行了", "label": "完成体"}, {"form": "航行着", "label": "持续体"}, {"form": "航行过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "船只在水上行驶、飞机在空中飞行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d23fd0e-84cc-4b7b-8d40-c450f027c617') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航行", "is_correct": true, "explanation": "正确：航行，船在水上平稳行进，与“大海里”相符。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“跳舞”要求人或动物，轮船不能跳舞。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”的主体是人，轮船不能唱歌。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是人的消遣行为，轮船不能散步。"}], "explanations": {"航行": "正确：航行，船在水上平稳行进，与“大海里”相符。", "跳舞": "搭配：“跳舞”要求人或动物，轮船不能跳舞。", "唱歌": "搭配：“唱歌”的主体是人，轮船不能唱歌。", "散步": "语义：散步是人的消遣行为，轮船不能散步。"}, "sentence_index": 0, "correct_answer": "航行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "马在草原上航行，速度很快。", "explanation": "这里应该用〈奔跑〉。航行只用于船或飞机，马在草原上跑要用奔跑。"}, {"text": "小鱼在池塘里航行。", "explanation": "这里应该用〈游〉。航行指船或飞机的行进，鱼在水里游要用游。"}, {"text": "他每天沿着马路航行去上班。", "explanation": "这里应该用〈走路〉。航行只用于船或飞机，人在马路上去上班要用走路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航行", "is_correct": true, "explanation": "正确：航行，船只在水上行进，与“一个星期”和“到岛上”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：船不会睡觉，句意不通。"}, {"text": "上课", "is_correct": false, "explanation": "语义：船不能上课，与“到岛上”的行程无关。"}, {"text": "打球", "is_correct": false, "explanation": "搭配：“打球”的主体是人，船不能打球。"}], "explanations": {"航行": "正确：航行，船只在水上行进，与“一个星期”和“到岛上”相符。", "睡觉": "语义：船不会睡觉，句意不通。", "上课": "语义：船不能上课，与“到岛上”的行程无关。", "打球": "搭配：“打球”的主体是人，船不能打球。"}, "sentence_index": 6, "correct_answer": "航行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蚂蚁在地上航行。", "explanation": "这里应该用〈爬行〉。航行只用于船或飞机，蚂蚁在地上爬要用爬行。"}, {"text": "蝴蝶在花丛中航行。", "explanation": "这里应该用〈飞舞〉。航行指船或飞机的移动，蝴蝶在花丛中飞要用飞舞。"}, {"text": "部队在山路上航行。", "explanation": "这里应该用〈前进〉。航行只指船或飞机，部队在陆地行进要用前进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "游船正航行过，窗外的风很大。", "corrected_sentence": "游船正航行着，窗外的风很大。", "error_description": "“过”用错：“正”表示动作正在进行，应使用持续体“着”，写作“正航行着”；经历体“过”不能与“正”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支船队曾航行着北极海域。", "corrected_sentence": "这支船队曾航行过北极海域。", "error_description": "“着”用错：“曾”表示过去的经历，应使用经历体“过”，写作“曾航行过”；持续体“着”表示动作正在进行，不能用于已经发生的经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87979, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": true, "explanation": "反义：“安静”指没有声音或声音很小，与“吵”（声音大而乱）相对。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”说卫生，与声音无关，不是“吵”的反义词。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”说空间大，与“吵”的声音义不相对。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”说光线，与“吵”的声音义不相对。"}], "correct_answer": "安静", "explanations": {"安静": "反义：“安静”指没有声音或声音很小，与“吵”（声音大而乱）相对。", "干净": "“干净”说卫生，与声音无关，不是“吵”的反义词。", "宽敞": "“宽敞”说空间大，与“吵”的声音义不相对。", "明亮": "“明亮”说光线，与“吵”的声音义不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87979, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": true, "explanation": "反义：“安静”指没有声音或声音很小，与“吵”（声音大而乱）相对。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”说排列有序，与声音无关，不是“吵”的反义词。"}, {"text": "清爽", "is_correct": false, "explanation": "“清爽”说感觉干净舒服，与声音无关。"}, {"text": "平整", "is_correct": false, "explanation": "“平整”说表面不起伏，与声音无关。"}], "correct_answer": "安静", "explanations": {"安静": "反义：“安静”指没有声音或声音很小，与“吵”（声音大而乱）相对。", "整齐": "“整齐”说排列有序，与声音无关，不是“吵”的反义词。", "清爽": "“清爽”说感觉干净舒服，与声音无关。", "平整": "“平整”说表面不起伏，与声音无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87979, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "吵是声音很大、很乱，让人觉得烦。", "primary_collocate": null, "pronunciation": "chǎo", "ipa": "tʂʰaʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个房间太吵了，我睡不着。", "target_word": "吵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路边的房子很吵，晚上我不开窗。", "target_word": "吵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里太吵了，老师听不见学生说话。", "target_word": "吵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼下的音乐很吵，我没法儿学习。", "target_word": "吵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆人多，又吵又热。", "target_word": "吵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢吵的地方，想找个安静的地方。", "target_word": "吵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都在玩儿，家里真吵。", "target_word": "吵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁里人很多，说话声也很吵。", "target_word": "吵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工地上的机器声很吵，工人都戴着耳罩。", "target_word": "吵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧里音乐声很大，我觉得有点儿吵。", "target_word": "吵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吵闹", "label": "复合词"}, {"form": "吵吵闹闹", "label": "重叠"}], "register": "口语", "sense_fingerprint": "声音大而乱、让人心烦的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19caa3-16e4-4fcd-a031-4c3dbc5187f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87979, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吵", "is_correct": true, "explanation": "正确答案：吵 chǎo，声音大而乱、让人烦。"}, {"text": "超", "is_correct": false, "explanation": "chāo（第一声）与 chǎo（第三声）声调不同，意思是超过。"}, {"text": "潮", "is_correct": false, "explanation": "cháo（第二声）与 chǎo（第三声）声调不同，意思是潮水。"}, {"text": "草", "is_correct": false, "explanation": "cǎo 与 chǎo 声母不同（c 与 ch），意思是草。"}], "explanations": {"吵": "正确答案：吵 chǎo，声音大而乱、让人烦。", "超": "chāo（第一声）与 chǎo（第三声）声调不同，意思是超过。", "潮": "cháo（第二声）与 chǎo（第三声）声调不同，意思是潮水。", "草": "cǎo 与 chǎo 声母不同（c 与 ch），意思是草。"}, "sentence_index": null, "correct_answer": "吵"}, "level_3": {"options": [{"text": "吵", "is_correct": true, "explanation": "正确：“吵”指声音杂乱、让人烦，与“睡不着”的原因相符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，房间不能是甜的，句子说不通。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地，不能用来形容房间。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，房间不能是慢的，句子说不通。"}], "explanations": {"吵": "正确：“吵”指声音杂乱、让人烦，与“睡不着”的原因相符。", "甜": "语义：“甜”说味道，房间不能是甜的，句子说不通。", "软": "搭配：“软”说质地，不能用来形容房间。", "慢": "语义：“慢”说速度，房间不能是慢的，句子说不通。"}, "sentence_index": 0, "correct_answer": "吵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天的阳光很吵，照在身上很暖和。", "explanation": "这里应该用〈温暖〉。“吵”只形容声音杂乱、让人烦，阳光要用“温暖”来形容。"}, {"text": "这首摇篮曲很吵，宝宝很快就睡着了。", "explanation": "这里应该用〈轻柔〉。摇篮曲要轻柔，“吵”指杂乱、让人烦的声音，不能用来形容摇篮曲。"}, {"text": "今天的天气很吵，我们都不想出门。", "explanation": "这里应该用〈闷热〉。“吵”只形容声音，天气闷热要用“闷热”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87979, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吵", "is_correct": true, "explanation": "正确答案：吵 chǎo，声音大而乱、让人烦。"}, {"text": "抄", "is_correct": false, "explanation": "chāo（第一声）与 chǎo（第三声）声调不同，意思是抄写。"}, {"text": "朝", "is_correct": false, "explanation": "cháo（第二声）与 chǎo（第三声）声调不同，意思是朝向。"}, {"text": "嘲", "is_correct": false, "explanation": "cháo（第二声）与 chǎo（第三声）声调不同，意思是嘲笑。"}], "explanations": {"吵": "正确答案：吵 chǎo，声音大而乱、让人烦。", "抄": "chāo（第一声）与 chǎo（第三声）声调不同，意思是抄写。", "朝": "cháo（第二声）与 chǎo（第三声）声调不同，意思是朝向。", "嘲": "cháo（第二声）与 chǎo（第三声）声调不同，意思是嘲笑。"}, "sentence_index": null, "correct_answer": "吵"}, "level_3": {"options": [{"text": "吵", "is_correct": true, "explanation": "正确：“吵”指声音杂乱、让人烦，与“家里真”后面的语境相符。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”说形状，“家里真圆”说不通，也和孩子们玩儿无关。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”说质地，不能用来形容家里的情况。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写人的体形，不能用来形容家里的情况。"}], "explanations": {"吵": "正确：“吵”指声音杂乱、让人烦，与“家里真”后面的语境相符。", "圆": "语义：“圆”说形状，“家里真圆”说不通，也和孩子们玩儿无关。", "硬": "搭配：“硬”说质地，不能用来形容家里的情况。", "瘦": "体貌：“瘦”描写人的体形，不能用来形容家里的情况。"}, "sentence_index": 6, "correct_answer": "吵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的旋律很吵，听起来很舒服。", "explanation": "这里应该用〈优美〉。“吵”形容声音杂乱、让人烦，悦耳的旋律不能用“吵”。"}, {"text": "妈妈的声音很吵，让孩子觉得很温暖。", "explanation": "这里应该用〈亲切〉。“吵”指让人烦的杂乱声音，形容妈妈温暖的说话声要用“亲切”。"}, {"text": "这杯茶很吵，喝起来很舒服。", "explanation": "这里应该用〈清香〉。“吵”只形容声音，茶的香味要用“清香”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上的街上车很多，吵很。", "corrected_sentence": "晚上的街上车很多，很吵。", "error_description": "错误：“吵很”。正确：“很吵”。形容词作谓语时，程度副词“很”要放在形容词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的音乐吵了人头疼。", "corrected_sentence": "这家店的音乐吵得人头疼。", "error_description": "错误：“吵了人头疼”。正确：“吵得人头疼”。“吵”后面表示程度要用补语助词“得”，“了”表示完成，不能表示“吵”的程度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
