INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87981, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抱是用两只手臂把人或东西围在身前。", "primary_collocate": null, "pronunciation": "bào", "ipa": "pɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "她抱着一大束花走进来。", "target_word": "抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥把妹妹抱到床上。", "target_word": "抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗太重，我一个人抱不起来。", "target_word": "抱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师抱来一堆作业本。", "target_word": "抱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子伸出手，要妈妈抱。", "target_word": "抱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他抱着篮球跑回了家。", "target_word": "抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我抱了一个大西瓜回家。", "target_word": "抱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶笑着抱起了小孙子。", "target_word": "抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抱着一个大纸箱上了楼。", "target_word": "抱", "complexity_tier": "T3", "furigana": "tā bào zhe yí gè dà zhǐ xiāng shàng le lóu", "sentence_source": "generated"}, {"text": "天冷的时候，她抱着热水袋看书。", "target_word": "抱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抱了", "label": "体标"}, {"form": "抱着", "label": "体标"}, {"form": "抱过", "label": "体标"}, {"form": "抱抱", "label": "重叠"}], "register": "中性", "sense_fingerprint": "两臂把人或东西围在身前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc845970-b582-4cbd-8bfb-d42e50e4b40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87981, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抱", "is_correct": true, "explanation": "抱（bào）指两臂把人或东西围在身前，是正确答案。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 bào（第四声）声调不同，意思是包裹。"}, {"text": "保", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）声调不同，意思是保护。"}, {"text": "炮", "is_correct": false, "explanation": "pào 与 bào 声母不同（p 与 b），意思是大炮。"}, {"text": "到", "is_correct": false, "explanation": "dào 与 bào 声母不同（d 与 b），意思是到达。"}], "explanations": {"抱": "抱（bào）指两臂把人或东西围在身前，是正确答案。", "包": "bāo（第一声）与 bào（第四声）声调不同，意思是包裹。", "保": "bǎo（第三声）与 bào（第四声）声调不同，意思是保护。", "炮": "pào 与 bào 声母不同（p 与 b），意思是大炮。", "到": "dào 与 bào 声母不同（d 与 b），意思是到达。"}, "sentence_index": null, "correct_answer": "抱"}, "level_3": {"options": [{"text": "抱", "is_correct": true, "explanation": "抱：两臂围住一大束花，表示抱着花走进来，与句子相符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，与拿着花的动作不符，“咬着一大束花”不通。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚击打，不能用来拿花，句子读起来不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象要能入口，“吃着一大束花”搭配不通。"}], "explanations": {"抱": "抱：两臂围住一大束花，表示抱着花走进来，与句子相符。", "咬": "语义：咬是用牙齿夹住，与拿着花的动作不符，“咬着一大束花”不通。", "踢": "语义：踢是用脚击打，不能用来拿花，句子读起来不通。", "吃": "搭配：“吃”的对象要能入口，“吃着一大束花”搭配不通。"}, "sentence_index": 0, "correct_answer": "抱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他走过去把窗户抱上了，屋里一下子暗了下来。", "explanation": "这里应该用〈关〉。抱是用手臂围住人或物，关窗户要用关。"}, {"text": "他抱着我的手走过马路。", "explanation": "这里应该用〈拉〉。抱是用两臂把人或东西围在身前，只用手带着别人走要用拉或牵。"}, {"text": "我把书抱在桌上。", "explanation": "这里应该用〈放〉。抱要把东西拥在怀里，书放在桌上要用放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87981, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抱", "is_correct": true, "explanation": "抱（bào）指两臂把人或东西围在身前，是正确答案。"}, {"text": "饱", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）声调不同，意思是吃饱。"}, {"text": "泡", "is_correct": false, "explanation": "pào 与 bào 声母不同（p 与 b），意思是泡在水里。"}, {"text": "罩", "is_correct": false, "explanation": "zhào 与 bào 声母不同（zh 与 b），意思是罩子。"}, {"text": "帽", "is_correct": false, "explanation": "mào 与 bào 声母不同（m 与 b），意思是帽子。"}], "explanations": {"抱": "抱（bào）指两臂把人或东西围在身前，是正确答案。", "饱": "bǎo（第三声）与 bào（第四声）声调不同，意思是吃饱。", "泡": "pào 与 bào 声母不同（p 与 b），意思是泡在水里。", "罩": "zhào 与 bào 声母不同（zh 与 b），意思是罩子。", "帽": "mào 与 bào 声母不同（m 与 b），意思是帽子。"}, "sentence_index": null, "correct_answer": "抱"}, "level_3": {"options": [{"text": "抱", "is_correct": true, "explanation": "抱：两臂围住一个大西瓜，把它带回家，与句子相符。"}, {"text": "踩", "is_correct": false, "explanation": "语义：踩是用脚压，与把西瓜带回家的动作不符，句子读起来不通。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：吞要求能入口的食物，一整个大西瓜无法吞下，搭配不通。"}, {"text": "嚼", "is_correct": false, "explanation": "搭配：嚼只用于能放进嘴里的食物，“嚼一个大西瓜回家”搭配不通。"}], "explanations": {"抱": "抱：两臂围住一个大西瓜，把它带回家，与句子相符。", "踩": "语义：踩是用脚压，与把西瓜带回家的动作不符，句子读起来不通。", "吞": "搭配：吞要求能入口的食物，一整个大西瓜无法吞下，搭配不通。", "嚼": "搭配：嚼只用于能放进嘴里的食物，“嚼一个大西瓜回家”搭配不通。"}, "sentence_index": 6, "correct_answer": "抱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把画抱在墙上。", "explanation": "这里应该用〈挂〉。把画固定在墙上要用挂，抱是用手臂围住人或物。"}, {"text": "她抱开了门，走进房间。", "explanation": "这里应该用〈推〉。开门要用推，抱是用手臂围住人或物。"}, {"text": "妈妈抱了一个电话，问我吃饭了没有。", "explanation": "这里应该用〈打〉。打电话要用打，抱是用手臂围住人或物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把猫进抱了屋里。", "corrected_sentence": "他把猫抱进了屋里。", "error_description": "补语“进”应紧跟在“抱”之后，应说“抱进了”。“进抱”语序错误，应改为“抱进”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一把抱了起那只受伤的小狗。", "corrected_sentence": "我一把抱起了那只受伤的小狗。", "error_description": "“起”是补语，要紧跟在“抱”之后，且“了”放在“抱起”之后。“抱了起”语序错误，应改为“抱起了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
