INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87983, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "万难是特别特别难，几乎做不到。", "primary_collocate": null, "pronunciation": "wàn nán", "ipa": "wan˥˩ nan˧˥", "syllable_count": 2, "sentences": [{"text": "让他在一天内学会游泳，万难做到。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多钱，我们万难拿出来。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的要求太过分，我万难答应。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种说法太奇怪，大家万难相信。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间这么紧，今天万难完成。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经搬去国外，要让他回来参加会议，万难办到。", "target_word": "万难", "complexity_tier": "T3", "furigana": "tā yǐ jīng bān qù guó wài, yào ràng tā huí lái cān jiā huì yì, wàn nán bàn dào.", "sentence_source": "generated"}, {"text": "这样的条件，公司万难接受。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有地图，在这片深山里万难找到出路。", "target_word": "万难", "complexity_tier": "T3", "furigana": "méi yǒu dì tú, zài zhè piàn shēn shān lǐ wàn nán zhǎo dào chū lù.", "sentence_source": "generated"}, {"text": "路这么远，我们万难按时赶到。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情已经变成这样，万难再改。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排除万难", "label": "复合词"}, {"form": "万难从命", "label": "复合词"}], "register": "书面", "sense_fingerprint": "特别难，几乎做不到（常放在动词前，如万难答应）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87983, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "万难", "is_correct": true, "explanation": "正确答案。“万难”读作 wàn nán，这里表示几乎做不到。"}, {"text": "犯难", "is_correct": false, "explanation": "fàn（第四声）与 wàn（第四声）声母不同（f 与 w），意思是“感到为难、拿不定主意”。"}, {"text": "万年", "is_correct": false, "explanation": "nián 与 nán 韵母不同（多一个 i），意思是“很长的时间、永远”。"}, {"text": "万能", "is_correct": false, "explanation": "néng 与 nán 韵母不同（eng 与 an），意思是“什么都能做”。"}], "explanations": {"万难": "正确答案。“万难”读作 wàn nán，这里表示几乎做不到。", "犯难": "fàn（第四声）与 wàn（第四声）声母不同（f 与 w），意思是“感到为难、拿不定主意”。", "万年": "nián 与 nán 韵母不同（多一个 i），意思是“很长的时间、永远”。", "万能": "néng 与 nán 韵母不同（eng 与 an），意思是“什么都能做”。"}, "sentence_index": null, "correct_answer": "万难"}, "level_3": {"options": [{"text": "万难", "is_correct": true, "explanation": "正确答案。“万难做到”表示几乎做不到，符合“一天内学会游泳”的语境。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示反复、习惯性，与“一天内学会游泳”这种一次性事件不合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已完成，与“让他在一天内学会游泳”的假设语境冲突。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定词连用，不说“从来做到”。"}], "explanations": {"万难": "正确答案。“万难做到”表示几乎做不到，符合“一天内学会游泳”的语境。", "常常": "语义：“常常”表示反复、习惯性，与“一天内学会游泳”这种一次性事件不合。", "已经": "语义：“已经”表示已完成，与“让他在一天内学会游泳”的假设语境冲突。", "从来": "搭配：“从来”通常与否定词连用，不说“从来做到”。"}, "sentence_index": 0, "correct_answer": "万难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种说法比那种更万难相信。", "explanation": "这里应该用〈难〉。“万难”已表示几乎做不到，程度到顶，不能再用“更”作比较；比较应说“更难相信”。"}, {"text": "这种说法不万难相信，大家很快就接受了。", "explanation": "这里应该用〈不难〉。“万难”只用于肯定句，否定时应说“不难相信”或“很容易相信”。"}, {"text": "这个消息很万难相信，我们还是先别传了。", "explanation": "这里应该用〈难〉。“万难”已表示几乎做不到、程度到顶，前面不能再加“很”；把“万难”换成“难”，说“很难相信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万难", "is_correct": true, "explanation": "正确答案。“万难接受”表示几乎不能接受，符合“这样的条件”的语境。"}, {"text": "压根", "is_correct": false, "explanation": "搭配：“压根”通常与“不”连用，不说“压根接受”。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常需与“不”“没”连用，单用于“接受”之前不成立，不能填入此空。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示庆幸结果好，与“这样的条件”的苛刻语境不合。"}], "explanations": {"万难": "正确答案。“万难接受”表示几乎不能接受，符合“这样的条件”的语境。", "压根": "搭配：“压根”通常与“不”连用，不说“压根接受”。", "根本": "搭配：“根本”通常需与“不”“没”连用，单用于“接受”之前不成立，不能填入此空。", "幸好": "语义：“幸好”表示庆幸结果好，与“这样的条件”的苛刻语境不合。"}, "sentence_index": 6, "correct_answer": "万难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个女孩万难漂亮，大家都夸她。", "explanation": "这里应该用〈十分〉。“万难”表示几乎做不到，是否定性的，不能用来形容程度；形容很漂亮应说“十分漂亮”。"}, {"text": "他万难答应了我的要求，只用了三分钟。", "explanation": "这里应该用〈很快〉。“万难”表示几乎做不到，与“只用了三分钟”的迅速矛盾；说答应得快应说“很快”。"}, {"text": "得知考上大学的消息，他万难高兴，立刻打电话告诉了全家。", "explanation": "这里应该用〈万分〉。“万难”表示几乎做不到，不能形容高兴的程度；形容极度高兴应说“万分高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么多的作业，他很万难在一晚上做完。", "corrected_sentence": "这么多的作业，他万难在一晚上做完。", "error_description": "程度副词用错。“万难”已表示几乎做不到、程度到顶，前面不能再加“很”。应去掉“很”，说“他万难在一晚上做完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事已经定下来了，我们万难又改。", "corrected_sentence": "这件事已经定下来了，我们万难再改。", "error_description": "“再”和“又”用错了。这里说的是以后的动作，应用“再”；“又”只用于已经发生过的重复。应说“万难再改”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
