INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "各种各样的困难。", "primary_collocate": null, "pronunciation": "wàn nán", "ipa": "wan˥˩ nan˧˥", "syllable_count": 2, "sentences": [{"text": "他排除万难，终于把学校建起来了。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了见到家人，她排除万难赶回了老家。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要有决心，我们就能排除万难。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年轻人不怕万难，一直往山里走。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资源极度匮乏，但研究小组克服万难，完成了这项研究。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次远征途中，他们遭遇了万难，却始终没有退缩。", "target_word": "万难", "complexity_tier": "T3", "furigana": "zhè cì yuǎn zhēng tú zhōng, tā men zāo yù le wàn nán, què shǐ zhōng méi yǒu tuì suō.", "sentence_source": "generated"}, {"text": "面对万难，他从来没有想过放弃。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她带着孩子一路排除万难，来到了北京。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱和人都不够，他们还是克服了万难。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人告诉我们，做事要敢于面对万难。", "target_word": "万难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排除万难", "label": "复合词"}, {"form": "万难从命", "label": "复合词"}], "register": "书面", "sense_fingerprint": "极其困难，或指各种各样的困难（常见于排除万难）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87984, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "万难", "is_correct": true, "explanation": "正确答案。“万难”读作 wàn nán，意思是极其困难，或指各种困难。"}, {"text": "犯难", "is_correct": false, "explanation": "fàn（第四声）与 wàn（第四声）声母不同（f 与 w），意思是“感到为难、拿不定主意”，不是“极其困难”。"}, {"text": "万年", "is_correct": false, "explanation": "nián 与 nán 韵母不同（多一个 i），意思是“很长的时间、永远”。"}, {"text": "万能", "is_correct": false, "explanation": "néng 与 nán 韵母不同（eng 与 an），意思是“什么都能做”。"}], "explanations": {"万难": "正确答案。“万难”读作 wàn nán，意思是极其困难，或指各种困难。", "犯难": "fàn（第四声）与 wàn（第四声）声母不同（f 与 w），意思是“感到为难、拿不定主意”，不是“极其困难”。", "万年": "nián 与 nán 韵母不同（多一个 i），意思是“很长的时间、永远”。", "万能": "néng 与 nán 韵母不同（eng 与 an），意思是“什么都能做”。"}, "sentence_index": null, "correct_answer": "万难"}, "level_3": {"options": [{"text": "万难", "is_correct": true, "explanation": "正确答案。“排除”的对象是各种困难，“万难”指极其困难的障碍，句意通顺。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“排除”针对的是障碍，风景不是要排除的对象，与“建起学校”的语境不合。"}, {"text": "乐趣", "is_correct": false, "explanation": "搭配：“排除”多接障碍、困难，不说“排除乐趣”，应说“享受乐趣”。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚不是要排除的障碍，这句话无法理解。"}], "explanations": {"万难": "正确答案。“排除”的对象是各种困难，“万难”指极其困难的障碍，句意通顺。", "风景": "语义：“排除”针对的是障碍，风景不是要排除的对象，与“建起学校”的语境不合。", "乐趣": "搭配：“排除”多接障碍、困难，不说“排除乐趣”，应说“享受乐趣”。", "夜晚": "语义：夜晚不是要排除的障碍，这句话无法理解。"}, "sentence_index": 0, "correct_answer": "万难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这孩子的脾气万难，谁也拿他没办法。", "explanation": "这里不这么用。“万难”形容事情或任务极其困难，不用于形容性格；形容脾气执拗应说“固执”。"}, {"text": "会场里挤满了万难的听众。", "explanation": "这里应该用〈成千上万〉。“万难”指极其困难或各种困难，不表示数量众多；形容人多应说“成千上万”。"}, {"text": "这件事很万难，我们先去吃饭吧。", "explanation": "这里应该用〈困难〉。“万难”本身已表示程度极高，前面不能再加“很”；应说“这件事万难”或“这件事很困难”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万难", "is_correct": true, "explanation": "正确答案。“面对”的对象是困难，“万难”指极其困难的障碍，符合句意。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天不是需要面对的对象，这句话意思不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“面对”可接事情、困难，但不说“面对心情”，与“从来没想过放弃”的语境不搭。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐不是需要面对并坚持到底的对象，句意不通。"}], "explanations": {"万难": "正确答案。“面对”的对象是困难，“万难”指极其困难的障碍，符合句意。", "春天": "语义：春天不是需要面对的对象，这句话意思不通。", "心情": "搭配：“面对”可接事情、困难，但不说“面对心情”，与“从来没想过放弃”的语境不搭。", "早餐": "语义：早餐不是需要面对并坚持到底的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "万难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试比上次更万难。", "explanation": "这里不这么用。“万难”本身已表示极度困难，程度已到顶，不能再用“更”比较；比较时应说“更困难”。"}, {"text": "他们为这项工作付出了很多万难。", "explanation": "这里应该用〈艰辛〉。“付出”搭配“艰辛、代价、心血”，“万难”指困难本身，不能被“付出”。"}, {"text": "这件事不万难，他一个小时就做完了。", "explanation": "这里应该用〈不难〉。“万难”只用于肯定句，表示极其困难；否定时应说“不难”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次登山，我们克服了一个万难，终于到达了山顶。", "corrected_sentence": "这次登山，我们克服了万难，终于到达了山顶。", "error_description": "错误在量词“一个”：“万难”指各种困难，是不可数的，不能用“个”计量。应说“克服了万难”，或说“克服了一个困难”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面对万难们，我们绝不退缩。", "corrected_sentence": "面对万难，我们绝不退缩。", "error_description": "错误在“们”：“们”只用于指人的词语，“万难”指困难，不能加“们”。应说“面对万难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
