INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87986, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市中面积较大的、供人们活动的开阔场地。", "primary_collocate": null, "pronunciation": "guǎng chǎng", "ipa": "kwɑŋ˨˩˦ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "市中心的广场每天都有很多游客。", "target_word": "广场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广场上正在举行一场音乐会。", "target_word": "广场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的中央广场很有名。", "target_word": "广场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在广场上办了一次市民活动。", "target_word": "广场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从酒店走到广场只要五分钟。", "target_word": "广场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广场四周种着很多树。", "target_word": "广场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年的晚上，人们聚在广场上倒数。", "target_word": "广场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广场是为市民修的。", "target_word": "广场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广场南边是市政府，北边是图书馆。", "target_word": "广场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站就在广场对面。", "target_word": "广场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "广场舞", "label": "复合"}, {"form": "廣場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "城市里供市民集会、活动的开阔场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43e9cbc-284b-4337-94c6-a22041e14477') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "广场", "is_correct": true, "explanation": "广场：“市中心的……每天都有很多游客”指可供游览的城市场地，正确。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是游客参观的地方，与句意矛盾。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌不供游客参观，与句意矛盾。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不是可以参观的场所，不能说“市中心的体重有游客”。"}], "explanations": {"广场": "广场：“市中心的……每天都有很多游客”指可供游览的城市场地，正确。", "冰箱": "语义：冰箱不是游客参观的地方，与句意矛盾。", "课桌": "语义：课桌不供游客参观，与句意矛盾。", "体重": "搭配：“体重”不是可以参观的场所，不能说“市中心的体重有游客”。"}, "sentence_index": 0, "correct_answer": "广场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个广场中间流着一条大河。", "explanation": "这里应该用〈河〉。有水流淌、长条形的水域说“河”，广场是供人活动的开阔场地。"}, {"text": "这个广场很大，里面种满了庄稼。", "explanation": "这里应该用〈农田〉。种庄稼的土地说“农田”，广场是城市里供人活动的空地。"}, {"text": "我们在广场里装了一台冰箱。", "explanation": "这里应该用〈厨房〉。广场是露天的空地，不能装冰箱，装设备应说“厨房”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "广场", "is_correct": true, "explanation": "广场：“聚在……上倒数”指聚在开阔的场地上，正确。"}, {"text": "电影院", "is_correct": false, "explanation": "配价：电影院用“里”，不用“上”，不能说“聚在电影院上”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：人不会聚在冰箱上倒数，与句意矛盾。"}, {"text": "信箱", "is_correct": false, "explanation": "语义：信箱不能供人聚集倒数，与句意矛盾。"}], "explanations": {"广场": "广场：“聚在……上倒数”指聚在开阔的场地上，正确。", "电影院": "配价：电影院用“里”，不用“上”，不能说“聚在电影院上”。", "冰箱": "语义：人不会聚在冰箱上倒数，与句意矛盾。", "信箱": "语义：信箱不能供人聚集倒数，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "广场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个广场很大，学生每天在这里上课。", "explanation": "这里应该用〈学校〉或〈教室〉。上课的地方说“学校”或“教室”，广场是供人活动的开阔场地。"}, {"text": "这个广场很大，沙子一望无际。", "explanation": "这里应该用〈沙漠〉。大片沙子覆盖的地方说“沙漠”，广场是城市里供人活动的开阔场地。"}, {"text": "这个广场很大，火车每分钟开过一趟。", "explanation": "这里应该用〈车站〉或〈铁路〉。火车经过、停靠的地方说“车站”或“铁路”，广场是供人活动的空地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋广场很大，市民们常来这里散步。", "corrected_sentence": "这座广场很大，市民们常来这里散步。", "error_description": "错误在量词。“广场”用“座”计量，不用“栋”；“栋”用于楼房。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去过一只广场。", "corrected_sentence": "我去过一座广场。", "error_description": "错误：“一只广场”；正确：“一座广场”。“广场”是大型场地，应用量词“座”，不用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
