INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "单车是有两个轮子、用脚蹬着走的车。", "primary_collocate": null, "pronunciation": "dān chē", "ipa": "tan˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "弟弟有一辆蓝色的单车。", "target_word": "单车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，爸爸教我骑单车。", "target_word": "单车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单车有两个轮子，不用油。", "target_word": "单车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一辆新单车。", "target_word": "单车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑单车骑得很快。", "target_word": "单车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我不能骑单车去学校。", "target_word": "单车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把单车借给了朋友。", "target_word": "单车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有人在租单车。", "target_word": "单车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的单车上有一个小篮子。", "target_word": "单车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑单车对身体很好。", "target_word": "单车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "單車", "label": "繁体"}, {"form": "共享单车", "label": "复合"}], "register": "口语", "sense_fingerprint": "单车：有两个轮子、用脚蹬着走的车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03c657c1-bea8-4c65-833c-a2de6b45be3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87987, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "搭配：“辆”用于车，不说“一辆蓝色的房子”。"}, {"text": "单车", "is_correct": true, "explanation": "正确答案。“单车”是一种车，用“辆”计量，与“弟弟有一辆蓝色的单车”相符。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不是车，“一辆蓝色的狗”不成立。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“辆”用于车，不说“一辆蓝色的书”。"}], "explanations": {"房子": "搭配：“辆”用于车，不说“一辆蓝色的房子”。", "单车": "正确答案。“单车”是一种车，用“辆”计量，与“弟弟有一辆蓝色的单车”相符。", "狗": "语义：狗不是车，“一辆蓝色的狗”不成立。", "书": "搭配：“辆”用于车，不说“一辆蓝色的书”。"}, "sentence_index": 0, "correct_answer": "单车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想买一本新单车。", "explanation": "这里应该用〈辆〉。“本”用于书册，单车不能用“本”。"}, {"text": "我想买一只新单车。", "explanation": "这里应该用〈辆〉。“只”用于动物或成对物品中的一个，单车要用“辆”。"}, {"text": "我想买一座新单车。", "explanation": "这里应该用〈辆〉。“座”用于山、桥、房屋等大型固定物，单车要用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不能借给别人，“把空气借给朋友”不成立。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子只是光照出的轮廓，不能借给别人。"}, {"text": "单车", "is_correct": true, "explanation": "正确答案。“单车”是可以借给别人的东西，与“我把单车借给了朋友”相符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“借”不与“年龄”搭配，“把年龄借给朋友”不成立。"}], "explanations": {"空气": "语义：空气是无形的气体，不能借给别人，“把空气借给朋友”不成立。", "影子": "语义：影子只是光照出的轮廓，不能借给别人。", "单车": "正确答案。“单车”是可以借给别人的东西，与“我把单车借给了朋友”相符。", "年龄": "搭配：“借”不与“年龄”搭配，“把年龄借给朋友”不成立。"}, "sentence_index": 6, "correct_answer": "单车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天骑着一块单车上学。", "explanation": "这里应该用〈辆〉。“块”用于块状物，单车不用“块”。"}, {"text": "教室门口停着一条单车。", "explanation": "这里应该用〈辆〉。“条”用于细长的东西，单车要用“辆”。"}, {"text": "院子里放着一张单车。", "explanation": "这里应该用〈辆〉。“张”用于平面的东西，单车要用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟有一只新单车。", "corrected_sentence": "弟弟有一辆新单车。", "error_description": "量词错误：单车应用量词“辆”，不用“只”。“一只新单车”应改为“一辆新单车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里停着一单车。", "corrected_sentence": "院子里停着一辆单车。", "error_description": "漏掉量词：“一”后面的名词“单车”需要量词“辆”，应说“一辆单车”，不说“一单车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
