INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87990, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到外地游览或办事。", "primary_collocate": null, "pronunciation": "lǚ xíng", "ipa": "/ly˨˩˦ ɕiŋ˧˥/", "syllable_count": 2, "sentences": [{"text": "他每年都去外地旅行。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算下个月去上海旅行。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她旅行了三天，才回家。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这次到外地旅行，顺便把工作办完了。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还没有去西藏旅行过。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐火车去北京旅行。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的时候，我喜欢拍照。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想和谁一起去旅行？", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢一个人旅行。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在南方旅行了一个星期，顺便办了事。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "旅行了", "label": "体标（完成）"}, {"form": "旅行过", "label": "体标（经历）"}, {"form": "旅行社", "label": "复合词"}, {"form": "旅行者", "label": "复合词"}], "register": "通用", "sense_fingerprint": "去外地游览或办事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e807c9-c27f-4438-82f2-649eff8684c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87990, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅行", "is_correct": true, "explanation": "正确。“去外地旅行”指到外地游览或办事，与句中的“去外地”和“每年”相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病是身体状况，不是去外地要做的事，句子说的是每年去外地做什么。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生只发生一次，不能说每年都去外地出生。"}, {"text": "离开", "is_correct": false, "explanation": "配价：“离开”必须说明离开的处所，单说“去外地离开”宾语缺失，意思不完整。"}], "explanations": {"旅行": "正确。“去外地旅行”指到外地游览或办事，与句中的“去外地”和“每年”相符。", "生病": "语义：生病是身体状况，不是去外地要做的事，句子说的是每年去外地做什么。", "出生": "语义：出生只发生一次，不能说每年都去外地出生。", "离开": "配价：“离开”必须说明离开的处所，单说“去外地离开”宾语缺失，意思不完整。"}, "sentence_index": 0, "correct_answer": "旅行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚饭后去公园旅行。", "explanation": "这里应该用〈散步〉。旅行指到外地去游览或办事，距离远、时间长；家附近公园里的短时间活动要说“散步”。"}, {"text": "我每天在公司旅行。", "explanation": "这里应该用〈上班〉。旅行要离开居住地到外地去，每天在公司工作不能说“旅行”。"}, {"text": "我每天晚上在家旅行。", "explanation": "这里应该用〈睡觉〉。旅行要离开家到外地去，晚上在家休息不能说“旅行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅行", "is_correct": true, "explanation": "正确。“旅行的时候”指出游期间，与句中的“拍照”语境相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试期间一般不能随意拍照，“考试的时候我喜欢拍照”与句子的出游语境不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时不能拍照，句子说的是一段边玩边拍照的时间。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡时不能随意拍照，与句中边玩边拍照的出游语境不合。"}], "explanations": {"旅行": "正确。“旅行的时候”指出游期间，与句中的“拍照”语境相符。", "考试": "语义：考试期间一般不能随意拍照，“考试的时候我喜欢拍照”与句子的出游语境不合。", "睡觉": "语义：睡觉时不能拍照，句子说的是一段边玩边拍照的时间。", "洗澡": "语义：洗澡时不能随意拍照，与句中边玩边拍照的出游语境不合。"}, "sentence_index": 6, "correct_answer": "旅行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每次感冒都去医院旅行。", "explanation": "这里应该用〈看病〉。旅行指到外地游览或办事，去医院看病是本地的事，不能说“旅行”。"}, {"text": "她住院的时候，每天在病房里旅行。", "explanation": "这里应该用〈休息〉。旅行指到外地游览或办事，病房里的日常休息不能说“旅行”。"}, {"text": "我在教室里旅行，听老师讲课。", "explanation": "这里应该用〈上课〉。旅行指到外地游览或办事，在教室听课要说“上课”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上个月去上海旅行着。", "corrected_sentence": "他上个月去上海旅行了。", "error_description": "体标错误：“上个月”说明旅行已经完成，“旅行”后面应该用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想北京旅行。", "corrected_sentence": "他想去北京旅行。", "error_description": "错误：漏了“去”。“旅行”是不及物动词，去某地要先用“去”引出地点，应说“去北京旅行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
